"""WHAT IF YOU WERE THE ONLY MAN ALIVE? - PART 2
A fully code-generated, cinematic 3D YouTube Short (1080x1920, 30 fps, 30.0 s), continuing Part 1. You are the only man
alive, and now the entire world is looking for you: a giant screen switches on with your face, the news, the crowds,
governments and scientists all want answers. A black government car takes you to an enormous research facility, where
a timeline shows billions vanishing at the same instant - and your photo, highlighted. The scientist turns, the lights
dim, a symbol nobody understands appears, the picture glitches: PART 3?

Everything is generated by this Blender (bpy) script: the procedural people (build_human, the same builder and the same
main character as Part 1: sculpted head, eyes, lids, lips with expressions, strand hair, subsurface skin, clothes and
hands), instanced crowds of the same people, the street and giant screen, the government car, a square of giant
screens, a newsroom, a situation room, a lab, the research facility (light lines, columns, walls of displays, a
holographic globe, a glass research room with a timeline wall), lighting, cameras (every shot moves), compositor grade,
synthesised music and sound design, the edit (titles, glitches, key captions, word-by-word captions, grain, vignette)
and the MP4 encode. Screen graphics come from tools/textures.py; his portrait on the screens is rendered by this script.

Accuracy notes (see sources.txt): the scenario is fiction and labelled on screen; the channel, people, places, figures
on the screens and the symbol are invented.

Run with Blender 4.2 LTS (headless):
  blender -b --factory-startup -P animation.py -- [options]

Stages (default: render):
  --stage render   build the 3D scene and render frames to renders/frames/
  --stage audio    synthesise music + sound design, mix with the narration (audio/*.wav, sound_design.txt)
  --stage edit     assemble frames, titles, key captions, captions, grain and audio in the Video Sequencer; encode
  --stage all      render + audio + edit

Options:
  --quality preview|final         preview = 270x480, 4 samples; final = 540x960, 6 samples (upscaled 2x in the edit)
  --frames A-B                    render only this frame range (resumable: existing frames are kept)
  --stills F1,F2,...              render single frames (look-dev checks)
  --out DIR                       frame folder (default renders/frames)
  --no-voice                      edit stage: leave the narration and captions out (to record your own voice)
  --output NAME                   edit stage: output file name
  --bitrate KBPS                  edit stage: video bitrate
  --save-blend PATH               also save the generated .blend

Collections: City (street, tower, giant screen, government car), Chars (the main character), Square, News, Lab, Sit
(situation room), Faci (the research facility), Flat (Part 1's flat, kept for the tower), Booth (portrait booth), FX,
Rig (cameras), Lights (sun), PeopleT (baked crowd people, instanced).
Timing comes from scene_timing.json (and build/vo_timing.json once tools/voiceover.py has run).
"""
import argparse
import json
import math
import os
import random
import subprocess
import sys
import wave

import bmesh
import bpy
import numpy as np
from mathutils import Matrix, Vector

ROOT = os.path.dirname(os.path.abspath(__file__))
BUILD = os.path.join(ROOT, 'build')
FONT_TITLE = os.path.join(ROOT, 'assets', 'fonts', 'Anton-Regular.ttf')
FONT_SERIF = os.path.join(ROOT, 'assets', 'fonts', 'OldStandard-Bold.ttf')
RES = (1080, 1920)
R = math.radians


# ============================================================================
# Arguments and timing
# ============================================================================
def parse_args():
    argv = sys.argv[sys.argv.index('--') + 1:] if '--' in sys.argv else []
    ap = argparse.ArgumentParser()
    ap.add_argument('--stage', default='render', choices=['render', 'audio', 'edit', 'all'])
    ap.add_argument('--quality', default='final', choices=['preview', 'final'])
    ap.add_argument('--frames', default=None)
    ap.add_argument('--stills', default=None)
    ap.add_argument('--out', default=os.path.join(ROOT, 'renders', 'frames'))
    ap.add_argument('--no-voice', action='store_true')
    ap.add_argument('--output', default=None)
    ap.add_argument('--save-blend', default=None)
    ap.add_argument('--bitrate', type=int, default=8000, help='edit stage: video kbit/s')
    return ap.parse_args(argv)


ARGS = parse_args()
with open(os.path.join(ROOT, 'scene_timing.json')) as _fh:
    TIMING = json.load(_fh)
FPS = TIMING['fps']
DURATION = TIMING['duration']
LAST_FRAME = round(DURATION * FPS)               # 900
RENDER_END = round(TIMING['render_end'] * FPS)
EV = TIMING['events']


def frame(t):
    """Seconds -> 1-based frame number."""
    return int(round(t * FPS)) + 1


def tsec(f):
    return (f - 1) / FPS


SHOTS = []
for _sc in TIMING['scenes']:
    for _sh in _sc['shots']:
        SHOTS.append(dict(name=_sh['name'], scene=_sc['id'], t0=_sh['start'], t1=_sh['end'],
                          f0=frame(_sh['start']), f1=frame(_sh['end']) - 1))
SHOTS[-1]['f1'] = RENDER_END
SHOT = {s['name']: s for s in SHOTS}


def shot_at(f):
    for s in SHOTS:
        if s['f0'] <= f <= s['f1']:
            return s
    return SHOTS[-1]


def smooth(x):
    x = min(max(x, 0.0), 1.0)
    return x * x * (3 - 2 * x)


def ramp(t, a, b):
    return smooth((t - a) / (b - a)) if b > a else float(t >= a)


def lin(t, a, b):
    return min(max((t - a) / (b - a), 0.0), 1.0) if b > a else float(t >= a)


def u_of(name, t):
    """0..1 progress of time t through a shot."""
    s = SHOT[name]
    return min(max((t - s['t0']) / (s['t1'] - s['t0']), 0.0), 1.0)


def lerp(a, b, u):
    return a + (b - a) * u


def vlerp(a, b, u):
    return Vector(a).lerp(Vector(b), u)


def path_at(pts, u):
    """Piecewise-linear interpolation along [(u, value), ...]."""
    if u <= pts[0][0]:
        return pts[0][1]
    for (u0, a), (u1, b) in zip(pts[:-1], pts[1:]):
        if u <= u1:
            k = (u - u0) / (u1 - u0) if u1 > u0 else 1.0
            if isinstance(a, (tuple, list, Vector)):
                return Vector(a).lerp(Vector(b), k)
            return a + (b - a) * k
    return pts[-1][1]


def hash01(a, b, salt=0.0):
    v = np.sin(a * 12.9898 + b * 78.233 + salt * 37.719) * 43758.5453
    return v - np.floor(v)


# ============================================================================
# Scene, render settings and small helpers
# ============================================================================
def reset_scene():
    bpy.ops.wm.read_factory_settings(use_empty=True)
    sc = bpy.context.scene
    sc.name = 'OnlyManPart2'
    sc.render.fps = FPS
    sc.frame_start, sc.frame_end = 1, RENDER_END
    sc.unit_settings.system = 'METRIC'
    return sc


SPP = [6]


def setup_render(sc):
    q = ARGS.quality
    r = sc.render
    r.engine = 'CYCLES'
    r.resolution_x, r.resolution_y = RES
    r.resolution_percentage = {'preview': 25, 'final': 50}[q]
    r.use_motion_blur = False
    r.use_persistent_data = True
    r.use_lock_interface = True
    r.use_overwrite = False
    r.use_placeholder = True
    r.image_settings.file_format = 'PNG'
    r.image_settings.color_mode = 'RGB'
    r.image_settings.color_depth = '8'
    c = sc.cycles
    c.device = 'CPU'
    c.samples = {'preview': 4, 'final': 6}[q]
    SPP[0] = c.samples
    c.use_adaptive_sampling = True
    c.adaptive_threshold = {'preview': 0.1, 'final': 0.05}[q]
    c.use_denoising = True
    c.denoiser = 'OPENIMAGEDENOISE'
    c.denoising_input_passes = 'RGB_ALBEDO_NORMAL'
    c.max_bounces, c.diffuse_bounces, c.glossy_bounces = 3, 1, 1
    c.transmission_bounces, c.transparent_max_bounces, c.volume_bounces = 2, 8, 0
    c.sample_clamp_indirect = 3.0
    c.caustics_reflective = c.caustics_refractive = False
    c.blur_glossy = 1.0
    c.filter_width = 1.5
    c.seed = 11
    c.use_animated_seed = False
    c.light_sampling_threshold = 0.02
    c.volume_step_rate = 4.0
    c.volume_max_steps = 64
    sc.view_settings.view_transform = 'AgX'
    sc.view_settings.look = 'AgX - Medium High Contrast'
    sc.view_layers[0].use_pass_mist = True


COLL = {}


def coll(name):
    if name not in COLL:
        c = bpy.data.collections.new(name)
        bpy.context.scene.collection.children.link(c)
        COLL[name] = c
    return COLL[name]


def template_collection(name):
    c = bpy.data.collections.new(name)
    bpy.context.scene.collection.children.link(c)
    bpy.context.view_layer.layer_collection.children[name].exclude = True
    COLL[name] = c
    return c


def link(ob, collection):
    coll(collection).objects.link(ob)
    return ob


def mesh_obj(name, verts, faces, mat=None, collection='World', smooth=True, loc=(0, 0, 0), uvs=None):
    me = bpy.data.meshes.new(name)
    me.from_pydata([tuple(v) for v in verts], [], [tuple(f) for f in faces])
    me.update()
    if uvs is not None:
        uvl = me.uv_layers.new(name='UVMap')
        uvl.data.foreach_set('uv', np.asarray(uvs, np.float32).ravel())
    if smooth:
        me.shade_smooth()
    ob = bpy.data.objects.new(name, me)
    ob.location = loc
    if mat is not None:
        for m in (mat if isinstance(mat, (list, tuple)) else [mat]):
            me.materials.append(m)
    coll(collection).objects.link(ob)
    return ob


def obj_from_bm(name, bm, mats=None, collection='World', smooth=False, loc=(0, 0, 0)):
    me = bpy.data.meshes.new(name)
    bm.to_mesh(me)
    bm.free()
    if smooth:
        me.shade_smooth()
    ob = bpy.data.objects.new(name, me)
    ob.location = loc
    if mats is not None:
        for m in (mats if isinstance(mats, (list, tuple)) else [mats]):
            me.materials.append(m)
    coll(collection).objects.link(ob)
    return ob


def _set_mi(bm, verts, mi):
    if not mi:
        return
    vs = set(verts)
    for f in bm.faces:
        if f.verts[0] in vs:
            f.material_index = mi


def add_box(bm, x0, y0, z0, x1, y1, z1, matrix=Matrix(), mi=0):
    m = matrix @ Matrix.Translation(((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2)) @ Matrix.Diagonal(
        (abs(x1 - x0), abs(y1 - y0), abs(z1 - z0), 1))
    r = bmesh.ops.create_cube(bm, size=1.0, matrix=m)
    _set_mi(bm, r['verts'], mi)


def add_cyl(bm, r1, r2, depth, seg=12, matrix=Matrix(), mi=0, caps=True):
    r = bmesh.ops.create_cone(bm, cap_ends=caps, cap_tris=False, segments=seg, radius1=r1, radius2=r2,
                              depth=depth, matrix=matrix)
    _set_mi(bm, r['verts'], mi)


def add_sphere(bm, r, u=12, v=8, matrix=Matrix(), mi=0):
    res = bmesh.ops.create_uvsphere(bm, u_segments=u, v_segments=v, radius=r, matrix=matrix)
    _set_mi(bm, res['verts'], mi)
    return res['verts']


def add_ellipsoid(bm, c, radii, u=16, v=10, mi=0, rot=Matrix()):
    m = Matrix.Translation(c) @ rot.to_4x4() @ Matrix.Diagonal((radii[0], radii[1], radii[2], 1))
    return add_sphere(bm, 1.0, u, v, m, mi)


def add_sbox(bm, c, half, e=0.3, u=16, v=10, mi=0, rot=Matrix()):
    """Rounded box (superellipsoid): e -> 0 is a sharp box, e = 1 an ellipsoid."""
    vs = add_sphere(bm, 1.0, u, v, Matrix(), mi)
    rm = rot.to_4x4() if rot.__class__ is Matrix and len(rot) == 3 else rot
    for vt in vs:
        p = vt.co
        q = Vector([math.copysign(abs(p[i]) ** e, p[i]) * half[i] for i in range(3)])
        vt.co = Matrix.Translation(c) @ rm @ q
    return vs


def seg_matrix(p0, p1):
    """Matrix mapping a unit cylinder along +Z centred at the origin onto segment p0-p1 (length via depth)."""
    p0, p1 = Vector(p0), Vector(p1)
    d = p1 - p0
    q = Vector((0, 0, 1)).rotation_difference(d.normalized())
    return Matrix.Translation((p0 + p1) / 2) @ q.to_matrix().to_4x4()


def add_capsule(bm, p0, p1, r0, r1=None, seg=10, mi=0, caps=True):
    r1 = r0 if r1 is None else r1
    p0, p1 = Vector(p0), Vector(p1)
    L = (p1 - p0).length
    add_cyl(bm, r0, r1, L, seg=seg, matrix=seg_matrix(p0, p1), mi=mi, caps=False)
    if caps:
        add_sphere(bm, r0, seg, max(4, seg // 2 + 1), Matrix.Translation(p0), mi)
        add_sphere(bm, r1, seg, max(4, seg // 2 + 1), Matrix.Translation(p1), mi)


def empty(name, loc=(0, 0, 0), collection='Rig', parent=None):
    e = bpy.data.objects.new(name, None)
    e.location = loc
    e.empty_display_size = 0.1
    coll(collection).objects.link(e)
    if parent is not None:
        e.parent = parent
    return e


def basis_matrix(o, r, u):
    o, r, u = Vector(o), Vector(r).normalized(), Vector(u).normalized()
    n = r.cross(u).normalized()
    return Matrix(((r.x, u.x, n.x, o.x), (r.y, u.y, n.y, o.y), (r.z, u.z, n.z, o.z), (0, 0, 0, 1)))


def card(name, mat, w, h, o, yaw=0.0, pitch=90.0, collection='World', seg=1):
    """A textured rectangle w x h, centred at o. pitch=90 stands it up facing -Y (rotated by yaw about Z)."""
    xs, ys = np.linspace(-w / 2, w / 2, seg + 1), np.linspace(-h / 2, h / 2, seg + 1)
    X, Y = np.meshgrid(xs, ys)
    verts = np.stack([X, Y, np.zeros_like(X)], -1).reshape(-1, 3)
    ii = np.arange((seg + 1) ** 2).reshape(seg + 1, seg + 1)
    faces = np.stack([ii[:-1, :-1], ii[:-1, 1:], ii[1:, 1:], ii[1:, :-1]], -1).reshape(-1, 4)
    uv = np.stack([(X + w / 2) / w, (Y + h / 2) / h], -1).reshape(-1, 2)
    loops = faces.ravel()
    ob = mesh_obj(name, verts, faces, mat, collection, smooth=False, uvs=uv[loops])
    ob.rotation_euler = (R(pitch), 0, R(yaw))
    ob.location = o
    return ob


# --- shader node helpers ---------------------------------------------------
def new_mat(name):
    m = bpy.data.materials.new(name)
    m.use_nodes = True
    nt = m.node_tree
    nt.nodes.clear()
    out = nt.nodes.new('ShaderNodeOutputMaterial')
    return m, nt, out


def nd(nt, kind, **inputs):
    n = nt.nodes.new(kind)
    for k, v in inputs.items():
        if k.startswith('p_'):
            setattr(n, k[2:], v)
        else:
            sock = n.inputs[k]
            if isinstance(v, bpy.types.NodeSocket):
                nt.links.new(v, sock)
            else:
                sock.default_value = v
    return n


def mth(nt, op, a, b=None, c=None, clamp=False):
    n = nt.nodes.new('ShaderNodeMath')
    n.operation = op
    n.use_clamp = clamp
    for i, v in enumerate((a, b, c)):
        if v is None:
            continue
        if isinstance(v, bpy.types.NodeSocket):
            nt.links.new(v, n.inputs[i])
        else:
            n.inputs[i].default_value = v
    return n.outputs[0]


def mixc(nt, fac, a, b):
    n = nt.nodes.new('ShaderNodeMix')
    n.data_type = 'RGBA'
    for idx, v in ((0, fac), (6, a), (7, b)):
        if isinstance(v, bpy.types.NodeSocket):
            nt.links.new(v, n.inputs[idx])
        else:
            n.inputs[idx].default_value = v
    return n.outputs[2]


def rgba(c):
    return (c[0], c[1], c[2], 1.0)


def principled(nt, out, **kw):
    p = nt.nodes.new('ShaderNodeBsdfPrincipled')
    for k, v in kw.items():
        if isinstance(v, bpy.types.NodeSocket):
            nt.links.new(v, p.inputs[k])
        else:
            p.inputs[k].default_value = v
    if out is not None:
        nt.links.new(p.outputs[0], out.inputs['Surface'])
    return p


def noise(nt, scale, detail=2.0, rough=0.5, vec=None, out='Fac'):
    n = nd(nt, 'ShaderNodeTexNoise', Scale=scale, Detail=detail, Roughness=rough)
    if vec is not None:
        nt.links.new(vec, n.inputs['Vector'])
    return n.outputs[out]


def obj_coord(nt):
    return nd(nt, 'ShaderNodeTexCoord').outputs['Object']


def value(nt, name, v):
    n = nt.nodes.new('ShaderNodeValue')
    n.name = name
    n.outputs[0].default_value = v
    return n.outputs[0]


def sep(nt, vec):
    return nd(nt, 'ShaderNodeSeparateXYZ', Vector=vec)


def comb(nt, x, y, z):
    return nd(nt, 'ShaderNodeCombineXYZ', X=x, Y=y, Z=z).outputs[0]


def ramp_node(nt, fac, stops):
    r = nd(nt, 'ShaderNodeValToRGB', Fac=fac)
    els = r.color_ramp.elements
    while len(els) < len(stops):
        els.new(0.5)
    for el, (pos, col) in zip(els, stops):
        el.position = pos
        el.color = rgba(col) if len(col) == 3 else col
    return r.outputs['Color']


MAT = {}
SHOTVAL = {}          # material Value nodes keyed by name: set per shot (see apply_shot)


def register_value(mat, node_name, key):
    SHOTVAL.setdefault(key, []).append(mat.node_tree.nodes[node_name].outputs[0])


# ============================================================================
# Materials
# ============================================================================
TEX = os.path.join(BUILD, 'tex')


def ensure_textures():
    if not os.path.exists(os.path.join(TEX, 'symbol.png')):
        py = os.environ.get('SHORTS_PY', '/opt/shorts/venv/bin/python')
        subprocess.run([py, os.path.join(ROOT, 'tools', 'textures.py')], check=True)


def teximg(name):
    return bpy.data.images.load(os.path.join(TEX, name + '.png'), check_existing=True)


def simple_mat(name, color, rough=0.7, noise_amt=0.15, noise_scale=8.0, metal=0.0, coat=0.0, sheen=0.0,
               emission=None, estr=0.0, spec=0.5):
    m, nt, out = new_mat(name)
    n = noise(nt, noise_scale, 3.0, 0.55, vec=obj_coord(nt))
    base = mixc(nt, mth(nt, 'MULTIPLY', n, noise_amt), rgba(color), rgba([c * 0.55 for c in color]))
    p = principled(nt, out, **{'Base Color': base, 'Roughness': rough, 'Metallic': metal, 'Coat Weight': coat,
                               'Sheen Weight': sheen, 'Specular IOR Level': spec})
    if emission is not None:
        p.inputs['Emission Color'].default_value = rgba(emission)
        p.inputs['Emission Strength'].default_value = estr
    MAT[name] = m
    return m


def flat_mat(name, color, rough=0.6, metal=0.0, spec=0.5, coat=0.0):
    m, nt, out = new_mat(name)
    principled(nt, out, **{'Base Color': rgba(color), 'Roughness': rough, 'Metallic': metal, 'Specular IOR Level': spec,
                           'Coat Weight': coat})
    MAT[name] = m
    return m


def emission_mat(name, color, strength, key=None):
    m, nt, out = new_mat(name)
    s = value(nt, key, strength) if key else strength
    e = nd(nt, 'ShaderNodeEmission', Color=rgba(color), Strength=s)
    nt.links.new(e.outputs[0], out.inputs['Surface'])
    MAT[name] = m
    if key:
        register_value(m, key, key)
    return m


def image_mat(name, tex, rough=0.6, glow=0.0, back=None, alpha=False, spec=0.4, proj=None, scale=1.0):
    """Image-textured material. back = colour shown on back faces (cards, tags)."""
    m, nt, out = new_mat(name)
    t = nd(nt, 'ShaderNodeTexImage', p_image=teximg(tex), p_interpolation='Linear', p_extension='REPEAT' if proj else 'EXTEND')
    if proj == 'BOX':
        t.projection = 'BOX'
        t.projection_blend = 0.3
        v = nd(nt, 'ShaderNodeVectorMath', p_operation='SCALE', Vector=obj_coord(nt))
        v.inputs['Scale'].default_value = scale
        nt.links.new(v.outputs[0], t.inputs['Vector'])
    col = t.outputs['Color']
    if back is not None:
        bf = nd(nt, 'ShaderNodeNewGeometry').outputs['Backfacing']
        col = mixc(nt, bf, col, rgba(back))
    p = principled(nt, out, **{'Base Color': col, 'Roughness': rough, 'Specular IOR Level': spec})
    if alpha:
        nt.links.new(t.outputs['Alpha'], p.inputs['Alpha'])
    if glow:
        nt.links.new(col, p.inputs['Emission Color'])
        p.inputs['Emission Strength'].default_value = glow
    MAT[name] = m
    return m


def volume_material(name, key, density, color, aniso):
    m, nt, out = new_mat(name)
    v = nd(nt, 'ShaderNodeVolumePrincipled', Color=rgba(color), Density=value(nt, key, density), Anisotropy=aniso)
    nt.links.new(v.outputs[0], out.inputs['Volume'])
    MAT[name] = m
    register_value(m, key, key)


def skin_mat(name, color):
    m, nt, out = new_mat(name)
    n = noise(nt, 40.0, 2.0, 0.5, vec=obj_coord(nt))
    base = mixc(nt, mth(nt, 'MULTIPLY', n, 0.12), rgba(color), rgba([c * 0.8 for c in color]))
    principled(nt, out, **{'Base Color': base, 'Roughness': 0.5, 'Subsurface Weight': 0.0, 'Specular IOR Level': 0.45,
                           'Coat Weight': 0.08, 'Coat Roughness': 0.4})
    MAT[name] = m
    return m


def cloth_mat(name, color, rough=0.85, weave=60.0):
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    w = nd(nt, 'ShaderNodeTexWave', Scale=weave, Distortion=0.0, Vector=oc, p_wave_type='BANDS').outputs['Fac']
    n = noise(nt, 6.0, 2.0, 0.5, vec=oc)
    f = mth(nt, 'ADD', mth(nt, 'MULTIPLY', w, 0.08), mth(nt, 'MULTIPLY', n, 0.18))
    base = mixc(nt, f, rgba(color), rgba([c * 0.6 for c in color]))
    principled(nt, out, **{'Base Color': base, 'Roughness': rough, 'Sheen Weight': 0.4, 'Specular IOR Level': 0.3})
    MAT[name] = m
    return m


def denim_mat(name, color):
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    w = nd(nt, 'ShaderNodeTexWave', Scale=140.0, Distortion=1.0, Vector=oc, p_wave_type='BANDS', p_bands_direction='DIAGONAL').outputs['Fac']
    n = noise(nt, 5.0, 3.0, 0.6, vec=oc)
    base = mixc(nt, mth(nt, 'ADD', mth(nt, 'MULTIPLY', w, 0.25), mth(nt, 'MULTIPLY', n, 0.3)), rgba(color),
                rgba([c * 1.5 for c in color]))
    principled(nt, out, **{'Base Color': base, 'Roughness': 0.9, 'Sheen Weight': 0.3, 'Specular IOR Level': 0.3})
    MAT[name] = m
    return m


def bill_material():
    m, nt, out = new_mat('bill')
    t = nd(nt, 'ShaderNodeTexImage', p_image=teximg('bill'), p_interpolation='Linear', p_extension='EXTEND')
    p = principled(nt, out, **{'Base Color': t.outputs['Color'], 'Roughness': 0.62, 'Specular IOR Level': 0.35,
                               'Sheen Weight': 0.2})
    # a little light through the thin paper
    tr = nd(nt, 'ShaderNodeBsdfTranslucent', Color=t.outputs['Color'])
    mx = nd(nt, 'ShaderNodeMixShader', Fac=0.18)
    nt.links.new(p.outputs[0], mx.inputs[1])
    nt.links.new(tr.outputs[0], mx.inputs[2])
    nt.links.new(mx.outputs[0], out.inputs['Surface'])
    MAT['bill'] = m


def stackedge_material():
    m, nt, out = new_mat('stackedge')
    oc = obj_coord(nt)
    z = sep(nt, oc).outputs['Z']
    lines = mth(nt, 'SINE', mth(nt, 'MULTIPLY', z, 2600.0))
    col = mixc(nt, mth(nt, 'MULTIPLY_ADD', lines, 0.25, 0.5), (0.70, 0.76, 0.66, 1), (0.52, 0.62, 0.50, 1))
    principled(nt, out, **{'Base Color': col, 'Roughness': 0.8})
    MAT['stackedge'] = m


def leaf_material(name, c0, c1, scale=3.0):
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    n = noise(nt, scale, 3.0, 0.6, vec=oc)
    col = ramp_node(nt, n, [(0.3, c0), (0.7, c1)])
    p = principled(nt, None, **{'Base Color': col, 'Roughness': 0.6, 'Specular IOR Level': 0.35, 'Sheen Weight': 0.3})
    tr = nd(nt, 'ShaderNodeBsdfTranslucent', Color=col)
    mx = nd(nt, 'ShaderNodeMixShader', Fac=0.25)
    nt.links.new(p.outputs[0], mx.inputs[1])
    nt.links.new(tr.outputs[0], mx.inputs[2])
    nt.links.new(mx.outputs[0], out.inputs['Surface'])
    MAT[name] = m


def bark_material():
    m, nt, out = new_mat('bark')
    oc = obj_coord(nt)
    w = nd(nt, 'ShaderNodeTexWave', Scale=3.0, Distortion=8.0, Detail=3.0, Vector=oc, p_wave_profile='SAW').outputs['Fac']
    n = noise(nt, 20.0, 3.0, 0.6, vec=oc)
    col = mixc(nt, mth(nt, 'MULTIPLY', w, n), (0.16, 0.11, 0.07, 1), (0.06, 0.04, 0.03, 1))
    principled(nt, out, **{'Base Color': col, 'Roughness': 0.9})
    MAT['bark'] = m


def ground_material(name, c0, c1, c2, scale=0.6, rough=0.9, fine=40.0):
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    n1 = noise(nt, scale, 4.0, 0.6, vec=oc)
    n2 = noise(nt, fine, 2.0, 0.6, vec=oc)
    col = ramp_node(nt, mth(nt, 'ADD', n1, mth(nt, 'MULTIPLY', n2, 0.25)), [(0.35, c0), (0.6, c1), (0.85, c2)])
    principled(nt, out, **{'Base Color': col, 'Roughness': rough, 'Specular IOR Level': 0.3})
    MAT[name] = m


def tile_floor_material():
    m, nt, out = new_mat('storefloor')
    oc = obj_coord(nt)
    ch = nd(nt, 'ShaderNodeTexChecker', Vector=oc, Scale=1.0, Color1=(0.62, 0.62, 0.58, 1), Color2=(0.50, 0.52, 0.50, 1))
    v = nd(nt, 'ShaderNodeVectorMath', p_operation='SCALE', Vector=oc)
    v.inputs['Scale'].default_value = 1.0 / 0.6
    nt.links.new(v.outputs[0], ch.inputs['Vector'])
    n = noise(nt, 3.0, 3.0, 0.6, vec=oc)
    col = mixc(nt, mth(nt, 'MULTIPLY', n, 0.25), ch.outputs['Color'], (0.35, 0.34, 0.30, 1))
    rough = mth(nt, 'MULTIPLY_ADD', n, 0.25, 0.12)
    principled(nt, out, **{'Base Color': col, 'Roughness': rough, 'Specular IOR Level': 0.5})
    MAT['storefloor'] = m


def facade_material(name, wall, glass, cols=3.2, rows=3.4, lit=0.0):
    """City building: a brick texture used as a window grid (bricks = windows, mortar = wall)."""
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    s = sep(nt, oc)
    # world-ish coordinate along the facade: x + y, height z
    v = comb(nt, mth(nt, 'ADD', s.outputs['X'], s.outputs['Y']), s.outputs['Z'], 0.0)
    b = nd(nt, 'ShaderNodeTexBrick', Vector=v, Scale=1.0, p_offset=0.0, p_offset_frequency=1, Color1=rgba(glass),
           Color2=rgba([c * 0.8 for c in glass]), Mortar=rgba(wall), **{'Mortar Size': 0.9, 'Brick Width': cols, 'Row Height': rows,
                                                                       'Mortar Smooth': 0.0})
    isglass = mth(nt, 'LESS_THAN', b.outputs['Fac'], 0.5)
    n = noise(nt, 0.5, 2.0, 0.5, vec=oc)
    col = mixc(nt, mth(nt, 'MULTIPLY', n, 0.3), b.outputs['Color'], rgba([c * 0.7 for c in wall]))
    rough = mixc(nt, isglass, (0.85, 0.85, 0.85, 1), (0.12, 0.12, 0.12, 1))
    p = principled(nt, out, **{'Base Color': col, 'Roughness': sep(nt, rough).outputs['X'], 'Specular IOR Level': 0.5})
    if lit:
        r = noise(nt, 2.2, 0.0, 0.5, vec=oc)
        on = mth(nt, 'MULTIPLY', isglass, mth(nt, 'GREATER_THAN', r, 0.58))
        nt.links.new(comb(nt, mth(nt, 'MULTIPLY', on, 1.0), mth(nt, 'MULTIPLY', on, 0.8), mth(nt, 'MULTIPLY', on, 0.55)),
                     p.inputs['Emission Color'])
        p.inputs['Emission Strength'].default_value = lit
    MAT[name] = m


def siding_material(name, color):
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    z = sep(nt, oc).outputs['Z']
    w = mth(nt, 'FRACT', mth(nt, 'MULTIPLY', z, 1 / 0.2))
    sh = mth(nt, 'POWER', w, 3.0)
    col = mixc(nt, mth(nt, 'MULTIPLY', sh, 0.35), rgba(color), rgba([c * 0.55 for c in color]))
    principled(nt, out, **{'Base Color': col, 'Roughness': 0.6})
    MAT[name] = m


def plastic_film_material():
    m, nt, out = new_mat('film')
    tr = nd(nt, 'ShaderNodeBsdfTranslucent', Color=(0.9, 0.92, 0.9, 1))
    tp = nd(nt, 'ShaderNodeBsdfTransparent')
    gl = nd(nt, 'ShaderNodeBsdfGlossy', Roughness=0.25)
    a = nd(nt, 'ShaderNodeMixShader', Fac=0.55)
    nt.links.new(tp.outputs[0], a.inputs[1])
    nt.links.new(tr.outputs[0], a.inputs[2])
    b = nd(nt, 'ShaderNodeMixShader', Fac=0.15)
    nt.links.new(a.outputs[0], b.inputs[1])
    nt.links.new(gl.outputs[0], b.inputs[2])
    nt.links.new(b.outputs[0], out.inputs['Surface'])
    MAT['film'] = m


def eye_material():
    m, nt, out = new_mat('eyewhite')
    principled(nt, out, **{'Base Color': (0.9, 0.9, 0.88, 1), 'Roughness': 0.15, 'Coat Weight': 0.6, 'Coat Roughness': 0.05})
    MAT['eyewhite'] = m
    m, nt, out = new_mat('iris')
    principled(nt, out, **{'Base Color': (0.02, 0.015, 0.012, 1), 'Roughness': 0.1, 'Coat Weight': 1.0, 'Coat Roughness': 0.02})
    MAT['iris'] = m


def billboard_base(name):
    m, nt, out = new_mat(name)
    uv = nd(nt, 'ShaderNodeUVMap').outputs[0]
    sm = nd(nt, 'ShaderNodeVertexColor', p_layer_name='sm')
    scn = nd(nt, 'ShaderNodeSeparateColor', Color=sm.outputs['Color'])
    su = sep(nt, uv)
    du = mth(nt, 'SUBTRACT', su.outputs['X'], 0.5)
    dv = mth(nt, 'SUBTRACT', su.outputs['Y'], 0.5)
    r2 = mth(nt, 'MULTIPLY', mth(nt, 'ADD', mth(nt, 'MULTIPLY', du, du), mth(nt, 'MULTIPLY', dv, dv)), 4.0)
    return m, nt, out, su, scn, sm.outputs['Alpha'], r2


def particle_materials():
    for name, col0, col1 in (('mist', (0.62, 0.60, 0.56), (0.42, 0.42, 0.40)),
                             ('dust', (0.66, 0.56, 0.42), (0.46, 0.38, 0.28))):
        m, nt, out, su, scn, opac, r2 = billboard_base(name)
        seed, age = scn.outputs[0], scn.outputs[1]
        fall = mth(nt, 'POWER', mth(nt, 'SUBTRACT', 1.0, r2, clamp=True), 1.6)
        v = comb(nt, mth(nt, 'MULTIPLY_ADD', su.outputs['X'], 1.6, mth(nt, 'MULTIPLY', seed, 37.0)),
                 mth(nt, 'MULTIPLY_ADD', su.outputs['Y'], 1.6, mth(nt, 'MULTIPLY', seed, 11.0)),
                 mth(nt, 'MULTIPLY', age, 1.6))
        n = noise(nt, 2.0, 5.0, 0.6, vec=v)
        dens = mth(nt, 'MULTIPLY', fall, mth(nt, 'MULTIPLY_ADD', n, 2.2, -0.75, clamp=True))
        dens = mth(nt, 'MULTIPLY', dens, opac, clamp=True)
        col = mixc(nt, mth(nt, 'MULTIPLY', n, 0.6), col0 + (1,), col1 + (1,))
        lum = value(nt, 'mist_lum', 0.3)
        k = mth(nt, 'MULTIPLY', lum, mth(nt, 'MULTIPLY_ADD', su.outputs['Y'], 0.5, 0.75))
        lit = nd(nt, 'ShaderNodeMix', p_data_type='RGBA', p_blend_type='MULTIPLY', Factor=1.0)
        nt.links.new(col, lit.inputs[6])
        nt.links.new(comb(nt, k, k, k), lit.inputs[7])
        em = nd(nt, 'ShaderNodeEmission', Color=lit.outputs[2], Strength=1.0)
        tr = nd(nt, 'ShaderNodeBsdfTransparent')
        mx = nd(nt, 'ShaderNodeMixShader', Fac=dens)
        nt.links.new(tr.outputs[0], mx.inputs[1])
        nt.links.new(em.outputs[0], mx.inputs[2])
        nt.links.new(mx.outputs[0], out.inputs['Surface'])
        MAT[name] = m
        register_value(m, 'mist_lum', 'mist_lum')
    m, nt, out, su, scn, opac, r2 = billboard_base('dot')
    dens = mth(nt, 'POWER', mth(nt, 'SUBTRACT', 1.0, r2, clamp=True), 3.0)
    a = mth(nt, 'MULTIPLY', dens, opac, clamp=True)
    col = mixc(nt, scn.outputs[2], (1.0, 0.86, 0.62, 1), (1.0, 0.96, 0.86, 1))
    em = nd(nt, 'ShaderNodeEmission', Color=col, Strength=mth(nt, 'MULTIPLY', a, value(nt, 'dot_lum', 4.0)))
    tr = nd(nt, 'ShaderNodeBsdfTransparent')
    mx = nd(nt, 'ShaderNodeMixShader', Fac=mth(nt, 'MULTIPLY', a, 1.4, clamp=True))
    nt.links.new(tr.outputs[0], mx.inputs[1])
    nt.links.new(em.outputs[0], mx.inputs[2])
    nt.links.new(mx.outputs[0], out.inputs['Surface'])
    MAT['dot'] = m
    register_value(m, 'dot_lum', 'dot_lum')


# ============================================================================
# World (sky gradient + sun glow) and compositor (mist fog, sun beams, glow, grade)
# ============================================================================
SKY = {}


def build_world(sc):
    w = bpy.data.worlds.new('Sky')
    sc.world = w
    w.use_nodes = True
    nt = w.node_tree
    nt.nodes.clear()
    out = nt.nodes.new('ShaderNodeOutputWorld')
    gen = nd(nt, 'ShaderNodeTexCoord').outputs['Generated']
    z = sep(nt, gen).outputs['Z']
    up = mth(nt, 'POWER', mth(nt, 'MAXIMUM', z, 0.0), 0.35)
    hor = nd(nt, 'ShaderNodeRGB')
    hor.name = 'SkyHorizon'
    zen = nd(nt, 'ShaderNodeRGB')
    zen.name = 'SkyZenith'
    col = mixc(nt, up, hor.outputs[0], zen.outputs[0])
    sv = nd(nt, 'ShaderNodeCombineXYZ')
    sv.name = 'SunVec'
    dot = nd(nt, 'ShaderNodeVectorMath', p_operation='DOT_PRODUCT', Vector=gen)
    nt.links.new(sv.outputs[0], dot.inputs[1])
    g = mth(nt, 'POWER', mth(nt, 'MAXIMUM', dot.outputs['Value'], 0.0), 6.0)
    g2 = mth(nt, 'POWER', mth(nt, 'MAXIMUM', dot.outputs['Value'], 0.0), 200.0)
    gcol = nd(nt, 'ShaderNodeRGB')
    gcol.name = 'GlowCol'
    gamt = mth(nt, 'MULTIPLY', mth(nt, 'ADD', mth(nt, 'MULTIPLY', g, 0.6), mth(nt, 'MULTIPLY', g2, 1.5)), value(nt, 'SunGlow', 0.0))
    glow = nd(nt, 'ShaderNodeMix', p_data_type='RGBA', p_blend_type='MULTIPLY', Factor=1.0)
    nt.links.new(gcol.outputs[0], glow.inputs[6])
    nt.links.new(comb(nt, gamt, gamt, gamt), glow.inputs[7])
    add = nd(nt, 'ShaderNodeMix', p_data_type='RGBA', p_blend_type='ADD', Factor=1.0)
    nt.links.new(col, add.inputs[6])
    nt.links.new(glow.outputs[2], add.inputs[7])
    # soft high clouds: stretched noise above the horizon
    cv = nd(nt, 'ShaderNodeVectorMath', p_operation='MULTIPLY', Vector=gen)
    cv.inputs[1].default_value = (2.0, 2.0, 9.0)
    cn = noise(nt, 2.5, 6.0, 0.6, vec=cv.outputs[0])
    cl = mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', mth(nt, 'SUBTRACT', cn, 0.52, clamp=True), 2.5),
             mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', z, 0.02), value(nt, 'Clouds', 0.0)))
    ccol = nd(nt, 'ShaderNodeRGB')
    ccol.name = 'CloudCol'
    add2 = nd(nt, 'ShaderNodeMix', p_data_type='RGBA', p_blend_type='MIX', Factor=cl)
    nt.links.new(add.outputs[2], add2.inputs[6])
    nt.links.new(ccol.outputs[0], add2.inputs[7])
    bg = nd(nt, 'ShaderNodeBackground', Color=add2.outputs[2], Strength=1.0)
    nt.links.new(bg.outputs[0], out.inputs['Surface'])
    w.cycles.sampling_method = 'MANUAL'
    w.cycles.sample_map_resolution = 64
    SKY.update(bg=bg, hor=hor, zen=zen, sunvec=sv, glowcol=gcol, glow=nt.nodes['SunGlow'], clouds=nt.nodes['Clouds'], cloudcol=ccol)
    w.mist_settings.start = 20
    w.mist_settings.depth = 1500
    w.mist_settings.falloff = 'QUADRATIC'
    sun = bpy.data.lights.new('Sun', 'SUN')
    sun.angle = math.radians(1.5)
    so = bpy.data.objects.new('Sun', sun)
    so.rotation_mode = 'XYZ'
    coll('Lights').objects.link(so)
    SKY['sun'] = so


def sun_dir(elev, azim):
    e, a = math.radians(elev), math.radians(azim)
    return Vector((math.cos(e) * math.cos(a), math.cos(e) * math.sin(a), math.sin(e)))


def build_compositor(sc):
    sc.use_nodes = True
    nt = sc.node_tree
    nt.nodes.clear()

    def n(kind, **kw):
        x = nt.nodes.new(kind)
        for k, v in kw.items():
            setattr(x, k, v)
        return x
    rl = n('CompositorNodeRLayers')
    amt = n('CompositorNodeMath', operation='MULTIPLY', name='FogAmt')
    amt.inputs[0].default_value = 0.4
    nt.links.new(rl.outputs['Mist'], amt.inputs[1])
    fog = n('CompositorNodeMixRGB', blend_type='MIX', name='FogColor')
    nt.links.new(amt.outputs[0], fog.inputs[0])
    nt.links.new(rl.outputs['Image'], fog.inputs[1])
    bright = n('CompositorNodeRGBToBW')
    nt.links.new(fog.outputs[0], bright.inputs[0])
    thr = n('CompositorNodeMath', operation='SUBTRACT', use_clamp=True, name='BeamThr')
    thr.inputs[1].default_value = 0.75
    nt.links.new(bright.outputs[0], thr.inputs[0])
    beams = n('CompositorNodeSunBeams', name='Beams', ray_length=0.2)
    nt.links.new(thr.outputs[0], beams.inputs[0])
    bamt = n('CompositorNodeMath', operation='MULTIPLY', name='BeamAmt')
    bamt.inputs[0].default_value = 0.0
    nt.links.new(beams.outputs[0], bamt.inputs[1])
    tint = n('CompositorNodeMixRGB', blend_type='MULTIPLY', name='BeamTint')
    tint.inputs[0].default_value = 1.0
    tint.inputs[2].default_value = (1.0, 0.85, 0.6, 1)
    nt.links.new(bamt.outputs[0], tint.inputs[1])
    add = n('CompositorNodeMixRGB', blend_type='ADD')
    add.inputs[0].default_value = 1.0
    nt.links.new(fog.outputs[0], add.inputs[1])
    nt.links.new(tint.outputs[0], add.inputs[2])
    glare = n('CompositorNodeGlare', glare_type='FOG_GLOW', quality='HIGH', threshold=0.85, size=8, mix=-0.5, name='Glow')
    nt.links.new(add.outputs[0], glare.inputs[0])
    cb = n('CompositorNodeColorBalance', correction_method='LIFT_GAMMA_GAIN', name='Grade')
    nt.links.new(glare.outputs[0], cb.inputs[1])
    hsv = n('CompositorNodeHueSat', name='Sat')
    nt.links.new(cb.outputs[0], hsv.inputs['Image'])
    comp = n('CompositorNodeComposite')
    nt.links.new(hsv.outputs[0], comp.inputs[0])


# ============================================================================
# Mesh buffer (verts / faces / UVs / material indices) for textured props built with numpy
# ============================================================================
class Geo:
    def __init__(self):
        self.v, self.f, self.uv, self.mi = [], [], [], []

    def quad(self, pts, uvs=((0, 0), (1, 0), (1, 1), (0, 1)), mi=0):
        n = len(self.v)
        self.v += [tuple(p) for p in pts]
        self.f.append(tuple(range(n, n + len(pts))))
        self.uv += [tuple(u) for u in uvs]
        self.mi.append(mi)

    def box(self, c, half, mi=(0, 0, 0, 0, 0, 0), m=None):
        """Faces: +Z, -Z, -Y (front), +Y, +X, -X. mi: material index per face."""
        x, y, z = half
        P = [((-x, -y, z), (x, -y, z), (x, y, z), (-x, y, z)), ((-x, y, -z), (x, y, -z), (x, -y, -z), (-x, -y, -z)),
             ((-x, -y, -z), (x, -y, -z), (x, -y, z), (-x, -y, z)), ((x, y, -z), (-x, y, -z), (-x, y, z), (x, y, z)),
             ((x, -y, -z), (x, y, -z), (x, y, z), (x, -y, z)), ((-x, y, -z), (-x, -y, -z), (-x, -y, z), (-x, y, z))]
        if isinstance(mi, int):
            mi = (mi,) * 6
        for face, k in zip(P, mi):
            if k is None:
                continue
            pts = [Vector(p) for p in face]
            if m is not None:
                pts = [m @ p for p in pts]
            self.quad([Vector(c) + p for p in pts], mi=k)

    def cylinder(self, c, r, h, seg=16, mi_side=0, mi_cap=1, caps=True):
        cx, cy, cz = c
        for i in range(seg):
            a0, a1 = 2 * math.pi * i / seg, 2 * math.pi * (i + 1) / seg
            p = [(cx + r * math.cos(a0), cy + r * math.sin(a0), cz), (cx + r * math.cos(a1), cy + r * math.sin(a1), cz),
                 (cx + r * math.cos(a1), cy + r * math.sin(a1), cz + h), (cx + r * math.cos(a0), cy + r * math.sin(a0), cz + h)]
            # u wraps so that u = 0.5 faces -Y (the label front)
            u0, u1 = (a0 / (2 * math.pi) + 0.25) % 1.0, (a1 / (2 * math.pi) + 0.25) % 1.0
            if u1 < u0:
                u1 += 1.0
            self.quad(p, ((u0, 0), (u1, 0), (u1, 1), (u0, 1)), mi_side)
        if caps:
            for zz, rev in ((cz + h, False), (cz, True)):
                pts = [(cx + r * math.cos(2 * math.pi * i / seg), cy + r * math.sin(2 * math.pi * i / seg), zz) for i in range(seg)]
                if rev:
                    pts = pts[::-1]
                n = len(self.v)
                self.v += pts
                self.f.append(tuple(range(n, n + seg)))
                self.uv += [(0.5, 0.5)] * seg
                self.mi.append(mi_cap)

    def obj(self, name, mats, collection, smooth=False):
        loops = [i for f in self.f for i in f]
        uvs = np.array(self.uv, np.float32)
        ob = mesh_obj(name, self.v, self.f, mats, collection, smooth=smooth, uvs=uvs[np.array(loops, int)] if loops else None)
        ob.data.polygons.foreach_set('material_index', np.array(self.mi, np.int32))
        return ob


BILL = (0.156, 0.066)


def bill_quads(centres, U, V, size=BILL):
    """Corner positions (n,4,3) of quads at centres with unit long axis U and short axis V."""
    w, h = size[0] / 2, size[1] / 2
    c = np.asarray(centres)
    return np.stack([c - U * w - V * h, c + U * w - V * h, c + U * w + V * h, c - U * w + V * h], 1)


def quad_mesh(name, n, mat, collection):
    faces = np.arange(4 * n).reshape(n, 4)
    uv = np.tile(np.array([[0, 0], [1, 0], [1, 1], [0, 1]], np.float32), (n, 1))
    ob = mesh_obj(name, np.zeros((4 * n, 3)), faces, mat, collection, smooth=False, uvs=uv)
    return ob


def set_quads(ob, V):
    ob.data.vertices.foreach_set('co', np.asarray(V, np.float32).ravel())
    ob.data.update()


# ============================================================================
# Trees: procedural trunk and branches, leafy clumps, leaves, and hanging banknotes that sway
# ============================================================================
TREES = {}
_ICO = {}


def ico(sub=2):
    if sub not in _ICO:
        bm = bmesh.new()
        bmesh.ops.create_icosphere(bm, subdivisions=sub, radius=1.0)
        v = np.array([tuple(x.co) for x in bm.verts])
        f = [tuple(x.index for x in fc.verts) for fc in bm.faces]
        bm.free()
        _ICO[sub] = (v, f)
    return _ICO[sub]


def tree_skeleton(height, seed, spread=1.0):
    """Branch segments [(p0, p1, r0, r1)] and clumps [(centre, radius)] in tree-local coordinates."""
    rng = np.random.default_rng(seed)
    segs, clumps = [], []
    trunk_h = height * 0.42
    r_trunk = height * 0.035
    base = np.array([0.0, 0.0, 0.0])
    top = np.array([rng.normal(0, 0.03 * height), rng.normal(0, 0.03 * height), trunk_h])
    segs.append((base, top, r_trunk * 1.25, r_trunk))

    def grow(p, d, length, r, depth):
        q = p + d * length
        segs.append((p, q, r, r * 0.65))
        if depth == 0:
            clumps.append((q, length * 0.9 + height * 0.09))
            return
        k = 2 if depth > 1 else 3
        for i in range(k):
            a = rng.uniform(0, 2 * math.pi)
            nd_ = d + np.array([math.cos(a), math.sin(a), 0.0]) * rng.uniform(0.5, 0.9) * spread + np.array([0, 0, 0.35])
            nd_ /= np.linalg.norm(nd_)
            grow(q, nd_, length * rng.uniform(0.6, 0.78), r * 0.62, depth - 1)
        if depth == 1:
            clumps.append((q + np.array([0, 0, length * 0.2]), length * 0.8 + height * 0.06))
    nb = 4
    for i in range(nb):
        a = 2 * math.pi * i / nb + rng.normal(0, 0.3)
        d = np.array([math.cos(a) * 0.75 * spread, math.sin(a) * 0.75 * spread, 0.85])
        d /= np.linalg.norm(d)
        grow(top, d, height * 0.24, r_trunk * 0.7, 2)
    clumps.append((top + np.array([0, 0, height * 0.42]), height * 0.2))
    return segs, clumps


def make_tree(name, collection, origin, height, seed, n_bills=600, n_leaves=1500, bill_scale=1.0, spread=1.0,
              leaf_mat='leaves', sway=True, bark_seg=8, clump_scale=1.0, hang_low=0.25):
    rng = np.random.default_rng(seed + 100)
    segs, clumps = tree_skeleton(height, seed, spread)
    clumps = [(c, r * clump_scale) for c, r in clumps]
    o = Vector(origin)
    bm = bmesh.new()
    for p0, p1, r0, r1 in segs:
        add_capsule(bm, p0, p1, r0, r1, seg=bark_seg, caps=False)
        add_sphere(bm, r1, bark_seg, 5, Matrix.Translation(Vector(p1)))
    trunk = obj_from_bm(name + '_trunk', bm, MAT['bark'], collection, smooth=True, loc=o)
    # clumps: displaced icospheres
    iv, iface = ico(2)
    V, Fc = [], []
    for k, (c, r) in enumerate(clumps):
        ph = rng.uniform(0, 10, 3)
        d = iv
        disp = 1.0 + 0.16 * np.sin(d @ np.array([5.1, 3.7, 4.3]) + ph[0]) + 0.12 * np.sin(d @ np.array([-3.3, 6.1, 2.7]) * 1.7 + ph[1])
        sq = np.array([1.0, 1.0, 0.78])
        V.append(c + d * (r * disp)[:, None] * sq)
        Fc += [tuple(i + k * len(iv) for i in f) for f in iface]
    leaves = mesh_obj(name + '_clumps', np.concatenate(V), Fc, MAT[leaf_mat], collection, smooth=True, loc=o)
    # leaf polygons on the clump surfaces
    if n_leaves:
        allc = np.array([c for c, r in clumps])
        allr = np.array([r for c, r in clumps])
        ci = rng.choice(len(clumps), n_leaves, p=allr ** 2 / (allr ** 2).sum())
        d = rng.normal(0, 1, (n_leaves, 3))
        d /= np.linalg.norm(d, axis=1)[:, None]
        pos = allc[ci] + d * allr[ci, None] * rng.uniform(0.92, 1.08, (n_leaves, 1)) * np.array([1, 1, 0.78])
        L = 0.09 * height / 6.0 + 0.04
        a = rng.normal(0, 1, (n_leaves, 3))
        U = np.cross(d, a)
        U /= np.linalg.norm(U, axis=1)[:, None]
        Vv = np.cross(d, U)
        tilt = d * 0.35
        Vv = Vv + tilt
        Vv /= np.linalg.norm(Vv, axis=1)[:, None]
        prof = [(0, 0), (0.25, 0.32), (0.55, 0.38), (0.8, 0.25), (1.0, 0.0)]
        pts = []
        for s, wv in prof:
            pts.append((s, wv))
        for s, wv in prof[-2:0:-1]:
            pts.append((s, -wv))
        npt = len(pts)
        verts = np.zeros((n_leaves, npt, 3))
        for j, (s, wv) in enumerate(pts):
            verts[:, j] = pos + U * (s * L) + Vv * (wv * L * 0.55)
        faces = [tuple(range(i * npt, (i + 1) * npt)) for i in range(n_leaves)]
        mesh_obj(name + '_leaves', verts.reshape(-1, 3), faces, MAT[leaf_mat], collection, smooth=False, loc=o)
    # hanging banknotes: anchored on the lower/outer part of the clumps
    info = None
    if n_bills:
        allc = np.array([c for c, r in clumps])
        allr = np.array([r for c, r in clumps])
        ci = rng.choice(len(clumps), n_bills, p=allr ** 2 / (allr ** 2).sum())
        az = rng.uniform(0, 2 * math.pi, n_bills)
        el = rng.uniform(-0.75, hang_low, n_bills)
        d = np.stack([np.cos(az) * np.cos(el), np.sin(az) * np.cos(el), np.sin(el)], 1)
        anchor = allc[ci] + d * allr[ci, None] * np.array([1, 1, 0.78]) * rng.uniform(0.95, 1.05, (n_bills, 1))
        face = az + rng.normal(0, 0.5, n_bills)                   # direction the note faces (horizontal)
        N = np.stack([np.cos(face), np.sin(face), np.zeros(n_bills)], 1)
        U = np.stack([-np.sin(face), np.cos(face), np.zeros(n_bills)], 1)
        hang = rng.normal(0, 0.25, n_bills)                       # rest tilt
        ob = quad_mesh(name + '_bills', n_bills, MAT['bill'], collection)
        ob.location = o
        info = dict(ob=ob, anchor=anchor, N=N, U=U, hang=hang, ph=rng.uniform(0, 6.3, n_bills),
                    fr=rng.uniform(1.2, 2.4, n_bills), size=(BILL[0] * bill_scale, BILL[1] * bill_scale), sway=sway, hidden=None)
        update_tree_bills(info, 0.0, 1.0)
    TREES[name] = dict(trunk=trunk, clumps=leaves, info=info, segs=segs, clumpdata=clumps, origin=o)
    return TREES[name]


def update_tree_bills(info, t, amp=1.0, hidden=None):
    """Each note hangs from its top edge and swings gently in the breeze."""
    sw = info['hang'] + (0.18 * amp * np.sin(info['fr'] * t + info['ph']) if info['sway'] else 0.0)
    N, U = info['N'], info['U']
    Z = np.array([0, 0, 1.0])
    D = -np.cos(sw)[:, None] * Z + np.sin(sw)[:, None] * N           # down the note
    w, h = info['size'][0] / 2, info['size'][1]
    a = info['anchor']
    V = np.stack([a - U * w + D * h, a + U * w + D * h, a + U * w, a - U * w], 1)
    if hidden is not None:
        V[hidden] = 0.0
    set_quads(info['ob'], V)


def tree_points(name, n, seed, lower=True):
    """Points on the canopy (world space) for falling-note emitters."""
    T = TREES[name]
    rng = np.random.default_rng(seed)
    cl = T['clumpdata']
    allc = np.array([c for c, r in cl])
    allr = np.array([r for c, r in cl])
    ci = rng.choice(len(cl), n)
    az = rng.uniform(0, 2 * math.pi, n)
    el = rng.uniform(-0.6, 0.1 if lower else 0.8, n)
    d = np.stack([np.cos(az) * np.cos(el), np.sin(az) * np.cos(el), np.sin(el)], 1)
    return np.array(T['origin']) + allc[ci] + d * allr[ci, None] * 0.95

# ============================================================================
# Characters: stylised, reusable, jointed figures with animated faces (eyes, lids, brows, shape-keyed mouth).
# Facing +Y. 'R' is the +X side, 'L' the -X side. Posed every frame by pose() from the frame handler.
# ============================================================================
CH = {}
HC = Vector((0, 0, 0.17))                   # head centre in neck-joint space
HEAD_R = (0.125, 0.13, 0.145)


def on_head(x, z, out=0.0):
    a, b, c = HEAD_R
    k = 1 - (x / a) ** 2 - (z / c) ** 2
    return HC + Vector((x, b * math.sqrt(max(k, 0.0)) + out, z))


def part(name, bm, mats, parent, collection, smooth=True, loc=(0, 0, 0)):
    ob = obj_from_bm(name, bm, mats, collection, smooth=smooth)
    ob.parent = parent
    ob.location = loc
    return ob


def hair_mesh(bm, style, mi=0):
    a, b, c = HEAD_R
    vs = add_ellipsoid(bm, HC, (a * 1.07, b * 1.07, c * 1.09), 24, 14, mi)
    kill = []
    for v in vs:
        p = v.co - HC
        y = p.y
        if style == 'bald':
            keep = -0.05 < p.z < 0.035 and y < 0.03
        else:
            hl = 0.035 + 0.06 * min(max(y / 0.13, 0), 1) - 0.11 * min(max(-y / 0.13, 0), 1)
            keep = p.z > hl
        if not keep:
            kill.append(v)
    bmesh.ops.delete(bm, geom=kill, context='VERTS')
    if style == 'ponytail':
        add_ellipsoid(bm, HC + Vector((0, -0.15, 0.02)), (0.05, 0.06, 0.07), 12, 8, mi)
        add_ellipsoid(bm, HC + Vector((0, -0.17, -0.1)), (0.04, 0.045, 0.1), 12, 8, mi)
    if style == 'bun':
        add_ellipsoid(bm, HC + Vector((0, -0.08, 0.15)), (0.06, 0.06, 0.055), 12, 8, mi)
    if style == 'quiff':
        add_ellipsoid(bm, HC + Vector((0, 0.07, 0.13)), (0.09, 0.07, 0.05), 12, 8, mi)


def mouth_shapes():
    N = 10
    top = np.linspace(1, -1, N)
    bot = np.linspace(-1, 1, N)[1:-1]

    def key(w, ftop, fbot, zc=-0.062):
        pts = [(w * x, zc + ftop(x)) for x in top] + [(w * x, zc + fbot(x)) for x in bot]
        cz = np.mean([p[1] for p in pts])
        pts.append((0.0, cz))
        return [tuple(on_head(x, z, 0.003)) for x, z in pts]
    sq = lambda x: math.sqrt(max(1 - x * x, 0))
    shapes = {
        'neutral': key(0.03, lambda x: 0.0028, lambda x: -0.0028),
        'smile': key(0.045, lambda x: 0.004 + 0.013 * x * x, lambda x: -0.018 + 0.03 * x * x),
        'open': key(0.026, lambda x: 0.016 * sq(x), lambda x: -0.04 * sq(x)),
        'frown': key(0.032, lambda x: 0.004 - 0.014 * x * x, lambda x: -0.0015 - 0.014 * x * x),
    }
    n = len(shapes['neutral'])
    faces = [(n - 1, i, (i + 1) % (n - 1)) for i in range(n - 1)]
    return shapes, faces


def build_char(name, spec, collection):
    """spec keys: skin, hair, hstyle, top, sleeves ('long'|'short'), pants, shoes, hat, extra (list), girth, scale."""
    C = collection
    g = spec.get('girth', 1.0)
    skin = MAT[spec.get('skin', 'skin0')]
    top = MAT[spec.get('top', 'tee_blue')]
    pants = MAT[spec.get('pants', 'jeans')]
    shoes = MAT[spec.get('shoes', 'shoe_black')]
    hair = MAT[spec.get('hair', 'hair_brown')]
    extra = spec.get('extra', [])
    J = {}
    J['root'] = empty(name + '_root', (0, 0, 0), C)
    J['root'].rotation_mode = 'XYZ'
    sc = spec.get('scale', 1.0)
    J['root'].scale = (sc, sc, sc)
    J['hips'] = empty(name + '_hips', (0, 0, 0.95), C, J['root'])
    J['spine'] = empty(name + '_spine', (0, 0, 0.0), C, J['hips'])
    J['chest'] = empty(name + '_chest', (0, 0, 0.25), C, J['spine'])
    J['neck'] = empty(name + '_neck', (0, 0, 0.27), C, J['chest'])
    for s, sx in (('R', 1), ('L', -1)):
        J['sh' + s] = empty(f'{name}_sh{s}', (sx * 0.2 * g ** 0.5, 0, 0.19), C, J['chest'])
        J['el' + s] = empty(f'{name}_el{s}', (0, 0, -0.28), C, J['sh' + s])
        J['hip' + s] = empty(f'{name}_hip{s}', (sx * 0.095 * g ** 0.5, 0, -0.05), C, J['hips'])
        J['kn' + s] = empty(f'{name}_kn{s}', (0, 0, -0.43), C, J['hip' + s])
    for j in J.values():
        j.rotation_mode = 'XYZ'
    P = {}
    # torso
    bm = bmesh.new()
    add_ellipsoid(bm, (0, 0, -0.02), (0.165 * g, 0.11 * g, 0.11), 16, 10)
    P['pelvis'] = part(name + '_pelvis', bm, pants, J['hips'], C, smooth=True)
    bm = bmesh.new()
    add_ellipsoid(bm, (0, 0.01 * g, 0.13), (0.17 * g, 0.12 * g, 0.2), 18, 12)
    if 'hoodie' in extra:
        add_sbox(bm, (0, 0.115 * g + 0.01, 0.06), (0.1, 0.02, 0.06), e=0.3, mi=0)
    P['belly'] = part(name + '_belly', bm, top, J['spine'], C)
    bm = bmesh.new()
    add_ellipsoid(bm, (0, 0, 0.07), (0.205 * g ** 0.5, 0.125 * g, 0.18), 18, 12)
    for sx in (1, -1):
        add_sphere(bm, 0.062, 12, 8, Matrix.Translation((sx * 0.2 * g ** 0.5, 0, 0.19)))
    add_capsule(bm, (0, 0, 0.16), (0, 0, 0.31), 0.05, 0.048, seg=12, mi=1)
    mats = [top, skin]
    if 'hoodie' in extra:
        add_ellipsoid(bm, (0, -0.07, 0.25), (0.15, 0.08, 0.075), 14, 8, 0)
        for sx in (1, -1):
            add_capsule(bm, (sx * 0.04, 0.115 * g, 0.2), (sx * 0.046, 0.125 * g, 0.06), 0.006, seg=6, mi=2)
        mats.append(MAT['shirt_white'])
    if 'polo' in extra:
        add_ellipsoid(bm, (0, 0.0, 0.235), (0.085, 0.08, 0.035), 14, 6, 0)
        add_box(bm, 0.06, 0.118 * g, 0.1, 0.12, 0.125 * g + 0.006, 0.13, mi=2)
        mats.append(MAT['badge'])
    if 'suit' in extra:
        add_quad(bm, [(-0.07, 0.124 * g + 0.001, 0.25), (0.0, 0.126 * g + 0.002, 0.05), (0.07, 0.124 * g + 0.001, 0.25)], mi=2)
        add_box(bm, -0.022, 0.126 * g, -0.06, 0.022, 0.134 * g, 0.21, mi=3)
        add_ellipsoid(bm, (0, 0.132 * g, 0.215), (0.028, 0.012, 0.022), 8, 6, 3)
        mats += [MAT['shirt_white'], MAT['tie']]
    if 'overalls' in extra:
        add_sbox(bm, (0, 0.118 * g, 0.0), (0.13, 0.018, 0.14), e=0.25, mi=2)
        for sx in (1, -1):
            add_box(bm, sx * 0.09 - 0.02, -0.12, 0.13, sx * 0.09 + 0.02, 0.13, 0.27, mi=2)
        mats.append(MAT[spec.get('bib', 'jeans')])
    if 'vest' in extra:
        add_ellipsoid(bm, (0, 0.003, 0.06), (0.212 * g ** 0.5, 0.132 * g, 0.16), 16, 10, 2)
        mats.append(MAT['vest'])
    P['chest'] = part(name + '_chestm', bm, mats, J['chest'], C)
    if 'apron' in extra:
        bm = bmesh.new()
        add_sbox(bm, (0, 0.13 * g, -0.08), (0.17 * g, 0.012, 0.42), e=0.15, mi=0)
        P['apron'] = part(name + '_apron', bm, MAT['apron'], J['spine'], C)
    if 'coat' in extra:
        bm = bmesh.new()
        add_cyl(bm, 0.19 * g, 0.235 * g, 0.5, seg=20, matrix=Matrix.Translation((0, -0.01, -0.3)), caps=False)
        P['coat'] = part(name + '_coatskirt', bm, top, J['hips'], C)
    # head
    bm = bmesh.new()
    add_ellipsoid(bm, HC, HEAD_R, 24, 16)
    add_sphere(bm, 0.03 * spec.get('nose', 1.0), 12, 8, Matrix.Translation(on_head(0, -0.015, -0.006)))
    for sx in (1, -1):
        add_ellipsoid(bm, HC + Vector((sx * 0.124, -0.005, -0.005)), (0.022, 0.032, 0.045), 10, 8)
    P['head'] = part(name + '_head', bm, skin, J['neck'], C)
    hs = spec.get('hstyle', 'short')
    if hs != 'none':
        bm = bmesh.new()
        hair_mesh(bm, hs)
        P['hair'] = part(name + '_hair', bm, hair, J['neck'], C)
    if spec.get('mustache'):
        bm = bmesh.new()
        for sx in (1, -1):
            add_capsule(bm, on_head(0.004 * sx, -0.034, 0.008), on_head(0.045 * sx, -0.05, 0.002), 0.013, 0.008, seg=8)
        part(name + '_mustache', bm, hair, J['neck'], C)
    hat = spec.get('hat')
    if hat == 'straw':
        bm = bmesh.new()
        add_cyl(bm, 0.27, 0.25, 0.014, seg=24, matrix=Matrix.Translation(HC + Vector((0, 0.01, 0.11))))
        add_sbox(bm, HC + Vector((0, 0, 0.16)), (0.135, 0.145, 0.065), e=0.4)
        add_cyl(bm, 0.14, 0.14, 0.025, seg=20, matrix=Matrix.Translation(HC + Vector((0, 0, 0.13))), mi=1)
        part(name + '_hat', bm, [MAT['straw'], MAT['red_paint']], J['neck'], C)
    elif hat == 'visor':
        bm = bmesh.new()
        add_cyl(bm, 0.135, 0.135, 0.04, seg=24, matrix=Matrix.Translation(HC + Vector((0, 0, 0.085))), caps=False)
        add_sbox(bm, HC + Vector((0, 0.17, 0.075)), (0.09, 0.065, 0.008), e=0.4)
        part(name + '_hat', bm, MAT['polo'], J['neck'], C)
    elif hat == 'cap':
        bm = bmesh.new()
        vs = add_ellipsoid(bm, HC + Vector((0, 0, 0.04)), (0.135, 0.14, 0.13), 20, 12)
        bmesh.ops.delete(bm, geom=[v for v in vs if v.co.z < HC.z + 0.04 + 0.01], context='VERTS')
        add_sbox(bm, HC + Vector((0, 0.17, 0.06)), (0.09, 0.07, 0.008), e=0.4)
        part(name + '_hat', bm, MAT[spec.get('capmat', 'tee_red')], J['neck'], C)
    if 'glasses' in extra:
        bm = bmesh.new()
        for sx in (1, -1):
            add_ellipsoid(bm, on_head(sx * 0.047, 0.02, 0.022), (0.03, 0.006, 0.022), 12, 6)
        add_capsule(bm, on_head(-0.02, 0.025, 0.02), on_head(0.02, 0.025, 0.02), 0.004, seg=6)
        part(name + '_glasses', bm, MAT['glasses'], J['neck'], C)
    # face: eyes, lids, brows, mouth
    F = {}
    es = spec.get('eye', 1.0)
    for s, sx in (('R', 1), ('L', -1)):
        c = on_head(sx * 0.047, 0.02, -0.017)
        bm = bmesh.new()
        add_sphere(bm, 0.032 * es, 16, 12)
        add_ellipsoid(bm, (0, 0.028 * es, 0), (0.016 * es, 0.007, 0.016 * es), 12, 8, 1)
        e = part(f'{name}_eye{s}', bm, [MAT['eyewhite'], MAT['iris']], J['neck'], C, loc=c)
        e.rotation_mode = 'XYZ'
        F['eye' + s] = e
        bm = bmesh.new()
        vs = add_sphere(bm, 0.0355 * es, 16, 12)
        bmesh.ops.delete(bm, geom=[v for v in vs if v.co.z < -0.002], context='VERTS')
        lid = part(f'{name}_lid{s}', bm, skin, J['neck'], C, loc=c)
        lid.rotation_mode = 'XYZ'
        F['lid' + s] = lid
        bm = bmesh.new()
        add_capsule(bm, (-0.022, 0, 0), (0.022, 0, 0), 0.0085, seg=8)
        b = part(f'{name}_brow{s}', bm, hair, J['neck'], C, loc=on_head(sx * 0.048, 0.078, 0.006))
        b.rotation_mode = 'XYZ'
        F['brow' + s] = b
        F['brow0' + s] = Vector(b.location)
    shapes, faces = mouth_shapes()
    m = mesh_obj(name + '_mouth', shapes['neutral'], faces, MAT['mouth'], C, smooth=True)
    m.parent = J['neck']
    m.shape_key_add(name='Basis')
    for k in ('smile', 'open', 'frown'):
        sk = m.shape_key_add(name=k)
        for i, p in enumerate(shapes[k]):
            sk.data[i].co = p
    F['mouth'] = m
    # arms
    long_sleeve = spec.get('sleeves', 'long') == 'long'
    for s, sx in (('R', 1), ('L', -1)):
        bm = bmesh.new()
        if long_sleeve:
            add_capsule(bm, (0, 0, 0), (0, 0, -0.27), 0.052, 0.046, seg=12)
            part(f'{name}_uarm{s}', bm, top, J['sh' + s], C)
        else:
            add_capsule(bm, (0, 0, -0.02), (0, 0, -0.27), 0.044, 0.04, seg=12, mi=1)
            add_cyl(bm, 0.058, 0.054, 0.15, seg=12, matrix=Matrix.Translation((0, 0, -0.06)), mi=0)
            part(f'{name}_uarm{s}', bm, [top, skin], J['sh' + s], C)
        bm = bmesh.new()
        add_capsule(bm, (0, 0, 0), (0, 0, -0.24), 0.043, 0.036, seg=12, mi=0 if long_sleeve else 1)
        add_ellipsoid(bm, (0, 0.004, -0.31), (0.026, 0.044, 0.058), 12, 8, 1)
        add_capsule(bm, (sx * -0.005, 0.034, -0.27), (sx * -0.004, 0.052, -0.31), 0.014, seg=8, mi=1)
        part(f'{name}_farm{s}', bm, [top, skin], J['el' + s], C)
        bm = bmesh.new()
        add_capsule(bm, (0, 0, 0), (0, 0, -0.42), 0.074 * g ** 0.5, 0.058, seg=12)
        part(f'{name}_thigh{s}', bm, pants, J['hip' + s], C)
        bm = bmesh.new()
        add_capsule(bm, (0, 0, 0), (0, 0, -0.38), 0.056, 0.046, seg=12)
        add_sbox(bm, (0, 0.05, -0.43), (0.052, 0.125, 0.042), e=0.35, mi=1)
        part(f'{name}_shin{s}', bm, [skin if spec.get('shorts') else pants, shoes], J['kn' + s], C)
    CH[name] = dict(J=J, F=F, P=P, spec=spec)
    pose(name, {})
    return CH[name]


def add_quad(bm, pts, mi=0):
    vs = [bm.verts.new(p) for p in pts]
    f = bm.faces.new(vs)
    f.material_index = mi
    return f


def hand_pos(name, side='R'):
    """World position of a hand (for props and emitters)."""
    el = CH[name]['J']['el' + side]
    return el.matrix_world @ Vector((0, 0.0, -0.31))


def attach(ob, name, joint, loc=(0, 0, 0), rot=(0, 0, 0)):
    ob.parent = CH[name]['J'][joint]
    ob.location = loc
    ob.rotation_euler = tuple(R(a) for a in rot)
    return ob


REST = dict(loc=(0, 0, 0), yaw=0.0, dz=0.0, lean=0.0, twist=0.0, side=0.0, chest=0.0, nod=0.0, turn=0.0, roll=0.0,
            shR=(0, 8, 0), shL=(0, 8, 0), elR=10.0, elL=10.0, hipR=(0, 0), hipL=(0, 0), knR=0.0, knL=0.0,
            smile=0.0, open=0.0, frown=0.0, brow=0.0, btilt=0.0, lid=0.12, look=(0.0, 0.0))


def pose(name, P):
    c = CH[name]
    J, F = c['J'], c['F']
    q = dict(REST)
    q.update(P)
    J['root'].location = q['loc']
    J['root'].rotation_euler = (0, 0, R(q['yaw']))
    J['hips'].location = (0, 0, 0.95 + q['dz'])
    J['spine'].rotation_euler = (R(-q['lean']), R(q['side']), R(q['twist']))
    J['chest'].rotation_euler = (R(-q['chest']), 0, 0)
    J['neck'].rotation_euler = (R(-q['nod']), R(q['roll']), R(q['turn']))
    for s, sg in (('R', -1), ('L', 1)):
        sw, ab, tw = q['sh' + s]
        J['sh' + s].rotation_euler = (R(sw), R(sg * ab), R(-sg * tw))
        J['el' + s].rotation_euler = (R(q['el' + s]), 0, 0)
        hs, ha = q['hip' + s]
        J['hip' + s].rotation_euler = (R(hs), R(sg * ha), 0)
        J['kn' + s].rotation_euler = (R(-q['kn' + s]), 0, 0)
    lx, ly = q['look']
    lid = q['lid']
    for s, sg in (('R', 1), ('L', -1)):
        F['eye' + s].rotation_euler = (R(ly), 0, R(lx))
        F['lid' + s].rotation_euler = (R(88 - 178 * lid + 0.4 * ly), 0, 0)
        b = F['brow' + s]
        b.location = F['brow0' + s] + Vector((0, 0, 0.016 * q['brow']))
        b.rotation_euler = (0, R(sg * 14 * q['btilt']), 0)
    kb = F['mouth'].data.shape_keys.key_blocks
    kb['smile'].value = q['smile']
    kb['open'].value = q['open']
    kb['frown'].value = q['frown']


def walk(ph, amp=1.0, run=0.0):
    """Joint angles for a walk (run=0) or run (run=1) cycle at phase ph (radians)."""
    s, c = math.sin(ph), math.cos(ph)
    leg = (26 + 22 * run) * amp
    arm = (18 + 30 * run) * amp
    out = dict(hipR=(leg * s, 2), hipL=(-leg * s, 2),
               knR=(8 + (30 + 40 * run) * max(0.0, c)) * amp, knL=(8 + (30 + 40 * run) * max(0.0, -c)) * amp,
               shR=(-arm * s, 10, 0), shL=(arm * s, 10, 0), elR=15 + 50 * run, elL=15 + 50 * run,
               dz=-(0.025 + 0.03 * run) * abs(s) * amp + 0.01 * run, lean=3 + 12 * run, twist=6 * s * amp)
    return out


def merge(*ds):
    out = {}
    for d in ds:
        out.update(d)
    return out


def walk_along(pts, t, t0, speed, stride=1.35, run=0.0, amp=1.0):
    """Walk along a polyline of (x, y) points starting at time t0 with speed m/s. Returns pose dict."""
    pts = [Vector((p[0], p[1], 0)) for p in pts]
    L = [0.0]
    for a, b in zip(pts[:-1], pts[1:]):
        L.append(L[-1] + (b - a).length)
    d = min(max((t - t0) * speed, 0.0), L[-1])
    moving = 0.0 < (t - t0) * speed < L[-1]
    for i in range(len(pts) - 1):
        if d <= L[i + 1] or i == len(pts) - 2:
            k = (d - L[i]) / max(L[i + 1] - L[i], 1e-6)
            p = pts[i].lerp(pts[i + 1], min(k, 1.0))
            dirn = (pts[i + 1] - pts[i]).normalized()
            break
    yaw = math.degrees(math.atan2(-dirn.x, dirn.y))
    P = dict(loc=(p.x, p.y, 0.0), yaw=yaw)
    if moving:
        P.update(walk(2 * math.pi * d / stride, amp, run))
    return P, moving


# ============================================================================
# Props
# ============================================================================
def area_light(name, loc, rot, sx, sy, energy, color, collection):
    ld = bpy.data.lights.new(name, 'AREA')
    ld.shape = 'RECTANGLE'
    ld.size, ld.size_y = sx, sy
    ld.energy = energy
    ld.color = color
    lo = bpy.data.objects.new(name, ld)
    lo.location = loc
    lo.rotation_euler = rot
    coll(collection).objects.link(lo)
    lo.visible_camera = False
    return lo


def point_light(name, loc, energy, color, collection, radius=0.1):
    ld = bpy.data.lights.new(name, 'POINT')
    ld.energy = energy
    ld.color = color
    ld.shadow_soft_size = radius
    lo = bpy.data.objects.new(name, ld)
    lo.location = loc
    coll(collection).objects.link(lo)
    return lo


def spot_light(name, loc, target, energy, angle, color, collection, blend=0.5, radius=0.05):
    ld = bpy.data.lights.new(name, 'SPOT')
    ld.energy = energy
    ld.color = color
    ld.spot_size = math.radians(angle)
    ld.spot_blend = blend
    ld.shadow_soft_size = radius
    lo = bpy.data.objects.new(name, ld)
    lo.location = loc
    lo.rotation_euler = (Vector(target) - Vector(loc)).to_track_quat('-Z', 'Y').to_euler()
    coll(collection).objects.link(lo)
    return lo

MAXQ = {'dust': 700, 'dot': 1200}
PART = {}
EMIT = {}


def billboard_obj(name, n, mat):
    faces = np.arange(4 * n).reshape(n, 4)
    ob = mesh_obj(name, np.zeros((4 * n, 3)), faces, mat, collection='FX', smooth=False,
                  uvs=np.tile(np.array([[0, 0], [1, 0], [1, 1], [0, 1]], np.float32), (n, 1)))
    ob.data.color_attributes.new('sm', 'FLOAT_COLOR', 'CORNER')
    ob.visible_shadow = False
    ob.visible_diffuse = False
    return ob


def emitter(kind, src, rate, life, vel, spread, size, opacity=1.0, glow=0.0, area=0.5, t0=-10.0, t1=1e9,
            rise=0.0, turb=0.4, salt=0.0):
    return dict(kind=kind, src=np.atleast_2d(np.array(src, float)), rate=rate, life=life, vel=np.array(vel, float),
                spread=spread, size=size, opacity=opacity, glow=glow, area=area, t0=t0, t1=t1, rise=rise, turb=turb, salt=salt)


def eval_emitter(e, t):
    K = len(e['src'])
    slots = int(math.ceil(e['life'] * e['rate'])) + 1
    k = np.repeat(np.arange(K), slots)
    j = np.tile(np.arange(slots), K)
    phase = hash01(k, 0.5, e['salt'])
    i = np.floor((t - e['t0']) * e['rate'] - phase) - j
    tb = e['t0'] + (i + phase) / e['rate']
    age = t - tb
    ok = (age >= 0) & (age <= e['life']) & (tb <= e['t1']) & (i >= 0)
    k, i, age = k[ok], i[ok], age[ok]
    r1, r2, r3, r4 = (hash01(k + 0.1 * q, i, e['salt'] + q) for q in range(4))
    a = r1 * 2 * np.pi
    rr = np.sqrt(r2) * e['area']
    start = e['src'][k] + np.stack([rr * np.cos(a), rr * np.sin(a), (r3 - 0.5) * e['area']], -1)
    dirn = np.stack([np.cos(a + 1.3), np.sin(a + 1.3), (r3 - 0.5) * 0.6], -1)
    u = age / e['life']
    pos = start + e['vel'][None, :] * age[:, None] + dirn * (e['spread'] * age)[:, None]
    pos[:, 2] += 0.5 * e['rise'] * age ** 2
    pos += e['turb'] * np.stack([np.sin(age * 1.3 + r4 * 6.3), np.cos(age * 1.1 + r1 * 6.3), 0.5 * np.sin(age * 0.9 + r2 * 6.3)], -1)
    s0, s1 = e['size']
    size = (s0 + (s1 - s0) * u ** 0.6) * (0.7 + 0.6 * r3)
    alpha = e['opacity'] * np.clip(u / 0.12, 0, 1) * np.clip((1 - u) / 0.45, 0, 1)
    return pos, size, u, r4, alpha, np.full_like(u, e['glow'])


def cam_basis(cs):
    fwd = Vector(cs['fwd']).normalized()
    right = fwd.cross(Vector((0, 0, 1)))
    if right.length < 1e-4:
        right = Vector((1, 0, 0))
    right.normalize()
    up = right.cross(fwd).normalized()
    return np.array(right), np.array(up)


def update_particles(t, shot, cs):
    right, up = cam_basis(cs)
    groups = {k: [] for k in MAXQ}
    for e in EMIT.get(shot, []):
        if e['t0'] <= t:
            groups[e['kind']].append(eval_emitter(e, t))
    camp, fwd = np.array(cs['loc']), np.array(cs['fwd'])
    for kind in MAXQ:
        ob, n = PART[kind], MAXQ[kind]
        V = np.zeros((n, 4, 3))
        C = np.zeros((n, 4, 4))
        if groups[kind]:
            pos, size, u, seed, alpha, glow = (np.concatenate(x) for x in zip(*groups[kind]))
            rel = pos - camp
            d = np.linalg.norm(rel, axis=1)
            front = rel @ fwd > 0.1
            pos, size, u, seed, alpha, glow, d = (a[front] for a in (pos, size, u, seed, alpha, glow, d))
            if kind == 'dot':
                size = size + 0.0012 * d
            if len(pos) > n:
                idx = np.argsort(d)[:n]
                pos, size, u, seed, alpha, glow, d = (a[idx] for a in (pos, size, u, seed, alpha, glow, d))
            m = len(pos)
            alpha = alpha * np.clip((d - size * 0.8) / (size * 1.5 + 0.2), 0, 1)
            rr, uu = right[None, :] * size[:, None], up[None, :] * size[:, None]
            V[:m] = np.stack([pos - rr - uu, pos + rr - uu, pos + rr + uu, pos - rr + uu], 1)
            C[:m] = np.stack([seed, u, glow, alpha], -1)[:, None, :]
        me = ob.data
        me.vertices.foreach_set('co', V.astype(np.float32).ravel())
        me.color_attributes['sm'].data.foreach_set('color', C.astype(np.float32).ravel())
        me.update()


def build_fx():
    for k in MAXQ:
        PART[k] = billboard_obj(k.capitalize(), MAXQ[k], MAT[k])

# ============================================================================
# Simple reach (IK-lite) and look-at helpers for the characters
# ============================================================================
def jmat(ob):
    M = ob.matrix_basis.copy()
    p = ob.parent
    while p is not None:
        M = p.matrix_basis @ M
        p = p.parent
    return M


def reach(name, side, target, bend=None):
    """Shoulder/elbow angles that put the hand (centre) at a world-space target. Returns (sh tuple, elbow)."""
    J = CH[name]['J']
    sh = J['sh' + side]
    M = jmat(J['chest']) @ Matrix.Translation(sh.location)
    d = M.inverted() @ Vector(target)
    D = d.length
    L = 0.59
    if bend is None:
        bend = math.degrees(2 * math.acos(min(D / L, 0.999))) if D < L else 6.0
        bend = max(bend, 6.0)
    dn = d.normalized()
    sw1 = math.asin(max(-1.0, min(1.0, dn.y)))
    ph1 = math.atan2(-dn.x, -dn.z)
    sw2 = math.pi - sw1
    ph2 = math.atan2(dn.x, dn.z)
    sw, ph = (sw1, ph1) if abs(ph1) <= abs(ph2) else (sw2, ph2)
    sg = -1 if side == 'R' else 1
    return (math.degrees(sw) - bend * 0.5, math.degrees(ph) * sg, 0.0), bend


def look_at(name, target, head=0.7):
    """Head turn/nod and eye angles toward a world-space point. Returns a pose fragment."""
    J = CH[name]['J']
    M = jmat(J['chest']) @ Matrix.Translation(J['neck'].location + HC)
    d = M.inverted() @ Vector(target)
    yaw = math.degrees(math.atan2(-d.x, d.y))
    pitch = math.degrees(math.atan2(d.z, math.hypot(d.x, d.y)))
    return dict(turn=yaw * head, nod=-pitch * head, look=(yaw * (1 - head) * 1.2, pitch * (1 - head) * 1.2))


def apply_reach(name, P, side, target, bend=None):
    pose(name, P)
    P['sh' + side], P['el' + side] = reach(name, side, target, bend)
    return P


# ============================================================================
# Cameras: one keyframed rig per shot (location, target, lens), bound with timeline markers
# ============================================================================
CAMS = {}
RIGS = {}
SHAKE = {}


def camera_shot(name, lens, path, target, fstop=8.0, shake=0.0, ease=True, lenses=None):
    """path/target: list of (u, (x, y, z)) keys with u in 0..1 of the shot. lenses: [(u, mm)]."""
    s = SHOT[name]
    rig = empty('Rig_' + name)
    tgt = empty('Target_' + name)
    cd = bpy.data.cameras.new('Cam_' + name)
    cd.lens = lens
    cd.sensor_width = 24
    cd.sensor_fit = 'VERTICAL'
    cd.clip_start, cd.clip_end = 0.02, 5000
    cd.dof.use_dof = fstop < 50
    cd.dof.aperture_fstop = fstop
    cd.dof.aperture_blades = 7
    cd.dof.focus_object = tgt
    cam = bpy.data.objects.new('Cam_' + name, cd)
    coll('Rig').objects.link(cam)
    cam.parent = rig
    con = rig.constraints.new('TRACK_TO')
    con.target = tgt
    con.track_axis = 'TRACK_NEGATIVE_Z'
    con.up_axis = 'UP_Y'
    span = s['f1'] + 1 - s['f0']
    for u, p in path:
        rig.location = p
        rig.keyframe_insert('location', frame=s['f0'] + u * span)
    for u, p in target:
        tgt.location = p
        tgt.keyframe_insert('location', frame=s['f0'] + u * span)
    if lenses:
        for u, mm in lenses:
            cd.lens = mm
            cd.keyframe_insert('lens', frame=s['f0'] + u * span)
    for idb in (rig, tgt, cd):
        if idb.animation_data:
            for fc in idb.animation_data.action.fcurves:
                for kp in fc.keyframe_points:
                    kp.interpolation = 'BEZIER'
                    kp.easing = ease if isinstance(ease, str) else ('EASE_IN_OUT' if ease else 'AUTO')
                    if not ease:
                        kp.handle_left_type = kp.handle_right_type = 'VECTOR'
    m = bpy.context.scene.timeline_markers.new('M_' + name, frame=s['f0'])
    m.camera = cam
    CAMS[name] = cam
    RIGS[name] = (rig, tgt, cd)
    SHAKE[name] = shake
    return cam


def eval_loc(ob, f):
    ad = ob.animation_data
    v = Vector(ob.location)
    if ad and ad.action:
        for fc in ad.action.fcurves:
            if fc.data_path == 'location':
                v[fc.array_index] = fc.evaluate(f)
    return v


def cam_state(name, f):
    rig, tgt, cd = RIGS[name]
    loc = eval_loc(rig, f)
    tl = eval_loc(tgt, f)
    return {'loc': tuple(loc), 'fwd': tuple((tl - loc).normalized())}


def shake_offset(t, name):
    amp = SHAKE.get(name, 0.0)
    if amp <= 0:
        return Vector((0, 0, 0))
    return Vector((math.sin(t * 7.0) + 0.5 * math.sin(t * 13.1), math.sin(t * 5.3 + 1), math.sin(t * 4.1 + 2))) * amp


def chest_pt(name, local):
    return jmat(CH[name]['J']['chest']) @ Vector(local)


def head_pt(name, local=(0, 0, 0)):
    return jmat(CH[name]['J']['neck']) @ (HC + Vector(local))


def hug(name, P, w=0.25, fwd=0.3, z=-0.12):
    pose(name, P)
    P['shR'], P['elR'] = reach(name, 'R', chest_pt(name, (w, fwd, z)))
    P['shL'], P['elL'] = reach(name, 'L', chest_pt(name, (-w, fwd, z)))
    return P


def idle(t, seed=0.0):
    """Small breathing / weight-shift motion."""
    return dict(chest=1.5 * math.sin(t * 1.7 + seed), side=1.2 * math.sin(t * 0.6 + seed), dz=0.006 * math.sin(t * 1.7 + seed))


def park(name, loc=(0, 0, -50)):
    pose(name, dict(loc=loc))


def cart_follow(cart_ob, P, dist=0.9):
    yaw = R(P['yaw'])
    x, y, _ = P['loc']
    cart_ob.location = (x - math.sin(yaw) * dist, y + math.cos(yaw) * dist, 0)
    cart_ob.rotation_euler = (0, 0, yaw)


def push_cart(name, P, cart_ob):
    cart_follow(cart_ob, P)
    M = cart_ob.matrix_basis
    pose(name, P)
    P['shR'], P['elR'] = reach(name, 'R', M @ Vector((0.18, -0.48, 1.08)))
    P['shL'], P['elL'] = reach(name, 'L', M @ Vector((-0.18, -0.48, 1.08)))
    return P


def set_face(P, **kw):
    P.update(kw)
    return P


def blend_face(a, b, u):
    out = {}
    for k in set(a) | set(b):
        va, vb = a.get(k, REST.get(k)), b.get(k, REST.get(k))
        if isinstance(va, tuple):
            out[k] = tuple(lerp(x, y, u) for x, y in zip(va, vb))
        else:
            out[k] = lerp(va, vb, u)
    return out


# ============================================================================
# Props: cars (body + 4 wheels on a root, so the suspension can extend and compress), bus, airliner,
# cafe furniture, bins, lamps, cups, the fountain, the basketball hoop, apartment furniture
# ============================================================================
PROPS = {}
CARS = {}


def car_body_bm(bm, L=4.4, W=1.8, H=1.42, mi_paint=0, mi_glass=1, mi_trim=2, mi_head=3, mi_tail=4):
    """A modern hatchback/sedan, facing +Y, wheels' bottom at z=0 (body is built at ride height)."""
    # lower body
    add_sbox(bm, (0, 0, 0.62), (W / 2, L / 2, 0.30), e=0.18, u=24, v=12, mi=mi_paint)
    # bonnet slope + cabin (glass house)
    add_sbox(bm, (0, -0.25, 1.06), (W / 2 - 0.1, L * 0.27, 0.30), e=0.32, u=24, v=12, mi=mi_glass)
    add_sbox(bm, (0, -0.25, 1.33), (W / 2 - 0.16, L * 0.22, 0.05), e=0.3, u=16, v=8, mi=mi_paint)       # roof
    # bumpers, sills
    for sy in (1, -1):
        add_sbox(bm, (0, sy * (L / 2 - 0.02), 0.45), (W / 2 - 0.05, 0.08, 0.12), e=0.3, u=12, v=8, mi=mi_trim)
    for sx in (1, -1):
        add_box(bm, sx * (W / 2 - 0.02) - 0.03, -L / 2 + 0.7, 0.30, sx * (W / 2 - 0.02) + 0.03, L / 2 - 0.7, 0.38, mi=mi_trim)
        # head and tail lights
        add_sbox(bm, (sx * 0.62, L / 2 - 0.02, 0.72), (0.2, 0.05, 0.06), e=0.3, u=12, v=6, mi=mi_head)
        add_sbox(bm, (sx * 0.64, -L / 2 + 0.02, 0.76), (0.18, 0.05, 0.06), e=0.3, u=12, v=6, mi=mi_tail)
        # mirrors
        add_sbox(bm, (sx * (W / 2 + 0.06), 0.55, 1.0), (0.08, 0.05, 0.06), e=0.4, u=10, v=6, mi=mi_paint)
    # wheel arches (dark)
    for sx in (1, -1):
        for sy in (1, -1):
            add_cyl(bm, 0.40, 0.40, 0.06, seg=18, matrix=Matrix.Translation((sx * (W / 2 - 0.0), sy * 1.36, 0.36)) @ Matrix.Rotation(R(90), 4, 'Y'), mi=mi_trim)


def wheel_bm(bm, r=0.33, w=0.22):
    add_cyl(bm, r, r, w, seg=20, matrix=Matrix.Rotation(R(90), 4, 'Y'), mi=0)
    add_cyl(bm, r * 0.62, r * 0.62, w + 0.01, seg=16, matrix=Matrix.Rotation(R(90), 4, 'Y'), mi=1)
    for k in range(5):
        a = 2 * math.pi * k / 5
        add_box(bm, -w / 2 - 0.008, -0.025, 0.04, w / 2 + 0.008, 0.025, r * 0.6,
                matrix=Matrix.Rotation(a, 4, 'X'), mi=1)


def make_car(name, collection, c, yaw, paint, L=4.4, W=1.8, kind='car'):
    root = empty(name, c, collection)
    root.rotation_mode = 'XYZ'
    root.rotation_euler = (0, 0, R(yaw))
    bm = bmesh.new()
    if kind == 'bus':
        add_sbox(bm, (0, 0, 1.75), (W / 2, L / 2, 1.42), e=0.12, u=24, v=12, mi=0)
        add_box(bm, -W / 2 - 0.01, -L / 2 + 0.6, 1.55, W / 2 + 0.01, L / 2 - 2.2, 2.75, mi=1)           # side windows band
        add_box(bm, -W / 2 + 0.15, L / 2 - 0.05, 1.2, W / 2 - 0.15, L / 2 + 0.01, 2.9, mi=1)            # windscreen
        add_box(bm, -W / 2 - 0.02, -L / 2, 0.38, W / 2 + 0.02, L / 2, 0.58, mi=2)
        for sx in (1, -1):
            add_sbox(bm, (sx * 0.95, L / 2, 0.75), (0.16, 0.04, 0.08), e=0.3, u=10, v=6, mi=3)
        add_box(bm, -W / 2 - 0.012, -L / 2 + 1.2, 2.82, W / 2 + 0.012, L / 2 - 1.0, 3.0, mi=4)          # livery stripe
        mats = [MAT[paint], MAT['window'], MAT['rubber'], MAT['headlight'], MAT['bus_stripe']]
        wheel_y = (L / 2 - 2.0, -L / 2 + 2.6)
        wr = 0.5
    else:
        car_body_bm(bm, L, W)
        mats = [MAT[paint], MAT['window'], MAT['black_plastic'], MAT['headlight'], MAT['taillight']]
        wheel_y = (1.36, -1.36)
        wr = 0.33
    body = obj_from_bm(name + '_body', bm, mats, collection, smooth=True)
    body.parent = root
    wheels = []
    for sx in (1, -1):
        for sy in wheel_y:
            bm = bmesh.new()
            wheel_bm(bm, wr, 0.24 if kind == 'car' else 0.32)
            wob = obj_from_bm(f'{name}_wheel{len(wheels)}', bm, [MAT['rubber'], MAT['alloy']], collection, smooth=True)
            wob.parent = root
            wob.location = (sx * (W / 2 - 0.12), sy, wr)
            wob.rotation_mode = 'XYZ'
            wheels.append(wob)
    CARS[name] = dict(root=root, body=body, wheels=wheels, wr=wr, kind=kind)
    return CARS[name]


def airliner(name, collection):
    root = empty(name, (0, 0, 0), collection)
    root.rotation_mode = 'XYZ'
    bm = bmesh.new()
    add_capsule(bm, (0, -17, 0), (0, 17, 0), 2.0, 2.0, seg=20)                  # fuselage along +Y
    add_sbox(bm, (0, 18.6, -0.2), (1.9, 2.4, 1.8), e=0.6, u=20, v=12)           # nose
    add_sbox(bm, (0, -19.5, 0.6), (1.2, 3.0, 1.2), e=0.6, u=16, v=10)           # tail cone

    def plate(pts, th, mi):
        top = [bm.verts.new((x, y, z + th / 2)) for x, y, z in pts]
        bot = [bm.verts.new((x, y, z - th / 2)) for x, y, z in pts]
        bm.faces.new(top)
        bm.faces.new(bot[::-1])
        n = len(pts)
        for i in range(n):
            f = bm.faces.new((top[i], top[(i + 1) % n], bot[(i + 1) % n], bot[i]))
            f.material_index = mi
        for f in bm.faces[-n - 2:]:
            f.material_index = mi
    for sx in (1, -1):
        plate([(sx * 1.6, 4.0, -0.9), (sx * 17.5, -4.0, 0.4), (sx * 17.5, -6.0, 0.4), (sx * 1.6, -3.5, -0.9)], 0.35, 1)   # wing
        plate([(sx * 0.8, -15.5, 0.8), (sx * 6.5, -19.5, 1.2), (sx * 6.5, -20.8, 1.2), (sx * 0.8, -19.8, 0.8)], 0.2, 1)   # stabiliser
        add_capsule(bm, (sx * 6.0, 2.6, -1.9), (sx * 6.0, -1.2, -1.9), 0.95, 0.85, seg=16, mi=2)                         # engine
    fin = [(0, -13.5, 1.6), (0, -20.5, 8.0), (0, -22.5, 8.0), (0, -21.0, 1.6)]
    top = [bm.verts.new((0.18, y, z)) for x, y, z in fin]
    bot = [bm.verts.new((-0.18, y, z)) for x, y, z in fin]
    bm.faces.new(top)
    bm.faces.new(bot[::-1])
    for i in range(4):
        bm.faces.new((top[i], top[(i + 1) % 4], bot[(i + 1) % 4], bot[i]))
    for k in range(26):                                                        # cabin windows
        add_sbox(bm, (1.98, 12 - k * 1.0, 0.55), (0.05, 0.16, 0.2), e=0.5, u=8, v=6, mi=3)
        add_sbox(bm, (-1.98, 12 - k * 1.0, 0.55), (0.05, 0.16, 0.2), e=0.5, u=8, v=6, mi=3)
    ob = obj_from_bm(name + '_mesh', bm, [MAT['plane_white'], MAT['plane_grey'], MAT['darksteel'], MAT['window']], collection, smooth=True)
    ob.parent = root
    PROPS[name] = root
    return root


def cafe_table(bm, c):
    x, y, z = c
    add_cyl(bm, 0.36, 0.36, 0.03, seg=24, matrix=Matrix.Translation((x, y, z + 0.74)), mi=0)
    add_cyl(bm, 0.025, 0.025, 0.72, seg=8, matrix=Matrix.Translation((x, y, z + 0.37)), mi=1)
    add_cyl(bm, 0.22, 0.24, 0.03, seg=16, matrix=Matrix.Translation((x, y, z + 0.015)), mi=1)


def cafe_chair(bm, c=(0, 0, 0)):
    x, y, z = c
    add_box(bm, x - 0.21, y - 0.21, z + 0.44, x + 0.21, y + 0.21, z + 0.47, mi=0)
    for sx in (1, -1):
        for sy in (1, -1):
            add_cyl(bm, 0.013, 0.013, 0.45, seg=6, matrix=Matrix.Translation((x + sx * 0.18, y + sy * 0.18, z + 0.225)), mi=1)
    for sx in (1, -1):
        add_cyl(bm, 0.013, 0.013, 0.42, seg=6, matrix=Matrix.Translation((x + sx * 0.18, y - 0.19, z + 0.67)), mi=1)
    add_box(bm, x - 0.2, y - 0.21, z + 0.72, x + 0.2, y - 0.18, z + 0.86, mi=0)


def bin_bm(bm):
    add_cyl(bm, 0.28, 0.25, 0.9, seg=16, matrix=Matrix.Translation((0, 0, 0.45)), mi=0)
    add_cyl(bm, 0.30, 0.30, 0.06, seg=16, matrix=Matrix.Translation((0, 0, 0.92)), mi=1)


def cup_bm(bm):
    """Takeaway paper cup without a lid (origin at the base)."""
    add_cyl(bm, 0.036, 0.046, 0.115, seg=20, matrix=Matrix.Translation((0, 0, 0.0575)), mi=0, caps=False)
    add_cyl(bm, 0.036, 0.036, 0.004, seg=20, matrix=Matrix.Translation((0, 0, 0.002)), mi=0)
    add_cyl(bm, 0.0475, 0.0475, 0.006, seg=20, matrix=Matrix.Translation((0, 0, 0.116)), mi=0, caps=False)
    add_cyl(bm, 0.043, 0.0445, 0.045, seg=20, matrix=Matrix.Translation((0, 0, 0.06)), mi=1, caps=False)       # sleeve


def hoop_bm(bm):
    """Basketball post + backboard + rim; rim centre at (0, 0, 3.05) (local), backboard behind it at +Y."""
    add_cyl(bm, 0.09, 0.09, 3.3, seg=12, matrix=Matrix.Translation((0, 1.45, 1.65)), mi=0)
    add_box(bm, -0.06, 0.7, 3.2, 0.06, 1.45, 3.3, mi=0)
    add_box(bm, -0.9, 0.38, 2.75, 0.9, 0.42, 3.8, mi=1)
    add_box(bm, -0.3, 0.37, 2.95, 0.3, 0.375, 3.4, mi=2)
    seg = 24
    for k in range(seg):
        a0, a1 = 2 * math.pi * k / seg, 2 * math.pi * (k + 1) / seg
        add_capsule(bm, (0.23 * math.cos(a0), 0.23 * math.sin(a0), 3.05), (0.23 * math.cos(a1), 0.23 * math.sin(a1), 3.05), 0.012, seg=6, mi=3, caps=False)
    for k in range(12):                                     # net strings
        a = 2 * math.pi * k / 12
        add_capsule(bm, (0.23 * math.cos(a), 0.23 * math.sin(a), 3.05), (0.14 * math.cos(a + 0.4), 0.14 * math.sin(a + 0.4), 2.62), 0.005, seg=4, mi=4, caps=False)
    add_box(bm, -0.04, 0.2, 3.03, 0.04, 0.38, 3.07, mi=3)


def lamp_post(bm, x, y, z0=0.15, side=1):
    add_cyl(bm, 0.09, 0.07, 6.5, seg=10, matrix=Matrix.Translation((x, y, z0 + 3.25)), mi=0)
    add_capsule(bm, (x, y, z0 + 6.4), (x - side * 1.3, y, z0 + 6.75), 0.05, seg=8, mi=0)
    add_sbox(bm, (x - side * 1.45, y, z0 + 6.68), (0.32, 0.16, 0.07), e=0.4, u=12, v=6, mi=1)


def ruler_bm(bm, h=2.0):
    add_box(bm, -0.04, -0.04, 0, 0.04, 0.04, h, mi=0)
    for k in range(int(h / 0.1) + 1):
        w = 0.14 if k % 5 == 0 else 0.08
        add_box(bm, 0.04, -0.012, k * 0.1 - 0.008, 0.04 + w, 0.012, k * 0.1 + 0.008, mi=1 if k % 5 == 0 else 0)


def sofa_bm(bm, w=2.0):
    add_sbox(bm, (0, 0, 0.25), (w / 2, 0.45, 0.15), e=0.2, mi=0)
    add_sbox(bm, (0, -0.35, 0.6), (w / 2, 0.12, 0.38), e=0.25, mi=0)
    for sx in (1, -1):
        add_sbox(bm, (sx * (w / 2 - 0.1), 0, 0.45), (0.12, 0.45, 0.22), e=0.25, mi=0)
    for k in range(2):
        add_sbox(bm, ((k - 0.5) * w * 0.45, 0.02, 0.45), (w * 0.22, 0.38, 0.08), e=0.3, mi=1)
    for sx in (1, -1):
        for sy in (1, -1):
            add_box(bm, sx * (w / 2 - 0.08) - 0.03, sy * 0.38 - 0.03, 0, sx * (w / 2 - 0.08) + 0.03, sy * 0.38 + 0.03, 0.1, mi=2)


def tree_row(prefix, collection, pts, height=7.5, seed=0):
    for k, p in enumerate(pts):
        make_tree(f'{prefix}{k}', collection, p, height * (0.9 + 0.2 * ((k * 37) % 7) / 7), seed + k * 3, n_bills=0,
                  n_leaves=700, spread=0.9, leaf_mat='leaves' if k % 2 else 'leaves_dark', bark_seg=7)


# ============================================================================
# REALISTIC HUMANS. A procedural person with adult proportions (about 7.5 heads tall): a sculpted head (skull,
# brow ridge, eye sockets, cheekbones, jaw, chin), a separate nose, ears, eyeballs with iris and pupil, eyelids with
# lashes, eyebrows, lips with shape keys, particle hair (or a hair shell), subsurface skin with stubble, a lofted body
# under clothes, and hands with five fingers. It uses the same joint hierarchy as build_char (root, hips, spine,
# chest, neck, shoulders, elbows, hips, knees), so pose(), walk_along(), reach() and look_at() drive it unchanged.
# ============================================================================
HC2 = Vector((0.0, 0.016, 0.128))          # head centre in neck-joint space
HR2 = (0.077, 0.097, 0.118)                # head half-width, half-depth, half-height
EYE_X, EYE_Z, EYE_R = 0.0315, -0.004, 0.0118


def smoothstep(e0, e1, x):
    t = np.clip((x - e0) / (e1 - e0), 0, 1)
    return t * t * (3 - 2 * t)


def head_surface_y(x, z):
    """Front surface (y) of the sculpted head at head-space x, z (relative to HC2) - used to place features."""
    a, b, c = HR2
    k = max(1 - (x / a) ** 2 - (z / c) ** 2, 0.02)
    return b * math.sqrt(k) * (1 - 0.06) + HC2.y


def head_mesh(bm, sp):
    """A UV sphere sculpted into a human head (in neck space). sp: jaw (width factor), chin, fem (0..1)."""
    a, b, c = HR2
    vs = add_sphere(bm, 1.0, 112, 84)
    jaw = sp.get('jaw', 1.0)
    nw, nl = sp.get('nose_w', 1.0), sp.get('nose_l', 1.0)
    for v in vs:
        n = v.co.copy()
        x, y, z = n.x * a, n.y * b, n.z * c
        front = max(n.y, 0.0)
        x *= 1 - 0.07 * n.y                                           # egg shape: narrower at the face
        lower = smoothstep(-0.05, -0.95, n.z) * smoothstep(-0.5, 0.3, n.y)
        x *= 1 - (0.20 + 0.12 * sp.get('fem', 0.0)) * lower * (1.1 - 0.1 * jaw)   # jaw tapering to the chin
        z *= 1 - 0.08 * smoothstep(-0.2, -1.0, n.z) * front           # shorter lower face
        if n.z < -0.25 and n.y < 0.15:                                # under the skull: pull in toward the neck
            k = smoothstep(-0.25, -0.95, n.z) * smoothstep(0.15, -0.6, n.y)
            y = y * (1 - 0.35 * k) + 0.012 * k
            x *= 1 - 0.25 * k
        y *= 1 - 0.06 * front                                         # flatter face
        # chin and jaw corner
        y += 0.008 * sp.get('chin', 1.0) * math.exp(-((n.z + 0.86) / 0.12) ** 2) * math.exp(-(n.x / 0.28) ** 2) * front
        # cheekbones
        for sx in (-1, 1):
            d = (n.x - sx * 0.72) ** 2 / 0.06 + (n.y - 0.55) ** 2 / 0.08 + (n.z + 0.2) ** 2 / 0.05
            k = math.exp(-d)
            x += sx * 0.0035 * k
            y += 0.002 * k
        # brow ridge
        y += 0.0045 * (1 - 0.6 * sp.get('fem', 0.0)) * math.exp(-((n.z - 0.15) / 0.09) ** 2) * math.exp(-(n.x / 0.55) ** 2) * front
        # mouth area (muzzle) forward
        y += 0.007 * math.exp(-((n.z + 0.55) / 0.18) ** 2) * math.exp(-(n.x / 0.32) ** 2) * front
        # eye sockets
        for sx in (-1, 1):
            d = ((x - sx * EYE_X) ** 2 + (z - EYE_Z) ** 2) / 0.018 ** 2
            y -= 0.0075 * math.exp(-d) * front
        # philtrum / under-nose dip and cheek hollows
        for sx in (-1, 1):
            d = ((x - sx * 0.045) ** 2 + (z + 0.055) ** 2) / 0.02 ** 2
            x -= sx * 0.002 * math.exp(-d)
        # the nose, sculpted into the face: bridge -> tip -> columella, with the wings either side
        if front > 0.4 and -0.07 < z < 0.02:
            zt = -0.034
            if z > zt:
                u = (z - 0.012) / (zt - 0.012)
                u = min(max(u, 0.0), 1.0)
                hgt = (0.003 + 0.016 * u ** 1.4) * nl
                sig = 0.0052 + 0.0042 * u
            else:
                u = (z - zt) / -0.014
                hgt = 0.019 * nl * max(0.0, 1 - u) ** 1.6
                sig = 0.0094 - 0.003 * min(u, 1)
            y += hgt * math.exp(-(x / (sig * nw)) ** 2)
            for sx in (-1, 1):
                dw = ((x - sx * 0.0118 * nw) / 0.0058) ** 2 + ((z - zt + 0.0035) / 0.0062) ** 2
                y += 0.0075 * math.exp(-dw)
            y -= 0.0018 * math.exp(-((x / 0.004) ** 2) - ((z + 0.047) / 0.004) ** 2)          # philtrum groove
        v.co = HC2 + Vector((x, y, z))
    return vs


def nose_mesh(bm, sp, mi=0):
    """A nose built from overlapping rounded forms: a thin bridge, a rounded tip, two alar wings, the columella."""
    w = sp.get('nose_w', 1.0)
    L = sp.get('nose_l', 1.0)
    zt = -0.034
    yt = head_surface_y(0, zt) + 0.0185 * L
    for k in range(6):                                                   # bridge: a chain of flattened ellipsoids
        u = k / 5
        z = 0.004 + (zt + 0.006 - 0.004) * u
        y = head_surface_y(0, z) - 0.004 + (yt - 0.006 - head_surface_y(0, z) + 0.004) * u
        add_ellipsoid(bm, (0, y, HC2.z + z), (0.0058 + 0.0016 * u, 0.0045, 0.0075), 12, 8, mi)
    add_ellipsoid(bm, (0, yt - 0.004, HC2.z + zt), (0.0085 * w, 0.0075, 0.0078), 14, 10, mi)       # tip
    for sx in (-1, 1):                                                   # wings
        add_ellipsoid(bm, (sx * 0.0115 * w, yt - 0.0105, HC2.z + zt - 0.002), (0.0065, 0.0075, 0.0068), 12, 8, mi)
    add_ellipsoid(bm, (0, yt - 0.009, HC2.z + zt - 0.0065), (0.0045, 0.008, 0.0035), 10, 6, mi)    # columella


def ear_mesh(bm, sx, mi=0):
    c = HC2 + Vector((sx * (HR2[0] * 0.98), -0.008, 0.002))
    rot = Matrix.Rotation(R(-8), 3, 'X') @ Matrix.Rotation(R(sx * 18), 3, 'Z')
    add_ellipsoid(bm, c, (0.008, 0.019, 0.030), 14, 10, mi, rot)
    add_ellipsoid(bm, c + Vector((sx * 0.004, 0.0, 0.004)), (0.005, 0.013, 0.021), 12, 8, mi, rot)


def lip_shapes(sp):
    """Mouth contour for each expression: (outer upper, outer lower, inner) point lists in neck space."""
    W = 0.024 * sp.get('mouth_w', 1.0)
    zc = HC2.z - 0.057
    N = 13
    xs = np.linspace(-1, 1, N)
    full = sp.get('lips', 1.0)

    def onface(x, z, out=0.0):
        return Vector((x, head_surface_y(x, z - HC2.z) + 0.0085 - 0.006 * (x / W) ** 2 + out, z))

    def key(w, top, bot, open_):
        up, lo, inner_t, inner_b = [], [], [], []
        for x in xs:
            xx = w * x
            curve_t, curve_b = top(x), bot(x)
            th_u = 0.0055 * full * (1 - x * x) ** 0.6 + 0.0008
            th_l = 0.0075 * full * (1 - x * x) ** 0.6 + 0.0008
            it = zc + curve_t + open_ * 0.5 * (1 - x * x)
            ib = zc + curve_b - open_ * 1.0 * (1 - x * x)
            inner_t.append(onface(xx, it, -0.002))
            inner_b.append(onface(xx, ib, -0.002))
            up.append(onface(xx, it + th_u, 0.0015 * (1 - x * x)))
            lo.append(onface(xx, ib - th_l, 0.002 * (1 - x * x)))
        return up, lo, inner_t, inner_b
    shapes = {
        'neutral': key(W, lambda x: 0.0003, lambda x: -0.0003, 0.0),
        'smile': key(W * 1.18, lambda x: 0.0012 + 0.0045 * x * x, lambda x: -0.0004 + 0.004 * x * x, 0.0012),
        'open': key(W * 0.92, lambda x: 0.0, lambda x: 0.0, 0.009),
        'frown': key(W * 1.02, lambda x: 0.0003 - 0.0035 * x * x, lambda x: -0.0003 - 0.0035 * x * x, 0.0),
    }
    return shapes


def lips_object(name, sp, parent, C, lipmat):
    shapes = lip_shapes(sp)
    up, lo, it, ib = shapes['neutral']
    N = len(up)

    def flat(sh):
        u, l, a, b = sh
        return list(u) + list(l) + list(a) + list(b)
    verts = flat(shapes['neutral'])
    faces = []
    U, Lo, A, B = 0, N, 2 * N, 3 * N
    for k in range(N - 1):
        faces.append((U + k, U + k + 1, A + k + 1, A + k))         # upper lip band
        faces.append((B + k, B + k + 1, Lo + k + 1, Lo + k))       # lower lip band
        faces.append((A + k, A + k + 1, B + k + 1, B + k))         # the mouth opening (dark)
    me = bpy.data.meshes.new(name)
    me.from_pydata([tuple(v) for v in verts], [], faces)
    me.materials.append(lipmat)
    me.materials.append(MAT['mouth_dark'])
    for i, p in enumerate(me.polygons):
        p.material_index = 1 if i % 3 == 2 else 0
        p.use_smooth = True
    ob = bpy.data.objects.new(name, me)
    coll(C).objects.link(ob)
    ob.parent = parent
    ob.shape_key_add(name='Basis')
    for kname in ('smile', 'open', 'frown'):
        sk = ob.shape_key_add(name=kname)
        for i, p in enumerate(flat(shapes[kname])):
            sk.data[i].co = p
    md = ob.modifiers.new('sub', 'SUBSURF')
    md.levels, md.render_levels = 0, 1
    return ob


def loft(bm, rings, seg=20, mi=0, caps=True):
    """rings: [(z, cx, cy, rx, ry, power)] - superellipse cross-sections stacked along z."""
    vr = []
    for z, cx, cy, rx, ry, pw in rings:
        r = []
        for k in range(seg):
            t = 2 * math.pi * k / seg
            ct, st = math.cos(t), math.sin(t)
            x = cx + rx * math.copysign(abs(ct) ** (2 / pw), ct)
            y = cy + ry * math.copysign(abs(st) ** (2 / pw), st)
            r.append(bm.verts.new((x, y, z)))
        vr.append(r)
    for r0, r1 in zip(vr[:-1], vr[1:]):
        for k in range(seg):
            f = bm.faces.new((r0[k], r0[(k + 1) % seg], r1[(k + 1) % seg], r1[k]))
            f.material_index = mi
    if caps:
        for r, flip in ((vr[0], True), (vr[-1], False)):
            f = bm.faces.new(r[::-1] if flip else r)
            f.material_index = mi
    return vr


def limb(bm, z0, z1, radii, seg=16, mi=0, bulge=None, flat=1.0):
    """A tapered limb along -z from z0 to z1 with radius keys [(u, r)]."""
    rings = []
    n = 9
    for i in range(n):
        u = i / (n - 1)
        z = z0 + (z1 - z0) * u
        r = np.interp(u, [p[0] for p in radii], [p[1] for p in radii])
        oy = 0.0
        if bulge:
            for (bu, ba, bs) in bulge:
                oy += ba * math.exp(-((u - bu) / bs) ** 2)
        rings.append((z, 0.0, oy * 0.5, r, (r + oy) * flat, 2.0))
    return loft(bm, rings, seg, mi)


def hand_bm(bm, sx, mi=0, curl=0.35):
    """A hand hanging along -z from the wrist (z = -0.25 in elbow space): palm and five fingers."""
    add_sbox(bm, (0, 0.003, -0.292), (0.0135, 0.041, 0.045), e=0.35, u=14, v=10, mi=mi)
    for k, (fy, L) in enumerate(((0.029, 0.075), (0.010, 0.083), (-0.009, 0.079), (-0.027, 0.064))):
        p = Vector((0.0, fy, -0.333))
        d = Vector((-sx * 0.0, 0.0, -1.0))
        r = 0.0085 - 0.0008 * (k == 3)
        for j, seg in enumerate((0.42, 0.33, 0.25)):
            ang = R(curl * (12 + 22 * j))
            d2 = Vector((sx * math.sin(ang), 0.0, -math.cos(ang)))
            q = p + d2 * L * seg
            add_capsule(bm, p, q, r, r * 0.92, seg=8, mi=mi)
            p, r = q, r * 0.92
    t0 = Vector((sx * 0.006, 0.035, -0.268))
    t1 = t0 + Vector((sx * 0.012, 0.022, -0.03))
    t2 = t1 + Vector((sx * 0.006, 0.008, -0.03))
    add_capsule(bm, t0, t1, 0.011, 0.0095, seg=8, mi=mi)
    add_capsule(bm, t1, t2, 0.0095, 0.0085, seg=8, mi=mi)


def subsurf(ob, lv=1, rlv=2):
    md = ob.modifiers.new('sub', 'SUBSURF')
    md.levels, md.render_levels = lv, rlv
    return md


def hair_particles(ob, length, count, children, color_mat, roughness=0.002, clump=0.3):
    ps = ob.modifiers.new('hair', 'PARTICLE_SYSTEM').particle_system
    st = ps.settings
    st.type = 'HAIR'
    st.count = count
    st.hair_length = length
    st.emit_from = 'FACE'
    st.use_advanced_hair = False
    st.factor_random = 0.25
    st.child_type = 'INTERPOLATED'
    st.child_percent = max(1, children // 4)
    st.child_radius = 0.004
    st.rendered_child_count = children
    st.child_length = 0.9
    st.roughness_1 = roughness
    st.roughness_2 = roughness * 0.6
    st.clump_factor = clump
    st.root_radius = 1.0
    st.tip_radius = 0.0
    st.radius_scale = 0.0005
    st.hair_step = 4
    st.display_step = 3
    st.render_step = 3
    st.material = 2                       # the hair colour is the scalp object's second material slot
    return ps


def hair_strands(name, style, parent, C, mat, seed=0):
    """Real strand hair as a Curves object: roots on the scalp, strands combed back and down over the head (short
    styles) or falling to the shoulders (long styles). Positions are in neck-joint space."""
    rng = np.random.default_rng(seed + 7)
    a, b, c = HR2
    n = {'crew': 26000, 'short': 22000, 'long': 16000, 'bob': 16000}[style]
    v = rng.normal(0, 1, (n * 3, 3))
    v /= np.linalg.norm(v, axis=1, keepdims=True)
    pnt = v * np.array([a, b, c]) * np.array([1.0, 0.995, 1.0])
    pnt[:, 0] *= 1 - 0.07 * v[:, 1]
    line = 0.040 + 0.03 * np.maximum(v[:, 1], 0) ** 2 - 0.09 * np.maximum(-v[:, 1], 0)
    side = (np.abs(v[:, 0]) > 0.62) & (v[:, 1] > -0.35) & (v[:, 2] < 0.45)
    ok = (pnt[:, 2] > line) & ~(side & (pnt[:, 2] < 0.05))
    if style in ('long', 'bob'):
        ok = (pnt[:, 2] > 0.02 + 0.03 * np.maximum(v[:, 1], 0)) | ((v[:, 1] < -0.2) & (pnt[:, 2] > -0.06))
    pnt, v = pnt[ok][:n], v[ok][:n]
    m = len(pnt)
    nrm = pnt / np.array([a, b, c]) ** 2
    nrm /= np.linalg.norm(nrm, axis=1, keepdims=True)
    comb = np.array([0.0, -1.0, -0.35])
    t = comb[None, :] - (nrm @ comb)[:, None] * nrm
    if style in ('long', 'bob'):
        cl = np.column_stack([0.45 * np.sign(pnt[:, 0] + 1e-6), -np.ones(m), -0.6 * np.ones(m)])
        t = cl - np.sum(nrm * cl, axis=1)[:, None] * nrm
    side_part = np.where(pnt[:, 0] > 0.012, 1.0, -1.0)
    t[:, 0] += 0.5 * side_part * (pnt[:, 2] > 0.06)
    t /= np.linalg.norm(t, axis=1, keepdims=True) + 1e-9
    t += rng.normal(0, 0.12, t.shape)
    t /= np.linalg.norm(t, axis=1, keepdims=True)
    if style in ('crew', 'short'):
        L = (0.018 if style == 'crew' else 0.035) * rng.uniform(0.7, 1.2, m)
        L *= 1 + 0.6 * (pnt[:, 2] > 0.07) * (v[:, 1] > -0.2)
        K = 4
        P = np.zeros((m, K, 3))
        for k in range(K):
            u = k / (K - 1)
            P[:, k] = pnt + nrm * (0.0022 + 0.0045 * np.sin(u * 1.4)) + t * (L * u)[:, None]
    else:
        # lie along the skull (re-projected onto it) until behind the ears, then fall, pushed clear of the shoulders
        L = (0.30 if style == 'long' else 0.12) * rng.uniform(0.85, 1.1, m)
        KL, KF = 6, 5
        K = KL + KF
        P = np.zeros((m, K, 3))
        q = pnt.copy()
        off = 0.011
        for k in range(KL):
            r = np.linalg.norm(q / np.array([a, b, c]), axis=1)
            surf = q / r[:, None]
            nn = surf / np.array([a, b, c]) ** 2
            nn /= np.linalg.norm(nn, axis=1, keepdims=True)
            P[:, k] = surf + nn * (off * min(1.0, 0.4 + k / 3))
            cl = np.column_stack([0.5 * np.sign(surf[:, 0] + 1e-6), -np.ones(m), -0.25 - 0.5 * (surf[:, 1] < -0.01)])
            tt = cl - np.sum(nn * cl, axis=1)[:, None] * nn
            tt /= np.linalg.norm(tt, axis=1, keepdims=True) + 1e-9
            step = np.where(surf[:, 1] > -0.03, 0.03, 0.012)
            q = surf + tt * step[:, None]
        start = P[:, KL - 1]
        outv = np.column_stack([start[:, 0] * 1.6, np.minimum(start[:, 1], -0.02) * 1.2, np.zeros(m)])
        outv /= np.linalg.norm(outv, axis=1, keepdims=True) + 1e-9
        for k in range(KF):
            u = (k + 1) / KF
            P[:, KL + k] = start + np.column_stack([np.zeros(m), np.zeros(m), -L * u]) + outv * (0.03 * u ** 0.6)
    P += np.array(HC2)[None, None, :]
    cv = bpy.data.hair_curves.new(name)
    cv.add_curves([K] * m)
    cv.position_data.foreach_set('vector', P.reshape(-1).astype(np.float32))
    rad = cv.attributes.new('radius', 'FLOAT', 'POINT')
    rr = np.tile(np.linspace(0.00009, 0.00003, K), m).astype(np.float32)
    rad.data.foreach_set('value', rr)
    cv.materials.append(mat)
    ob = bpy.data.objects.new(name, cv)
    coll(C).objects.link(ob)
    ob.parent = parent
    return ob


def hair_shell(bm, style, mi=0):
    """A sculpted hair shell for people without particle hair (crowds) and long hairstyles."""
    a, b, c = HR2
    vs = add_ellipsoid(bm, HC2 + Vector((0, -0.006, 0.006)), (a * 1.08, b * 1.08, c * 1.06), 28, 20, mi)
    kill = []
    for v in vs:
        p = v.co - HC2
        nyf = p.y / b
        line = (0.040 if style == 'cap' else 0.045) + 0.04 * max(nyf, 0) ** 2 - 0.12 * max(-nyf, 0)
        if style in ('long', 'bob', 'ponytail', 'bun') and nyf < 0.2:
            line = -0.05 - 0.07 * max(-nyf, 0)
        if p.z < line:
            kill.append(v)
    bmesh.ops.delete(bm, geom=kill, context='VERTS')
    if style == 'cap':
        for v in list(bm.verts):
            v.co = HC2 + (v.co - HC2) * 0.952
    if style == 'long':
        add_ellipsoid(bm, HC2 + Vector((0, -0.045, -0.13)), (a * 1.05, 0.055, 0.15), 18, 12, mi)
        for sx in (-1, 1):
            add_ellipsoid(bm, HC2 + Vector((sx * 0.07, -0.01, -0.09)), (0.022, 0.05, 0.12), 12, 10, mi)
    if style == 'bob':
        add_ellipsoid(bm, HC2 + Vector((0, -0.03, -0.05)), (a * 1.12, b * 0.95, 0.09), 20, 12, mi)
    if style == 'ponytail':
        add_ellipsoid(bm, HC2 + Vector((0, -0.11, 0.0)), (0.03, 0.035, 0.04), 12, 8, mi)
        add_ellipsoid(bm, HC2 + Vector((0, -0.125, -0.1)), (0.028, 0.03, 0.1), 12, 8, mi)
    if style == 'bun':
        add_ellipsoid(bm, HC2 + Vector((0, -0.08, 0.1)), (0.04, 0.04, 0.036), 12, 8, mi)


TOPS = {  # (material key, sleeve length 0..1 of the upper arm (1 = long), collar)
    'tee': ('tee', 0.45, 'crew'), 'blazer': ('blazer', 1.0, 'lapel'), 'labcoat': ('labcoat', 1.0, 'lapel'),
    'scrubs': ('scrubs', 0.5, 'v'), 'sweater': ('sweater', 1.0, 'crew'), 'blouse': ('blouse', 1.0, 'v'),
    'jacket': ('jacket', 1.0, 'crew'),
}


def build_human(name, spec, collection, hair_particles_on=True):
    """spec: sex ('m'/'f'), skin, hair (material), hstyle ('crew','long','bob','ponytail','bun','short'), top, topmat,
    bottom ('trousers','skirt','sweats'), bottommat, shoes, height, girth, iris, face params (jaw, chin, nose_w, nose_l,
    lips, mouth_w), stubble."""
    C = collection
    fem = 1.0 if spec.get('sex', 'm') == 'f' else 0.0
    g = spec.get('girth', 1.0)
    sk = MAT[spec['skin']]
    topm = MAT[spec.get('topmat', 'tee_grey')]
    botm = MAT[spec.get('bottommat', 'trousers_navy')]
    shoe = MAT[spec.get('shoes', 'shoe_black')]
    hairm = MAT[spec.get('hair', 'hair_dark')]
    J = {}
    J['root'] = empty(name + '_root', (0, 0, 0), C)
    J['root'].rotation_mode = 'XYZ'
    scl = spec.get('height', 1.0)
    J['root'].scale = (scl, scl, scl)
    J['hips'] = empty(name + '_hips', (0, 0, 0.95), C, J['root'])
    J['spine'] = empty(name + '_spine', (0, 0, 0.0), C, J['hips'])
    J['chest'] = empty(name + '_chest', (0, 0, 0.25), C, J['spine'])
    J['neck'] = empty(name + '_neck', (0, 0, 0.27), C, J['chest'])
    shx = (0.19 - 0.02 * fem) * g ** 0.5
    for s, sx in (('R', 1), ('L', -1)):
        J['sh' + s] = empty(f'{name}_sh{s}', (sx * shx, 0, 0.19), C, J['chest'])
        J['el' + s] = empty(f'{name}_el{s}', (0, 0, -0.28), C, J['sh' + s])
        J['hip' + s] = empty(f'{name}_hip{s}', (sx * (0.092 + 0.012 * fem) * g ** 0.5, 0, -0.05), C, J['hips'])
        J['kn' + s] = empty(f'{name}_kn{s}', (0, 0, -0.43), C, J['hip' + s])
    for j in J.values():
        j.rotation_mode = 'XYZ'
    P = {}
    sub_lv = spec.get('subdiv', 2)
    # --- torso (clothed)
    hw = 1.0 + 0.12 * fem
    bm = bmesh.new()
    if spec.get('bottom', 'trousers') == 'skirt':
        loft(bm, [(-0.46, 0, 0.0, 0.175 * hw * g, 0.13 * g, 2.3), (-0.12, 0, 0.0, 0.172 * hw * g, 0.122 * g, 2.3),
                  (0.0, 0, 0.0, 0.17 * hw * g, 0.115 * g, 2.3), (0.07, 0, 0.0, 0.155 * hw * g, 0.11 * g, 2.3)], 24, 0)
    else:
        loft(bm, [(-0.15, 0, 0.0, 0.145 * hw * g, 0.105 * g, 2.3), (-0.06, 0, 0.0, 0.17 * hw * g, 0.12 * g, 2.3),
                  (0.03, 0, 0.0, 0.165 * hw * g, 0.115 * g, 2.3), (0.08, 0, 0.0, 0.155 * hw * g, 0.11 * g, 2.3)], 24, 0)
    P['pelvis'] = part(name + '_pelvis', bm, botm, J['hips'], C, smooth=True)
    subsurf(P['pelvis'], 1, sub_lv - 1 if sub_lv > 1 else 1)
    waist = 1.0 - 0.13 * fem
    bm = bmesh.new()
    loft(bm, [(-0.02, 0, 0.0, 0.152 * g, 0.108 * g, 2.4), (0.10, 0, 0.004, 0.145 * waist * g, 0.104 * g, 2.4),
              (0.21, 0, 0.008, 0.158 * g, 0.112 * g, 2.4), (0.29, 0, 0.008, 0.165 * g, 0.115 * g, 2.4)], 24, 0)
    P['belly'] = part(name + '_belly', bm, topm, J['spine'], C, smooth=True)
    subsurf(P['belly'], 1, 1)
    bm = bmesh.new()
    cw = (1.0 - 0.08 * fem) * g ** 0.5
    loft(bm, [(-0.05, 0, 0.008, 0.162 * g, 0.114 * g, 2.4), (0.06, 0, 0.012, 0.175 * cw, 0.122 * g, 2.5),
              (0.16, 0, 0.0, 0.19 * cw, 0.115 * g, 2.3), (0.215, 0, -0.008, 0.185 * cw, 0.095, 2.2), (0.24, 0, -0.01, 0.15 * cw, 0.085, 2.4),
              (0.255, 0, -0.012, 0.09, 0.07, 2.0), (0.28, 0, -0.012, 0.062, 0.058, 2.0)], 24, 0)
    for sx in (-1, 1):
        add_ellipsoid(bm, (sx * (shx - 0.02), 0, 0.18), (0.05, 0.055, 0.055), 14, 10)
        if fem:
            add_ellipsoid(bm, (sx * 0.05, 0.085 * g, 0.07), (0.058, 0.045, 0.052), 14, 10)
    P['chest'] = part(name + '_chestm', bm, topm, J['chest'], C, smooth=True)
    subsurf(P['chest'], 1, 1)
    # collar / lapels / tie details
    top = spec.get('top', 'tee')
    if top in ('blazer', 'labcoat'):
        bm = bmesh.new()
        for sx in (-1, 1):
            add_quad(bm, [(sx * 0.012, 0.128 * g, 0.02), (sx * 0.075, 0.118 * g, 0.215), (sx * 0.04, 0.105 * g, 0.255)], mi=0)
            add_quad(bm, [(sx * 0.012, 0.13 * g, 0.02), (sx * 0.04, 0.106 * g, 0.255), (sx * 0.005, 0.1, 0.24)], mi=1)
        ob = part(name + '_lapels', bm, [topm, MAT[spec.get('shirtmat', 'shirt_white')]], J['chest'], C, smooth=False)
        if top == 'labcoat':
            bm = bmesh.new()
            add_cyl(bm, 0.18 * hw * g, 0.215 * hw * g, 0.55, seg=24, matrix=Matrix.Translation((0, 0, -0.32)), caps=False)
            P['coat'] = part(name + '_coatskirt', bm, topm, J['hips'], C)
    if top == 'tee' or top == 'sweater':
        bm = bmesh.new()
        add_cyl(bm, 0.064, 0.064, 0.012, seg=20, matrix=Matrix.Translation((0, -0.012, 0.272)), caps=False)
        part(name + '_collar', bm, topm, J['chest'], C)
    # neck
    bm = bmesh.new()
    loft(bm, [(-0.03, 0, 0.0, 0.05 - 0.006 * fem, 0.05, 2.0), (0.05, 0, 0.004, 0.047 - 0.006 * fem, 0.048, 2.0),
              (0.11, 0, 0.012, 0.045, 0.046, 2.0)], 18, 0)
    P['neckm'] = part(name + '_neckm', bm, sk, J['neck'], C, smooth=True)
    subsurf(P['neckm'], 1, 1)
    # --- head
    sp = dict(jaw=spec.get('jaw', 1.0 - 0.15 * fem), chin=spec.get('chin', 1.0 - 0.3 * fem), fem=fem, nose_w=spec.get('nose_w', 1.0 - 0.15 * fem),
              nose_l=spec.get('nose_l', 1.0 - 0.1 * fem), lips=spec.get('lips', 1.0 + 0.35 * fem), mouth_w=spec.get('mouth_w', 1.0))
    bm = bmesh.new()
    head_mesh(bm, sp)
    for sx in (-1, 1):
        ear_mesh(bm, sx)
    hm = MAT[spec['skin'] + ('_stubble' if spec.get('stubble') else '_face')] if (spec['skin'] + ('_stubble' if spec.get('stubble') else '_face')) in MAT else sk
    P['head'] = part(name + '_head', bm, hm, J['neck'], C, smooth=True)
    subsurf(P['head'], 0, min(sub_lv, 1))
    # hair
    hs = spec.get('hstyle', 'crew')
    if hair_particles_on and hs in ('crew', 'short', 'long', 'bob'):
        bm = bmesh.new()
        hair_shell(bm, 'cap' if hs in ('crew', 'short') else hs)
        if hs not in ('crew', 'short'):
            for v in bm.verts:
                v.co = HC2 + (v.co - HC2) * 0.952
        P['hairbase'] = part(name + '_hairbase', bm, MAT['scalp_dark'] if hs in ('crew', 'short') else hairm, J['neck'], C, smooth=True)
        P['hair'] = hair_strands(name + '_strands', hs, J['neck'], C, hairm, seed=len(name))
    elif hs != 'none':
        bm = bmesh.new()
        hair_shell(bm, hs)
        P['hair'] = part(name + '_hair', bm, hairm, J['neck'], C, smooth=True)
        subsurf(P['hair'], 1, 1)
    # --- face: eyes, lids, brows, lips
    F = {}
    eyem = MAT['eye_' + spec.get('iris', 'brown')]
    for s, sx in (('R', 1), ('L', -1)):
        ex = sx * EYE_X
        c = Vector((ex, head_surface_y(ex, EYE_Z) - 0.0105, HC2.z + EYE_Z))
        bm = bmesh.new()
        add_sphere(bm, EYE_R, 20, 14)
        e = part(f'{name}_eye{s}', bm, eyem, J['neck'], C, loc=c)
        e.rotation_mode = 'XYZ'
        F['eye' + s] = e
        bm = bmesh.new()
        vs = add_sphere(bm, EYE_R * 1.1, 24, 16)
        bmesh.ops.delete(bm, geom=[v for v in vs if v.co.z < -0.0004], context='VERTS')
        add_cyl(bm, EYE_R * 1.16, EYE_R * 1.22, 0.0007, seg=24, matrix=Matrix.Translation((0, 0, -0.0002)), caps=False, mi=1)
        lid = part(f'{name}_lid{s}', bm, [sk, MAT['lash']], J['neck'], C, loc=c)
        lid.rotation_mode = 'XYZ'
        F['lid' + s] = lid
        bm = bmesh.new()
        add_ellipsoid(bm, (0, 0, 0), (EYE_R * 1.08, EYE_R * 1.08, EYE_R * 1.08), 20, 12)
        bmesh.ops.delete(bm, geom=[v for v in bm.verts if v.co.z > -EYE_R * 0.32], context='VERTS')
        part(f'{name}_lowlid{s}', bm, sk, J['neck'], C, loc=c)
        bm = bmesh.new()
        thick = 0.0019 if not fem else 0.0013
        pts = [Vector((sx * (-0.016 + 0.034 * u), 0.0, 0.003 * math.sin(math.pi * u) - 0.002 * u)) for u in np.linspace(0, 1, 8)]
        for k in range(len(pts) - 1):
            add_capsule(bm, pts[k], pts[k + 1], thick * (1.3 - 0.6 * k / 7), seg=6)
        bz = EYE_Z + 0.0175
        b_ = part(f'{name}_brow{s}', bm, MAT[spec.get('browmat', spec.get('hair', 'hair_dark'))], J['neck'], C,
                  loc=Vector((ex + sx * 0.002, head_surface_y(ex, bz) + 0.0058, HC2.z + bz)))
        b_.rotation_mode = 'XYZ'
        F['brow' + s] = b_
        F['brow0' + s] = Vector(b_.location)
    F['mouth'] = lips_object(name + '_mouth', sp, J['neck'], C, MAT['lips_f' if fem else 'lips_m'])
    # --- arms and hands
    sleeve = TOPS.get(top, ('tee', 1.0, 'crew'))[1]
    ag = (1.0 - 0.15 * fem) * g ** 0.5
    for s, sx in (('R', 1), ('L', -1)):
        bm = bmesh.new()
        limb(bm, 0.0, -0.285, [(0, 0.058 * ag), (0.2, 0.057 * ag), (0.6, 0.05 * ag), (1, 0.043 * ag)], 16, 1)
        if sleeve > 0:
            limb(bm, 0.0, -0.285 * min(sleeve, 1.0) - 0.005, [(0, 0.062 * ag), (1, (0.058 if sleeve < 1 else 0.05) * ag)], 16, 0)
        part(f'{name}_uarm{s}', bm, [topm, sk], J['sh' + s], C, smooth=True)
        bm = bmesh.new()
        limb(bm, 0.01, -0.255, [(0, 0.044 * ag), (0.25, 0.046 * ag), (0.8, 0.033 * ag), (1, 0.028 * ag)], 16, 1)
        if sleeve >= 1:
            limb(bm, 0.02, -0.235, [(0, 0.047 * ag), (1, 0.036 * ag)], 16, 0)
        hand_bm(bm, sx, mi=1)
        fa = part(f'{name}_farm{s}', bm, [topm, sk], J['el' + s], C, smooth=True)
        subsurf(fa, 0, 1)
        # legs
        bm = bmesh.new()
        lg = (1.0 + 0.06 * fem) * g ** 0.5
        if spec.get('bottom') == 'skirt':
            limb(bm, 0.0, -0.44, [(0, 0.08 * lg), (0.5, 0.068 * lg), (1, 0.05)], 16, 1)
        else:
            limb(bm, 0.03, -0.44, [(0, 0.095 * lg), (0.5, 0.08 * lg), (1, 0.062)], 16, 0)
        part(f'{name}_thigh{s}', bm, [botm, MAT[spec['skin'] + '_leg'] if spec.get('bottom') == 'skirt' else sk], J['hip' + s], C, smooth=True)
        bm = bmesh.new()
        if spec.get('bottom') == 'skirt':
            limb(bm, 0.0, -0.4, [(0, 0.05), (0.25, 0.053), (0.75, 0.036), (1, 0.03)], 16, 1)
        else:
            limb(bm, 0.02, -0.4, [(0, 0.062), (0.25, 0.064), (0.75, 0.05), (1, 0.047)], 16, 0)
        add_sbox(bm, (0, 0.045, -0.43), (0.045, 0.12, 0.04), e=0.35, mi=2)
        part(f'{name}_shin{s}', bm, [botm, MAT[spec['skin'] + '_leg'] if spec.get('bottom') == 'skirt' else sk, shoe], J['kn' + s], C, smooth=True)
    CH[name] = dict(J=J, F=F, P=P, spec=spec)
    pose(name, {})
    return CH[name]


def bake_human(name, tcoll, pose_dict):
    """Pose a built human, then merge all of its meshes (modifiers applied, subdivision 0) into one static mesh in a
    template collection - for instanced crowds. The original objects are removed."""
    pose(name, pose_dict)
    bpy.context.view_layer.update()
    dg = bpy.context.evaluated_depsgraph_get()
    root = CH[name]['J']['root']
    inv = root.matrix_world.inverted()
    bm = bmesh.new()
    mats = []
    obs = [o for o in bpy.data.objects if o.name.startswith(name + '_') and o.type == 'MESH']
    for o in obs:
        for m in o.modifiers:
            if m.type == 'SUBSURF':
                m.levels = 0
            if m.type == 'PARTICLE_SYSTEM':
                m.show_render = m.show_viewport = False
    bpy.context.view_layer.update()
    dg = bpy.context.evaluated_depsgraph_get()
    for o in obs:
        if o.data.shape_keys:
            pass
        ev = o.evaluated_get(dg)
        me = ev.to_mesh()
        me.transform(inv @ o.matrix_world)
        offs = len(mats)
        for m in o.data.materials:
            mats.append(m)
        for p in me.polygons:
            p.material_index += offs
        bm.from_mesh(me)
        ev.to_mesh_clear()
    out = bpy.data.meshes.new(name + '_baked')
    bm.to_mesh(out)
    bm.free()
    for m in mats:
        out.materials.append(m)
    ob = bpy.data.objects.new(name + '_baked', out)
    coll(tcoll).objects.link(ob)
    for o in [o for o in bpy.data.objects if o.name.startswith(name + '_') and o.name != name + '_baked']:
        bpy.data.objects.remove(o, do_unlink=True)
    CH.pop(name, None)
    return ob


# --- materials for people ---------------------------------------------------------------------------------------------
SKINS = {'skinA': (0.80, 0.58, 0.46), 'skinB': (0.66, 0.45, 0.33), 'skinC': (0.48, 0.31, 0.21), 'skinD': (0.30, 0.18, 0.12),
         'skinE': (0.86, 0.68, 0.57), 'skinH': (0.70, 0.49, 0.37)}


def skin_real(name, color, stubble=False, sss=0.25, blush=False):
    """Skin: subsurface scattering, fine pore bump, colour variation; optional stubble on the jaw and upper lip."""
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    n1 = noise(nt, 60.0, 3.0, 0.6, vec=oc)
    n2 = noise(nt, 9.0, 2.0, 0.5, vec=oc)
    base = mixc(nt, mth(nt, 'MULTIPLY', n2, 0.25), rgba(color), rgba([c * 0.82 for c in color]))
    if blush:
        s_ = sep(nt, oc)
        ch = mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', s_.outputs['Y'], 0.07), mth(nt, 'LESS_THAN', mth(nt, 'ABSOLUTE', mth(nt, 'SUBTRACT', s_.outputs['Z'], 0.10)), 0.03))
        base = mixc(nt, mth(nt, 'MULTIPLY', ch, 0.18), base, (0.75, 0.30, 0.28, 1))
    if stubble:
        s_ = sep(nt, oc)
        z, y, x = s_.outputs['Z'], s_.outputs['Y'], s_.outputs['X']
        soft = lambda v, a, b: mth(nt, 'MULTIPLY', mth(nt, 'SUBTRACT', v, a), 1.0 / (b - a), clamp=True)
        below_nose = soft(z, 0.086, 0.074)                    # 1 below the nose line, fading over 12 mm
        above_neck = soft(z, 0.0, 0.03)
        cheek = mth(nt, 'MULTIPLY', soft(y, 0.0, 0.05), soft(mth(nt, 'ABSOLUTE', x), 0.075, 0.05))
        mask = mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', below_nose, above_neck), cheek)
        dots = mth(nt, 'GREATER_THAN', noise(nt, 2600.0, 1.0, 0.5, vec=oc), 0.5)
        base = mixc(nt, mth(nt, 'MULTIPLY', mask, mth(nt, 'ADD', 0.18, mth(nt, 'MULTIPLY', dots, 0.32))), base, (0.10, 0.075, 0.06, 1))
    bump = nd(nt, 'ShaderNodeBump', Strength=0.08, Distance=0.0005, Height=n1)
    p = principled(nt, out, **{'Base Color': base, 'Roughness': 0.48, 'Subsurface Weight': sss, 'Subsurface Scale': 0.006,
                               'Subsurface Radius': (1.0, 0.35, 0.18), 'Specular IOR Level': 0.45, 'Coat Weight': 0.05})
    nt.links.new(bump.outputs[0], p.inputs['Normal'])
    MAT[name] = m
    return m


def eye_mat(name, iris):
    """Eyeball: white sclera with faint veins, an iris with radial fibres and a dark limbal ring, a black pupil, and a
    glossy wet coat. The eye looks along its local +Y."""
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    s_ = sep(nt, oc)
    d = nd(nt, 'ShaderNodeVectorMath', p_operation='LENGTH', Vector=comb(nt, s_.outputs['X'], 0.0, s_.outputs['Z'])).outputs['Value']
    front = mth(nt, 'GREATER_THAN', s_.outputs['Y'], 0.0)
    ang = mth(nt, 'ARCTAN2', s_.outputs['Z'], s_.outputs['X'])
    fib = nd(nt, 'ShaderNodeTexNoise', Scale=1.0, Detail=4.0, Vector=comb(nt, mth(nt, 'MULTIPLY', ang, 18.0), mth(nt, 'MULTIPLY', d, 400.0), 0.0)).outputs['Fac']
    irc = mixc(nt, fib, rgba([c * 0.55 for c in iris]), rgba([min(1, c * 1.5) for c in iris]))
    irc = mixc(nt, mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', d, 0.0050), 0.8), irc, (0.02, 0.015, 0.012, 1))
    sclera = mixc(nt, mth(nt, 'MULTIPLY', noise(nt, 300.0, 2.0, 0.5, vec=oc), 0.15), (0.86, 0.82, 0.78, 1), (0.8, 0.45, 0.42, 1))
    col = mixc(nt, mth(nt, 'MULTIPLY', front, mth(nt, 'LESS_THAN', d, 0.0058)), sclera, irc)
    col = mixc(nt, mth(nt, 'MULTIPLY', front, mth(nt, 'LESS_THAN', d, 0.0022)), col, (0.005, 0.005, 0.005, 1))
    principled(nt, out, **{'Base Color': col, 'Roughness': 0.35, 'Coat Weight': 1.0, 'Coat Roughness': 0.02, 'Specular IOR Level': 0.6})
    MAT[name] = m


def hair_mat(name, melanin, redness=0.15, rough=0.35):
    m, nt, out = new_mat(name)
    h = nd(nt, 'ShaderNodeBsdfHairPrincipled')
    h.parametrization = 'MELANIN'
    h.inputs['Melanin'].default_value = melanin
    h.inputs['Melanin Redness'].default_value = redness
    h.inputs['Roughness'].default_value = rough
    h.inputs['Radial Roughness'].default_value = 0.4
    # on meshes (hair shells) Cycles needs a surface BSDF: strands of colour with an anisotropic sheen
    oc = obj_coord(nt)
    s_ = sep(nt, oc)
    strands = nd(nt, 'ShaderNodeTexWave', Scale=180.0, Distortion=3.0, Detail=4.0, Vector=oc, p_wave_type='BANDS', p_bands_direction='Z').outputs['Fac']
    lum = 0.45 * (1 - melanin) ** 1.5 + 0.012
    base = (lum * (1 + redness * 1.6), lum * (1 + redness * 0.5), lum * 0.9)
    sh = principled(nt, None, **{'Base Color': mixc(nt, mth(nt, 'MULTIPLY', strands, 0.6), rgba([c * 0.6 for c in base]), rgba(base)),
                                 'Roughness': 0.38, 'Anisotropic': 0.8, 'Specular IOR Level': 0.6, 'Coat Weight': 0.1})
    ip = nd(nt, 'ShaderNodeHairInfo').outputs['Is Strand']
    mx = nd(nt, 'ShaderNodeMixShader', Fac=ip)
    nt.links.new(sh.outputs[0], mx.inputs[1])
    nt.links.new(h.outputs[0], mx.inputs[2])
    nt.links.new(mx.outputs[0], out.inputs['Surface'])
    MAT[name] = m


def fabric(name, color, rough=0.85, weave=140.0, sheen=0.25):
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    n = noise(nt, weave, 2.0, 0.5, vec=oc)
    n2 = noise(nt, 12.0, 3.0, 0.5, vec=oc)
    base = mixc(nt, mth(nt, 'ADD', mth(nt, 'MULTIPLY', n, 0.12), mth(nt, 'MULTIPLY', n2, 0.12)), rgba(color), rgba([c * 0.78 for c in color]))
    bump = nd(nt, 'ShaderNodeBump', Strength=0.15, Distance=0.001, Height=n)
    p = principled(nt, out, **{'Base Color': base, 'Roughness': rough, 'Sheen Weight': sheen, 'Sheen Tint': rgba(color)})
    nt.links.new(bump.outputs[0], p.inputs['Normal'])
    MAT[name] = m


