def instancer(name, P, var, yaw, scl, tcoll, collection):
    """Geometry-nodes instancer: one point per instance; per-point template index, yaw and scale (as attributes, so
    the yaw can be changed every frame from Python)."""
    n = len(P)
    me = bpy.data.meshes.new(name)
    me.from_pydata(np.asarray(P, float).tolist(), [], [])
    for an, typ, vals in (('var', 'INT', var), ('yaw', 'FLOAT', yaw), ('scl', 'FLOAT', scl)):
        a = me.attributes.new(an, typ, 'POINT')
        a.data.foreach_set('value', np.asarray(vals, np.int32 if typ == 'INT' else np.float32))
    ob = bpy.data.objects.new(name, me)
    coll(collection).objects.link(ob)
    ng = bpy.data.node_groups.new(name + '_gn', 'GeometryNodeTree')
    ng.interface.new_socket('Geometry', in_out='INPUT', socket_type='NodeSocketGeometry')
    ng.interface.new_socket('Geometry', in_out='OUTPUT', socket_type='NodeSocketGeometry')
    N = ng.nodes
    gi, go = N.new('NodeGroupInput'), N.new('NodeGroupOutput')
    ci = N.new('GeometryNodeCollectionInfo')
    ci.inputs['Collection'].default_value = COLL[tcoll]
    ci.inputs['Separate Children'].default_value = True
    ci.inputs['Reset Children'].default_value = True
    io = N.new('GeometryNodeInstanceOnPoints')
    io.inputs['Pick Instance'].default_value = True

    def attr(an, typ):
        x = N.new('GeometryNodeInputNamedAttribute')
        x.data_type = typ
        x.inputs['Name'].default_value = an
        return x.outputs['Attribute']
    cx = N.new('ShaderNodeCombineXYZ')
    ng.links.new(attr('yaw', 'FLOAT'), cx.inputs['Z'])
    ng.links.new(gi.outputs[0], io.inputs['Points'])
    ng.links.new(ci.outputs[0], io.inputs['Instance'])
    ng.links.new(attr('var', 'INT'), io.inputs['Instance Index'])
    ng.links.new(cx.outputs[0], io.inputs['Rotation'])
    ng.links.new(attr('scl', 'FLOAT'), io.inputs['Scale'])
    ng.links.new(io.outputs['Instances'], go.inputs[0])
    md = ob.modifiers.new('GN', 'NODES')
    md.node_group = ng
    return ob


def set_attr(ob, an, vals):
    ob.data.attributes[an].data.foreach_set('value', np.asarray(vals, np.float32))
    ob.data.update()



def tower_block(bm, x0, y0, x1, y1, h, rng):
    add_box(bm, x0, y0, 0.0, x1, y1, min(h, 14.0))
    if h > 14:
        s = rng.uniform(0.0, 0.12)
        w, l = x1 - x0, y1 - y0
        add_box(bm, x0 + w * s, y0 + l * s, 14.0, x1 - w * s, y1 - l * s, h)


def city_blocks(C, centre, radius, clear, seed, tall=1.0):
    """Towers on a grid around `centre`, leaving the rectangle `clear` (x0, y0, x1, y1) empty."""
    rng = np.random.default_rng(seed)
    bms = {k: bmesh.new() for k in ('tower_glass', 'tower_dark', 'tower_stone')}
    for i in range(-radius, radius + 1):
        for j in range(-radius, radius + 1):
            cx, cy = centre.x + i * 70.0, centre.y + j * 70.0
            if clear[0] - 30 < cx < clear[2] + 30 and clear[1] - 30 < cy < clear[3] + 30:
                continue
            for (ox, oy) in ((-17, -17), (17, -17), (-17, 17), (17, 17)):
                if rng.random() < 0.1:
                    continue
                w, l = rng.uniform(16, 28), rng.uniform(16, 28)
                x, y = cx + ox, cy + oy
                h = (20 + 40 * rng.random() + 120 * rng.random() ** 2) * tall
                k = 'tower_glass' if rng.random() < 0.5 else ('tower_dark' if rng.random() < 0.5 else 'tower_stone')
                tower_block(bms[k], x - w / 2, y - l / 2, x + w / 2, y + l / 2, h, rng)
    for k, bm in bms.items():
        obj_from_bm(f'{C}_{k}', bm, MAT[k], C)


def street_furniture(C, x0, x1, y_kerb, side, lamps=True, trees=True, seed=0):
    rng = np.random.default_rng(seed)
    bm = bmesh.new()
    for x in np.arange(x0, x1, 18.0):
        if lamps:
            lamp_post(bm, x, y_kerb + side * 0.6, z0=0.15, side=-side)
    obj_from_bm(f'{C}_lamps{seed}', bm, [MAT['darksteel'], MAT['lamp_off']], C, smooth=True)
    if trees:
        for k, x in enumerate(np.arange(x0 + 9, x1, 18.0)):
            info = None
            bm = bmesh.new()
            add_cyl(bm, 0.14, 0.1, 3.0, seg=8, matrix=Matrix.Translation((x, y_kerb + side * 1.2, 1.65)))
            obj_from_bm(f'{C}_trunk{seed}_{k}', bm, MAT['bark'], C, smooth=True)
            bm = bmesh.new()
            for j in range(4):
                add_sphere(bm, rng.uniform(1.1, 1.6), 10, 8, Matrix.Translation((x + rng.normal(0, 0.6), y_kerb + side * 1.2 + rng.normal(0, 0.6), 3.6 + rng.uniform(0, 1.2))))
            obj_from_bm(f'{C}_crown{seed}_{k}', bm, MAT['canopy'], C, smooth=True)


def road(C, x0, x1, y0, y1, centre_line=True):
    bm = bmesh.new()
    add_box(bm, x0, y0, -0.1, x1, y1, 0.0)
    obj_from_bm(f'{C}_road', bm, MAT['asphalt'], C)
    if centre_line:
        bm = bmesh.new()
        ym = (y0 + y1) / 2
        for x in np.arange(x0, x1, 6.0):
            add_box(bm, x, ym - 0.07, 0.0, x + 3.0, ym + 0.07, 0.012)
        obj_from_bm(f'{C}_lines', bm, MAT['road_paint'], C)


def build_city():
    C = 'City'
    road(C, -150, 150, -16.0, -4.0)
    bm = bmesh.new()
    add_box(bm, -150, -4.0, 0.0, 150, 0.0, 0.15)
    add_box(bm, -150, -20.0, 0.0, 150, -16.0, 0.15)
    obj_from_bm('Pavements', bm, MAT['paving'], C)
    bm = bmesh.new()
    for y in (-4.0, -16.0):
        add_box(bm, -150, y - 0.15, 0.0, 150, y + 0.15, 0.16)
    obj_from_bm('Kerbs', bm, MAT['kerb'], C)
    # his tower: x -14..14, y 0..20, 40 m; a hole in the south facade for his window
    W = WIN
    bm = bmesh.new()
    for (x0, x1, z0, z1) in ((-14, W['x0'], 0, 40), (W['x1'], 14, 0, 40), (W['x0'], W['x1'], 0, W['z0']), (W['x0'], W['x1'], W['z1'], 40)):
        add_box(bm, x0, 0.0, z0, x1, 0.25, z1)
    add_box(bm, -14, 0.25, 0, 14, 20, 11.9)
    add_box(bm, -14, 0.25, 15.0, 14, 20, 40)
    add_box(bm, -14, 5.1, 11.9, 14, 20, 15.0)
    add_box(bm, -14, 0.25, 11.9, -4.2, 5.1, 15.0)
    add_box(bm, 7.4, 0.25, 11.9, 14, 5.1, 15.0)
    obj_from_bm('HomeTower', bm, MAT['facade_home'], C)
    bm = bmesh.new()
    for z in np.arange(3.0, 40, 3.0):
        add_box(bm, -14.05, -0.2, z - 0.15, 14.05, 0.0, z)
    obj_from_bm('HomeLedges', bm, MAT['concrete'], C)
    card('HomeEntrance', MAT['doorway'], 3.0, 2.8, Vector((0, -0.01, 1.4)), collection=C)
    # the building opposite, its giant screen and the frame round it
    G = GIANT
    bm = bmesh.new()
    add_box(bm, -30, -45, 0, 30, -20.8, 46)
    obj_from_bm('OppBuilding', bm, MAT['tower_stone'], C)
    w, h = G['x1'] - G['x0'], G['z1'] - G['z0']
    SETS['giant'] = card('GiantScreen', MAT['scr_giant'], w, h, Vector((0, G['y'], (G['z0'] + G['z1']) / 2)), yaw=180, collection=C)
    SETS['giant_portrait'] = card('GiantPortrait', MAT['portrait_board'], w * 704 / 2048, h * 864 / 1152,
                                  Vector((G['x1'] - w * 440 / 2048, G['y'] + 0.05, G['z1'] - h * 630 / 1152)), yaw=180, collection=C)
    bm = bmesh.new()
    add_box(bm, G['x0'] - 0.8, G['y'] - 0.6, G['z0'] - 0.8, G['x1'] + 0.8, G['y'] - 0.05, G['z1'] + 0.8)
    obj_from_bm('GiantFrame', bm, MAT['darksteel'], C)
    lt = bpy.data.lights.new('GiantLight', 'AREA')
    lt.shape, lt.size, lt.size_y, lt.energy, lt.color = 'RECTANGLE', w, h, 0.0, (1.0, 0.85, 0.7)
    lo = bpy.data.objects.new('GiantLight', lt)
    lo.location = (0, G['y'] + 1.0, (G['z0'] + G['z1']) / 2)
    lo.rotation_euler = (R(90), 0, 0)
    lo.visible_camera = False
    coll(C).objects.link(lo)
    SETS['giant_light'] = lo
    # neighbours along the street, and the city beyond
    bm = bmesh.new()
    for x0 in (-150, -110, -70, 30, 70, 110):
        tower_block(bm, x0 + 2, 0.5, x0 + 38, 30, 30 + (x0 % 7) * 6, np.random.default_rng(int(abs(x0))))
    for x0 in (-150, -110, -70, 40, 80, 120):
        tower_block(bm, x0 + 2, -60, x0 + 36, -21, 25 + (x0 % 5) * 8, np.random.default_rng(int(abs(x0)) + 1))
    obj_from_bm('StreetBlocks', bm, MAT['tower_glass'], C)
    city_blocks('City', Vector((0, 0, 0)), 5, (-160, -70, 160, 40), 11)
    street_furniture(C, -120, 120, -4.0, -1, seed=1)
    street_furniture(C, -120, 120, -16.0, 1, seed=2)
    # news vans, satellite dishes, camera tripods (the reporters themselves are instanced people)
    SETS['vans'] = []
    for k, (x, yaw) in enumerate(((-9.0, 90), (7.5, 90), (19.0, 92), (-21.0, 88))):
        bm = bmesh.new()
        add_sbox(bm, (0, 0, 1.45), (1.05, 2.9, 1.3), e=0.15, mi=0)
        add_box(bm, -1.0, 2.0, 1.2, 1.0, 2.95, 2.3, mi=1)
        add_cyl(bm, 0.05, 0.05, 1.2, seg=8, matrix=Matrix.Translation((0, -1.0, 3.3)), mi=2)
        add_cyl(bm, 0.75, 0.2, 0.25, seg=20, matrix=Matrix.Translation((0, -1.0, 3.95)) @ Matrix.Rotation(R(60), 4, 'X'), mi=2)
        for wy in (-1.8, 1.8):
            for wx in (-1.0, 1.0):
                add_cyl(bm, 0.36, 0.36, 0.25, seg=14, matrix=Matrix.Translation((wx, wy, 0.38)) @ Matrix.Rotation(R(90), 4, 'Y'), mi=3)
        van = obj_from_bm(f'Van{k}', bm, [MAT['van_white'], MAT['window'], MAT['steel'], MAT['rubber']], C, smooth=False)
        van.location = (x, -11.0 + (k % 2) * 3.5, 0)
        van.rotation_euler = (0, 0, R(yaw))
        card(f'VanLogo{k}', MAT['ch_logo'], 1.6, 0.5, Vector((x, -11.0 + (k % 2) * 3.5 - 1.08 * (1 if yaw < 90 else 1), 1.9)), collection=C)
    # helicopters (rotors spin in the frame handler)
    SETS['helis'] = [helicopter(f'Heli{k}', C) for k in range(3)]
    # cars parked along the far kerb
    for k, x in enumerate((-60, -44, -28, 26, 44, 63)):
        make_car(f'PCar{k}', C, (x, -14.7, 0), 90, ('car_white', 'car_black', 'car_red', 'car_grey', 'car_blue', 'car_silver')[k % 6])


def helicopter(name, C):
    root = empty(name, (0, 0, -100), C)
    root.rotation_mode = 'XYZ'
    bm = bmesh.new()
    add_sbox(bm, (0, 0.3, 0), (0.85, 1.9, 0.9), e=0.45, mi=0)
    add_capsule(bm, (0, -1.3, 0.25), (0, -6.0, 0.55), 0.32, 0.12, seg=10, mi=0)
    add_sbox(bm, (0, 1.4, 0.1), (0.75, 0.75, 0.7), e=0.5, mi=1)
    for sx in (-1, 1):
        add_capsule(bm, (sx * 0.8, -1.2, -1.1), (sx * 0.8, 2.0, -1.1), 0.06, seg=6, mi=2)
        add_capsule(bm, (sx * 0.75, -0.6, -1.08), (sx * 0.6, -0.6, -0.7), 0.05, seg=6, mi=2)
        add_capsule(bm, (sx * 0.75, 1.3, -1.08), (sx * 0.6, 1.3, -0.7), 0.05, seg=6, mi=2)
    add_box(bm, -0.05, -6.2, 0.4, 0.05, -5.6, 1.4, mi=0)
    add_cyl(bm, 0.1, 0.1, 0.5, seg=8, matrix=Matrix.Translation((0, 0.2, 1.1)), mi=2)
    ob = obj_from_bm(name + '_body', bm, [MAT['van_white'], MAT['window'], MAT['darksteel']], C, smooth=True)
    ob.parent = root
    rot = empty(name + '_rotor', (0, 0.2, 1.38), C, root)
    rot.rotation_mode = 'XYZ'
    bm = bmesh.new()
    add_cyl(bm, 5.4, 5.4, 0.02, seg=40, mi=0)
    ob = obj_from_bm(name + '_disc', bm, MAT['rotor_blur'], C)
    ob.parent = rot
    bm = bmesh.new()
    for a in (0, 90):
        add_box(bm, -5.3, -0.1, -0.02, 5.3, 0.1, 0.02, matrix=Matrix.Rotation(R(a), 4, 'Z'))
    ob = obj_from_bm(name + '_blades', bm, MAT['darksteel'], C)
    ob.parent = rot
    sp = spot_light(name + '_spot', (0, 0, -100), (0, 0, -101), 0.0, 15, (0.9, 0.95, 1.0), C, blend=0.3, radius=0.1)
    return dict(root=root, rotor=rot, spot=sp)


def build_flat():
    """His bedroom (behind the window in the tower's south wall) and the bathroom next door."""
    C = 'Flat'
    F_ = FLAT
    z0, z1 = F_['z0'], F_['z1']
    bm = bmesh.new()
    add_box(bm, F_['x0'], F_['y0'], z0 - 0.1, BATH['x1'], F_['y1'], z0, mi=0)
    add_box(bm, F_['x0'], F_['y0'], z1, BATH['x1'], F_['y1'], z1 + 0.1, mi=1)
    add_box(bm, F_['x0'] - 0.1, F_['y0'], z0, F_['x0'], F_['y1'], z1, mi=2)
    add_box(bm, F_['x0'], F_['y1'], z0, BATH['x1'], F_['y1'] + 0.1, z1, mi=2)
    add_box(bm, F_['x1'], F_['y0'], z0, F_['x1'] + 0.15, F_['y1'], z1, mi=2)
    add_box(bm, BATH['x1'], F_['y0'], z0, BATH['x1'] + 0.1, F_['y1'], z1, mi=3)
    add_box(bm, F_['x0'], F_['y0'] - 0.05, z0, WIN['x0'], F_['y0'], z1, mi=2)
    add_box(bm, WIN['x1'], F_['y0'] - 0.05, z0, BATH['x1'], F_['y0'], z1, mi=2)
    obj_from_bm('FlatShell', bm, [MAT['floor_wood'], MAT['ceiling_white'], MAT['wall_warm'], MAT['tile_white']], C)
    bm = bmesh.new()
    add_box(bm, WIN['x0'], -0.05, WIN['z0'], WIN['x1'], 0.3, WIN['z0'] + 0.06)
    add_box(bm, WIN['x0'], -0.05, WIN['z1'] - 0.06, WIN['x1'], 0.3, WIN['z1'])
    add_box(bm, -0.03, -0.05, WIN['z0'], 0.03, 0.3, WIN['z1'])
    obj_from_bm('WinFrame', bm, MAT['frame_dark'], C)
    card('WinGlass', MAT['window_glass'], WIN['x1'] - WIN['x0'], WIN['z1'] - WIN['z0'], Vector((0, 0.12, (WIN['z0'] + WIN['z1']) / 2)), collection=C)
    # curtains either side of the window (one is pulled back in the peek shot)
    SETS['curtains'] = []
    for k, sx in enumerate((-1, 1)):
        verts, faces = [], []
        n = 24
        for i in range(n + 1):
            u = i / n
            for zz in (WIN['z0'] - 0.3, WIN['z1'] + 0.15):
                verts.append((sx * (0.05 + 1.0 * u), 0.08 * math.sin(u * 14 * math.pi) + 0.38, zz - z0))
        for i in range(n):
            faces.append((2 * i, 2 * i + 2, 2 * i + 3, 2 * i + 1))
        cu = mesh_obj(f'Curtain{k}', verts, faces, MAT['curtain'], C, smooth=True, loc=(0, 0, z0))
        SETS['curtains'].append(cu)
    # bed, pillows, duvet, nightstand, lamp, TV
    bx, by = 2.2, 3.4
    bm = bmesh.new()
    add_box(bm, bx - 1.0, by - 1.15, z0, bx + 1.0, by + 1.45, z0 + 0.32, mi=0)
    add_box(bm, bx - 1.05, by + 1.45, z0, bx + 1.05, by + 1.55, z0 + 1.05, mi=0)
    add_sbox(bm, (bx, by + 0.15, z0 + 0.45), (0.95, 1.28, 0.13), e=0.25, mi=1)
    obj_from_bm('Bed', bm, [MAT['wood_dark'], MAT['sheet']], C, smooth=True)
    bm = bmesh.new()
    for sx in (-0.48, 0.48):
        add_sbox(bm, (bx + sx, by + 1.15, z0 + 0.66), (0.36, 0.22, 0.09), e=0.4)
    obj_from_bm('Pillows', bm, MAT['pillow'], C, smooth=True)
    duv = bmesh.new()
    add_sbox(duv, (0, 0, 0), (0.98, 0.95, 0.12), e=0.3, u=28, v=12)
    SETS['duvet'] = obj_from_bm('Duvet', duv, MAT['duvet'], C, smooth=True, loc=(bx, by - 0.25, z0 + 0.62))
    bm = bmesh.new()
    add_box(bm, bx + 1.2, by + 0.9, z0, bx + 1.7, by + 1.4, z0 + 0.55)
    add_cyl(bm, 0.08, 0.1, 0.32, seg=12, matrix=Matrix.Translation((bx + 1.45, by + 1.2, z0 + 0.71)))
    obj_from_bm('Nightstand', bm, MAT['wood_dark'], C)
    bm = bmesh.new()
    add_cyl(bm, 0.18, 0.13, 0.22, seg=16, matrix=Matrix.Translation((bx + 1.45, by + 1.2, z0 + 0.98)), caps=False)
    obj_from_bm('LampShade', bm, MAT['lampshade'], C, smooth=True)
    SETS['lamp'] = point_light('BedLamp', (bx + 1.45, by + 1.2, z0 + 0.95), 0.0, (1.0, 0.72, 0.45), C, radius=0.12)
    # TV on the west wall, facing the bed
    tv = Vector((F_['x0'] + 0.06, by + 0.2, z0 + 1.45))
    bm = bmesh.new()
    add_box(bm, -0.04, -0.75, -0.43, 0.04, 0.75, 0.43)
    ob = obj_from_bm('TVBody', bm, MAT['black_plastic'], C, loc=tv)
    SETS['tv'] = card('TVScreen', MAT['scr_tv'], 1.44, 0.81, tv + Vector((0.05, 0, 0)), yaw=90, collection=C)
    SETS['tv_feed'] = card('TVFeed', MAT['anchor_feed'], 1.44 * 0.55, 0.81 * 0.72, tv + Vector((0.051, -1.44 * 0.2, 0.81 * 0.12)), yaw=90, collection=C)
    SETS['tv_light'] = area_light('TVLight', tv + Vector((0.3, 0, 0)), (0, R(-90), 0), 1.4, 0.8, 0.0, (0.75, 0.82, 1.0), C)
    SETS['tvpos'] = tv
    # phone (in his hand; the screen shows the alert)
    bm = bmesh.new()
    add_sbox(bm, (0, 0, 0), (0.037, 0.077, 0.0045), e=0.25, u=16, v=6)
    ph = obj_from_bm('Phone', bm, MAT['phone_body'], 'Chars', smooth=True)
    ph.rotation_mode = 'XYZ'
    scr = card('PhoneScreen', MAT['phone_scr'], 0.068, 0.147, Vector((0, 0, 0)), pitch=0, collection='Chars')
    scr.parent = ph
    scr.location = (0, 0, 0.0047)
    scr.rotation_euler = (0, 0, 0)
    SETS['phone'] = ph
    SETS['bed'] = Vector((bx, by, z0))
    # bathroom: sink, mirror, light
    B = BATH
    bm = bmesh.new()
    add_box(bm, B['x0'] - 0.1, B['y0'], z0, B['x0'], B['y1'], z1)
    obj_from_bm('BathWall', bm, MAT['tile_white'], C)
    sx_, sy_ = (B['x0'] + B['x1']) / 2, B['y1'] - 0.3
    bm = bmesh.new()
    add_box(bm, sx_ - 0.5, sy_ - 0.25, z0, sx_ + 0.5, sy_ + 0.3, z0 + 0.8, mi=0)
    add_sbox(bm, (sx_, sy_, z0 + 0.86), (0.32, 0.22, 0.07), e=0.3, mi=1)
    add_capsule(bm, (sx_, sy_ + 0.22, z0 + 0.9), (sx_, sy_ + 0.08, z0 + 1.0), 0.015, seg=8, mi=2)
    obj_from_bm('Sink', bm, [MAT['wood_dark'], MAT['ceramic'], MAT['steel']], C, smooth=True)
    SETS['mirror'] = card('Mirror', MAT['mirror'], 0.9, 0.95, Vector((sx_, B['y1'] - 0.02, z0 + 1.55)), collection=C)
    area_light('BathLight', (sx_, B['y1'] - 0.6, z1 - 0.05), (0, 0, 0), 0.8, 0.3, 120.0, (1.0, 0.95, 0.88), C)
    SETS['sink'] = Vector((sx_, sy_, z0))
    area_light('FlatFill', (0.0, 2.5, z1 - 0.05), (0, 0, 0), 3.0, 2.0, 60.0, (1.0, 0.93, 0.85), C)


def build_square():
    """A plaza ringed by towers with three giant screens; the crowd is instanced."""
    C = 'Square'
    O = SQ
    bm = bmesh.new()
    add_box(bm, O.x - 90, O.y - 90, -0.1, O.x + 90, O.y + 90, 0.06)
    obj_from_bm('SqFloor', bm, MAT['paving'], C)
    bm = bmesh.new()
    for (x0, y0, x1, y1, h) in ((-90, 50, -20, 90, 110), (-18, 60, 30, 95, 140), (32, 45, 90, 90, 90),
                                (-95, -40, -60, 40, 80), (60, -50, 95, 30, 120)):
        tower_block(bm, O.x + x0, O.y + y0, O.x + x1, O.y + y1, h, np.random.default_rng(int(h)))
    obj_from_bm('SqTowers', bm, MAT['tower_glass'], C)
    city_blocks('Square', O, 4, (O.x - 100, O.y - 100, O.x + 100, O.y + 100), 21)
    card('SqScreen0', MAT['scr_search'], 36.0, 20.25, O + Vector((5.0, 59.8, 30.0)), collection=C)
    card('SqPortrait0', MAT['portrait_glow'], 36.0 * 704 / 2048, 20.25 * 864 / 1152, O + Vector((5.0 - 18.0 + 36.0 * 440 / 2048, 59.75, 30.0 + 20.25 * (0.5 - 630 / 1152))), collection=C)
    card('SqScreen1', MAT['scr_where'], 14.0, 21.0, O + Vector((-59.8, 10.0, 22.0)), yaw=90, collection=C)
    card('SqScreen2', MAT['scr_globe'], 26.0, 14.6, O + Vector((59.8, -5.0, 26.0)), yaw=-90, collection=C)


def build_street():
    """A busy downtown street - the "world keeps going" shot."""
    C = 'Street'
    O = STREET
    bm = bmesh.new()
    add_box(bm, O.x - 200, O.y - 9.0, -0.1, O.x + 200, O.y + 9.0, 0.0)
    obj_from_bm('StRoad', bm, MAT['asphalt'], C)
    bm = bmesh.new()
    for y0, y1 in ((-14.0, -9.0), (9.0, 14.0)):
        add_box(bm, O.x - 200, O.y + y0, 0.0, O.x + 200, O.y + y1, 0.15)
    obj_from_bm('StPave', bm, MAT['paving'], C)
    bm = bmesh.new()
    for x in np.arange(-200, 200, 6.0):
        add_box(bm, O.x + x, O.y - 0.07, 0.0, O.x + x + 3.0, O.y + 0.07, 0.012)
    obj_from_bm('StLines', bm, MAT['road_paint'], C)
    bm = bmesh.new()
    rng = np.random.default_rng(5)
    shop = bmesh.new()
    for x in np.arange(-200, 200, 22.0):
        for sy in (-1, 1):
            y0 = O.y + sy * 14.0
            h = rng.uniform(18, 60)
            tower_block(bm, O.x + x + 1, min(y0, y0 + sy * 25), O.x + x + 21, max(y0, y0 + sy * 25), h, rng)
            add_box(shop, O.x + x + 2, y0 + sy * 0.0 - 0.02 * sy, 0.3, O.x + x + 20, y0 + 0.05 * sy, 3.4)
    obj_from_bm('StBlocks', bm, MAT['tower_stone'], C)
    obj_from_bm('StShops', shop, MAT['shop_window'], C)
    city_blocks('Street', O, 4, (O.x - 220, O.y - 60, O.x + 220, O.y + 60), 31)
    street_furniture(C, O.x - 150, O.x + 150, O.y - 9.0, -1, seed=5)
    street_furniture(C, O.x - 150, O.x + 150, O.y + 9.0, 1, seed=6)
    SETS['traffic'] = []
    paints = ('car_white', 'car_black', 'car_red', 'car_grey', 'car_blue', 'car_silver', 'car_yellow')
    for k in range(14):
        lane = (-1) ** k
        x0 = rng.uniform(-150, 150)
        kind = 'bus' if k % 7 == 3 else 'car'
        c = make_car(f'TCar{k}', C, (O.x + x0, O.y + lane * (2.2 + 3.0 * (k % 2 == 0)), 0), 90 if lane > 0 else -90,
                     'bus_white' if kind == 'bus' else paints[k % len(paints)], L=11.0 if kind == 'bus' else 4.4,
                     W=2.5 if kind == 'bus' else 1.8, kind=kind)
        SETS['traffic'].append((c, x0, lane, rng.uniform(7, 11)))


def room(name, C, O, x0, x1, y0, y1, h, floor, wall, ceil):
    bm = bmesh.new()
    add_box(bm, x0, y0, -0.1, x1, y1, 0.0, mi=0)
    add_box(bm, x0, y0, h, x1, y1, h + 0.1, mi=1)
    for (a, b, c, d) in ((x0 - 0.15, y0, x0, y1), (x1, y0, x1 + 0.15, y1), (x0, y1, x1, y1 + 0.15), (x0, y0 - 0.15, x1, y0)):
        add_box(bm, a, b, 0, c, d, h, mi=2)
    return obj_from_bm(name, bm, [MAT[floor], MAT[ceil], MAT[wall]], C, loc=O)


def build_newsroom():
    C = 'News'
    O = NEWSR
    room('NewsRoom', C, O, -12, 12, -10, 8, 6.0, 'studio_floor', 'news_wall_dark', 'ceiling_dark')
    k = 0
    for row in range(3):
        for col in range(6):
            x = -7.5 + col * 3.0
            z = 1.2 + row * 1.75
            tex = ('scr_globe', 'scr_bc', 'scr_breaking', 'scr_only', 'scr_breaking', 'scr_bc')[(row + col) % 6]
            ob = card(f'NWall{k}', MAT[tex], 2.9, 1.63, O + Vector((x, 7.85, z)), collection=C)
            SETS.setdefault('nwall', []).append((ob, tex))
            pp = card(f'NWallP{k}', MAT['portrait_glow'], 2.9 * 580 / 1600, 1.63 * 680 / 900,
                      O + Vector((x - 1.45 + 2.9 * 360 / 1600, 7.83, z + 1.63 * (0.5 - 450 / 900))), collection=C)
            SETS.setdefault('nwallp', []).append(pp)
            k += 1
    # desk + chairs; journalists are instanced people
    bm = bmesh.new()
    for x in (-6, -2, 2, 6):
        add_box(bm, x - 1.5, -1.2, 0.0, x + 1.5, 0.0, 0.76)
        for dx in (-0.8, 0.8):
            add_box(bm, x + dx - 0.35, -0.6, 0.76, x + dx + 0.35, -0.55, 1.2)
    ob = obj_from_bm('NewsDesks', bm, MAT['desk_white'], C, loc=O)
    for x in (-6, -2, 2, 6):
        for dx in (-0.8, 0.8):
            card(f'NMon{x}{dx}', MAT['scr_bc'], 0.66, 0.38, O + Vector((x + dx, -0.62, 1.0)), collection=C)
    area_light('NewsTop', O + Vector((0, 0, 5.9)), (0, 0, 0), 12.0, 8.0, 1600.0, (0.9, 0.95, 1.0), C)
    V2, F2 = [], []
    for i in range(25):
        a = R(-55 + 110 * i / 24)
        x, y = 2.6 * math.sin(a), 4.9 - 2.6 * (1 - math.cos(a)) * 0.6
        for z in (0.0, 1.0):
            V2.append(O + Vector((x, y, z)))
    F2 = [(2 * i, 2 * i + 2, 2 * i + 3, 2 * i + 1) for i in range(24)]
    mesh_obj('AnchorDeskFront', V2, F2, MAT['desk_front_mat'], C, smooth=True)
    bm = bmesh.new()
    add_box(bm, -2.2, 4.4, 0.98, 2.2, 5.6, 1.04)
    obj_from_bm('AnchorDeskTop', bm, MAT['desk_white'], C, loc=O)
    area_light('AnchorKey', O + Vector((-1.6, 1.0, 3.2)), (R(55), 0, R(-25)), 2.0, 1.5, 420.0, (1.0, 0.96, 0.92), C)
    area_light('AnchorRimN', O + Vector((1.5, 7.0, 3.4)), (R(-55), 0, R(160)), 1.5, 1.0, 260.0, (0.6, 0.75, 1.0), C)


def build_lab():
    C = 'Lab'
    O = LAB
    room('LabRoom', C, O, -6, 6, -5, 5, 3.4, 'lab_floor', 'lab_wall', 'ceiling_white')
    for k, (x, tex) in enumerate(((-3.3, 'scr_labface'), (0.0, 'scr_labdna'), (3.3, 'scr_labface2'))):
        card(f'LabScreen{k}', MAT[tex], 3.0, 1.69, O + Vector((x, 4.88, 1.95)), collection=C)
        if tex.startswith('scr_labface'):
            card(f'LabPortrait{k}', MAT['portrait_glow'], 3.0 * 560 / 1600, 1.69 * 720 / 900,
                 O + Vector((x - 1.5 + 3.0 * 340 / 1600, 4.86, 1.95 + 1.69 * (0.5 - 480 / 900))), collection=C)
    bm = bmesh.new()
    add_box(bm, -5, 2.8, 0.0, 5, 3.6, 0.9)
    add_box(bm, -5, -3.6, 0.0, 5, -2.8, 0.9)
    for x in (-3.8, -1.2, 1.4, 4.0):
        add_cyl(bm, 0.08, 0.06, 0.25, seg=10, matrix=Matrix.Translation((x, -3.2, 1.03)))
        add_cyl(bm, 0.05, 0.05, 0.18, seg=10, matrix=Matrix.Translation((x + 0.3, -3.2, 0.99)))
    obj_from_bm('LabBenches', bm, MAT['lab_bench'], C, loc=O)
    for x in (-3.0, 0.0, 3.0):
        area_light(f'LabTop{x}', O + Vector((x, 0, 3.35)), (0, 0, 0), 2.4, 0.5, 260.0, (0.95, 0.98, 1.0), C)


def build_office():
    C = 'Office'
    O = OFFICE
    room('OfficeRoom', C, O, -14, 14, -8, 8, 3.2, 'carpet_grey', 'wall_warm', 'ceiling_white')
    bm = bmesh.new()
    mons = []
    for row in range(3):
        for col in range(5):
            x, y = -9 + col * 4.5, -4 + row * 3.2
            add_box(bm, x - 1.6, y - 0.4, 0.72, x + 1.6, y + 0.4, 0.76)
            for lx in (-1.5, 1.5):
                add_box(bm, x + lx - 0.03, y - 0.35, 0, x + lx + 0.03, y + 0.35, 0.72)
            mons.append((x, y))
    obj_from_bm('Desks', bm, MAT['desk_white'], C, loc=O)
    for k, (x, y) in enumerate(mons):
        for j, dx in enumerate((-0.75, 0.75)):
            card(f'OMon{k}_{j}', MAT[f'scr_office{(k + j) % 3}'], 0.6, 0.38, O + Vector((x + dx, y + 0.22, 1.05)), collection=C)
    SETS['office_desks'] = mons
    card('OfficeSign', MAT['office_sign'], 4.0, 0.75, O + Vector((0, 7.85, 2.4)), collection=C)
    bm = bmesh.new()
    for x in np.arange(-13, 14, 2.0):
        add_box(bm, x, 7.9, 0.4, x + 1.6, 8.0, 2.9)
    obj_from_bm('OfficeWindows', bm, MAT['skylight'], C, loc=O)
    for x in (-8, 0, 8):
        for y in (-4, 3):
            area_light(f'OffTop{x}{y}', O + Vector((x, y, 3.15)), (0, 0, 0), 2.0, 1.0, 220.0, (1.0, 0.97, 0.92), C)


