def build_parliament():
    C = 'Parl'
    O = PARL
    bm = bmesh.new()
    add_box(bm, -30, -30, -0.1, 30, 30, 0.0)
    obj_from_bm('ParlFloor', bm, MAT['carpet_green'], C, loc=O)
    seats = []
    bm = bmesh.new()
    for tier in range(6):
        r = 9.0 + tier * 1.6
        z = tier * 0.55
        for a in np.linspace(R(200), R(340), 26 + tier * 4):
            x, y = r * math.cos(a), r * math.sin(a) + 6
            add_box(bm, x - 0.55, y - 0.5, 0.0, x + 0.55, y + 0.5, z + 0.45, matrix=Matrix())
            seats.append((x, y, z, a))
    obj_from_bm('ParlTiers', bm, MAT['wood_dark'], C, loc=O)
    SETS['parl_seats'] = seats
    bm = bmesh.new()
    add_box(bm, -1.2, 9.5, 0.0, 1.2, 10.3, 1.15)
    add_box(bm, -4.0, 10.8, 0.0, 4.0, 12.0, 0.6)
    obj_from_bm('Podium', bm, MAT['wood_dark'], C, loc=O)
    card('ParlCrest', MAT['parl_crest'], 4.0, 4.0, O + Vector((0, 14.9, 4.2)), collection=C)
    bm = bmesh.new()
    add_box(bm, -16, 15, 0, 16, 15.2, 9)
    obj_from_bm('ParlWall', bm, MAT['wood_panel'], C, loc=O)
    area_light('ParlTop', O + Vector((0, 2, 12)), (0, 0, 0), 20.0, 16.0, 3000.0, (1.0, 0.95, 0.85), C)


def build_train():
    C = 'Train'
    O = TRAIN
    bm = bmesh.new()
    add_box(bm, -80, -3.0, -1.2, 80, 4.0, -1.1, mi=0)
    add_box(bm, -80, 4.0, -1.2, 80, 9.0, 0.0, mi=1)
    add_box(bm, -80, 4.0, 0.0, 80, 4.4, 0.01, mi=2)
    add_box(bm, -80, -3.2, -1.2, 80, -3.0, 5.0, mi=3)
    add_box(bm, -80, 9.0, 0.0, 80, 9.2, 5.0, mi=3)
    add_box(bm, -80, -3.2, 5.0, 80, 9.2, 5.2, mi=4)
    obj_from_bm('Platform', bm, [MAT['ballast'], MAT['platform'], MAT['yellow_line'], MAT['metro_wall'], MAT['ceiling_dark']], C, loc=O)
    card('TrainSign', MAT['train_sign'], 2.4, 0.45, O + Vector((0, 6.0, 3.2)), collection=C)
    for x in np.arange(-70, 70, 6.0):
        area_light(f'TrL{x}', O + Vector((x, 5.5, 4.95)), (0, 0, 0), 0.4, 1.6, 120.0, (1.0, 0.95, 0.85), C)
    root = empty('Train', O + Vector((0, 0.5, -1.1)), C)
    bm = bmesh.new()
    for car in range(4):
        x0 = -car * 21.0
        add_sbox(bm, (x0, 0, 2.05), (10.2, 1.45, 1.85), e=0.15, mi=0)
        for k in range(6):
            add_box(bm, x0 - 8.5 + k * 3.2, 1.42, 1.9, x0 - 6.9 + k * 3.2, 1.5, 3.0, mi=1)
        add_box(bm, x0 - 10.2, 1.43, 1.2, x0 + 10.2, 1.5, 1.4, mi=2)
    add_box(bm, 9.6, -1.2, 1.6, 10.25, 1.2, 3.2, mi=1)
    ob = obj_from_bm('TrainBody', bm, [MAT['train_white'], MAT['train_window'], MAT['train_stripe']], C, smooth=False)
    ob.parent = root
    SETS['train'] = root


