def build_sitroom():
    """A government situation room: a long table, an URGENT wall, red alert light."""
    C = 'Sit'
    O = SIT
    room('SitRoom', C, O, -8, 8, -6, 6, 3.4, 'studio_floor', 'news_wall_dark', 'ceiling_dark')
    card('SitWall', MAT['scr_urgent'], 8.0, 4.5, O + Vector((0, 5.88, 1.95)), collection=C)
    for k, x in enumerate((-6.2, 6.2)):
        card(f'SitSide{k}', MAT['scr_globe'], 2.8, 1.58, O + Vector((x, 5.88, 2.2)), collection=C)
    bm = bmesh.new()
    add_sbox(bm, (0, 0, 0.75), (1.1, 3.6, 0.04), e=0.2)
    add_box(bm, -0.4, -3.0, 0.0, 0.4, 3.0, 0.73)
    obj_from_bm('SitTable', bm, MAT['wood_dark'], C, loc=O)
    bm = bmesh.new()
    for k in range(6):
        for sx in (-1, 1):
            add_box(bm, sx * 0.62 - 0.25, -2.5 + k * 1.0 - 0.22, 0.79, sx * 0.62 + 0.25, -2.5 + k * 1.0 + 0.22, 0.8)
    obj_from_bm('SitPapers', bm, MAT['sheet'], C, loc=O)
    for k in range(6):
        for sx in (-1, 1):
            card(f'SitTab{k}{sx}', MAT['scr_urgent'], 0.32, 0.2, O + Vector((sx * 0.55, -2.5 + k * 1.0, 0.88)), yaw=90 * sx, pitch=60, collection=C)
    SETS['sit_light'] = point_light('SitRed', O + Vector((0, 0, 3.2)), 120.0, (1.0, 0.1, 0.08), C, radius=0.4)
    area_light('SitTop', O + Vector((0, 0, 3.35)), (0, 0, 0), 2.0, 7.0, 260.0, (0.85, 0.9, 1.0), C)
    SETS['sit_seats'] = [(O.x + sx * 1.55, O.y - 2.5 + k * 1.0, -90 * sx) for k in range(6) for sx in (-1, 1)]


def build_vehicle():
    """A black government vehicle with blue light strips (its rear door slides open)."""
    C = 'City'
    root = empty('GovCar', (-80, -6.6, 0), C)
    root.rotation_mode = 'XYZ'
    bm = bmesh.new()
    add_sbox(bm, (0, 0, 0.95), (1.0, 2.55, 0.55), e=0.18, u=28, v=12, mi=0)
    add_sbox(bm, (0, -0.25, 1.62), (0.9, 1.7, 0.36), e=0.25, u=24, v=10, mi=1)
    for sx in (-1, 1):
        add_box(bm, sx * 1.005 - 0.01, -2.4, 0.78, sx * 1.005 + 0.01, 2.4, 0.83, mi=2)
    add_box(bm, -0.85, 2.52, 0.75, 0.85, 2.58, 0.82, mi=2)
    add_box(bm, -0.85, -2.58, 0.8, 0.85, -2.52, 0.88, mi=3)
    body = obj_from_bm('GovCarBody', bm, [MAT['car_black'], MAT['window'], MAT['led_blue'], MAT['taillight']], C, smooth=True)
    body.parent = root
    wheels = []
    for sx in (-1, 1):
        for sy in (-1.65, 1.65):
            bm = bmesh.new()
            add_cyl(bm, 0.42, 0.42, 0.3, seg=20, matrix=Matrix.Rotation(R(90), 4, 'Y'), mi=0)
            add_cyl(bm, 0.27, 0.27, 0.31, seg=16, matrix=Matrix.Rotation(R(90), 4, 'Y'), mi=1)
            w_ = obj_from_bm(f'GovWheel{len(wheels)}', bm, [MAT['rubber'], MAT['alloy']], C, smooth=True)
            w_.parent = root
            w_.location = (sx * 0.92, sy, 0.42)
            w_.rotation_mode = 'XYZ'
            wheels.append(w_)
    bm = bmesh.new()
    add_box(bm, -0.03, -0.55, 0.45, 0.03, 0.55, 1.75)
    door = obj_from_bm('GovCarDoor', bm, [MAT['car_black']], C)
    door.parent = root
    door.location = (-1.03, -0.3, 0)
    SETS['govcar'] = dict(root=root, wheels=wheels, door=door)


def build_facility():
    """An enormous research facility: a dark hall with light lines, walls of displays, a holographic globe, and a glass
    research room with a timeline wall."""
    C = 'Faci'
    O = FACI
    bm = bmesh.new()
    add_box(bm, -28, -12, -0.1, 28, 62, 0.0)
    obj_from_bm('FaciFloor', bm, MAT['faci_floor'], C, loc=O)
    bm = bmesh.new()
    add_box(bm, -28.2, -12, 0, -28, 62, 20)
    add_box(bm, 28, -12, 0, 28.2, 62, 20)
    add_box(bm, -28, 62, 0, 28, 62.2, 20)
    add_box(bm, -28, -12.2, 0, 28, -12, 20)
    add_box(bm, -28.2, -12.2, 20, 28.2, 62.2, 20.3)
    obj_from_bm('FaciShell', bm, MAT['faci_wall'], C, loc=O)
    bm = bmesh.new()
    for x in np.arange(-26, 27, 4.0):
        add_box(bm, x - 0.04, -11, 0.0, x + 0.04, 60, 0.012)
    for y in np.arange(-10, 61, 6.0):
        add_box(bm, -27, y - 0.04, 0.0, 27, y + 0.04, 0.012)
    obj_from_bm('FaciFloorLines', bm, MAT['led_blue_dim'], C, loc=O)
    bm = bmesh.new()
    for x in np.arange(-24, 25, 8.0):
        for y in (-8, 10, 28, 46):
            add_box(bm, x - 0.5, y - 0.5, 0, x + 0.5, y + 0.5, 20)
    obj_from_bm('FaciColumns', bm, MAT['faci_column'], C, loc=O)
    bm = bmesh.new()
    for x in np.arange(-24, 25, 8.0):
        for y in (-8, 10, 28, 46):
            add_box(bm, x - 0.52, y - 0.52, 0.5, x + 0.52, y + 0.52, 0.56)
            add_box(bm, x - 0.52, y - 0.52, 19.2, x + 0.52, y + 0.52, 19.26)
    for y in np.arange(-10, 61, 8.0):
        add_box(bm, -27.9, y, 8.0, -27.8, y + 6, 8.08)
        add_box(bm, 27.8, y, 8.0, 27.9, y + 6, 8.08)
    obj_from_bm('FaciStrips', bm, MAT['led_violet'], C, loc=O)
    # the far wall of displays
    for k, (x, tex) in enumerate(((-18, 'scr_disdata'), (-6, 'scr_globe'), (6, 'scr_timeline'), (18, 'scr_urgent'))):
        card(f'FaciWall{k}', MAT[tex], 11.4, 6.4, O + Vector((x, 61.85, 9.0)), collection=C)
    for k, (x, tex) in enumerate(((-14, 'scr_disdata'), (14, 'scr_globe'))):
        card(f'FaciSide{k}', MAT[tex], 9.0, 5.06, O + Vector((-27.85 if x < 0 else 27.85, 36.0, 6.5)), yaw=90 if x < 0 else -90, collection=C)
    # consoles in rows
    bm = bmesh.new()
    mons = []
    for row in range(3):
        for col in range(6):
            x, y = -20 + col * 7.0, 34 + row * 6.0
            if x > 8 and row < 2:
                continue
            add_box(bm, x - 2.0, y - 0.4, 0.0, x + 2.0, y + 0.4, 0.9)
            mons.append((x, y))
    obj_from_bm('FaciConsoles', bm, MAT['console_dark'], C, loc=O)
    for k, (x, y) in enumerate(mons):
        for j, dx in enumerate((-1.0, 1.0)):
            card(f'FaciMon{k}_{j}', MAT[('scr_disdata', 'scr_globe', 'scr_timeline')[(k + j) % 3]], 1.5, 0.84, O + Vector((x + dx, y + 0.3, 1.45)), collection=C)
    SETS['faci_consoles'] = mons
    # the holographic globe: a wireframe sphere, rings and a beam from the floor
    gc = O + Vector((0, 22, 6.5))
    holo = empty('Holo', gc, C)
    holo.rotation_mode = 'XYZ'
    bm = bmesh.new()
    bmesh.ops.create_icosphere(bm, subdivisions=3, radius=4.2)
    me = bpy.data.meshes.new('HoloSphere')
    bm.to_mesh(me)
    bm.free()
    sph = bpy.data.objects.new('HoloSphere', me)
    coll(C).objects.link(sph)
    sph.parent = holo
    md = sph.modifiers.new('wire', 'WIREFRAME')
    md.thickness = 0.03
    me.materials.append(MAT['holo'])
    bm = bmesh.new()
    for k, (r, tilt) in enumerate(((5.4, 12), (6.2, -20), (4.8, 70))):
        ring = add_cyl(bm, r, r, 0.04, seg=64, matrix=Matrix.Rotation(R(tilt), 4, 'X'), caps=False)
    ob = obj_from_bm('HoloRings', bm, MAT['holo'], C)
    ob.parent = holo
    bm = bmesh.new()
    add_cyl(bm, 2.2, 3.4, 0.4, seg=48, matrix=Matrix.Translation(Vector((0, 22, 0.2))), mi=0)
    add_cyl(bm, 2.0, 2.0, 0.02, seg=48, matrix=Matrix.Translation(Vector((0, 22, 0.42))), mi=1)
    obj_from_bm('HoloBase', bm, [MAT['console_dark'], MAT['led_blue']], C, loc=O)
    bm = bmesh.new()
    add_cyl(bm, 1.9, 4.5, 6.0, seg=32, matrix=Matrix.Translation(Vector((0, 22, 3.4))), caps=False)
    obj_from_bm('HoloBeam', bm, MAT['holo_beam'], C, loc=O)
    SETS['holo'] = holo
    point_light('HoloLight', gc, 2500.0, (0.4, 0.65, 1.0), C, radius=2.0)
    for x in (-16, 0, 16):
        for y in (0, 24, 48):
            area_light(f'FaciTop{x}_{y}', O + Vector((x, y, 19.8)), (0, 0, 0), 6.0, 6.0, 1800.0, (0.75, 0.82, 1.0), C)
    # the glass research room
    R_ = RROOM
    bm = bmesh.new()
    add_box(bm, R_.x - 6, R_.y - 8, 0.0, R_.x + 6, R_.y + 8, 0.02, mi=0)
    add_box(bm, R_.x - 6, R_.y - 8, 4.6, R_.x + 6, R_.y + 8, 4.7, mi=1)
    add_box(bm, R_.x + 6, R_.y - 8, 0, R_.x + 6.15, R_.y + 8, 4.6, mi=1)
    add_box(bm, R_.x - 6, R_.y + 8, 0, R_.x + 6, R_.y + 8.15, 4.6, mi=1)
    add_box(bm, R_.x - 6, R_.y - 8.15, 0, R_.x + 6, R_.y - 8, 4.6, mi=1)
    obj_from_bm('RRShell', bm, [MAT['faci_floor'], MAT['faci_wall']], C)
    card('RRGlass', MAT['glass_room'], 16.0, 4.6, Vector((R_.x - 6.0, R_.y, 2.3)), yaw=-90, collection=C)
    bm = bmesh.new()
    for y in np.arange(-8, 8.1, 2.0):
        add_box(bm, R_.x - 6.04, R_.y + y - 0.03, 0, R_.x - 5.96, R_.y + y + 0.03, 4.6)
    obj_from_bm('RRMullions', bm, MAT['darksteel'], C)
    SETS['rr_screen'] = card('RRScreen', MAT['scr_rr'], 14.4, 4.05, Vector((R_.x + 5.98, R_.y, 2.5)), yaw=-90, collection=C)
    SETS['rr_portrait'] = card('RRPortrait', MAT['portrait_rr'], 14.4 * 310 / 3200, 4.05 * 360 / 900,
                               Vector((R_.x + 5.96, R_.y + 7.2 - 14.4 * 485 / 3200, 2.5 + 4.05 * (0.5 - 510 / 900))), yaw=-90, collection=C)
    bm = bmesh.new()
    add_sbox(bm, (R_.x, R_.y, 0.76), (1.4, 3.2, 0.04), e=0.2)
    add_box(bm, R_.x - 0.4, R_.y - 2.6, 0.0, R_.x + 0.4, R_.y + 2.6, 0.74)
    obj_from_bm('RRTable', bm, MAT['desk_white'], C)
    SETS['rr_lights'] = [area_light(f'RRTop{k}', Vector((R_.x, R_.y + y, 4.55)), (0, 0, 0), 2.0, 3.0, 380.0, (0.85, 0.9, 1.0), C)
                         for k, y in enumerate((-4, 0, 4))]
    SETS['rr_scr_light'] = area_light('RRScrLight', Vector((R_.x + 5.2, R_.y, 2.5)), (0, R(90), 0), 14.0, 4.0, 300.0, (0.5, 0.8, 1.0), C)


def build_sets():
    build_city()
    build_flat()
    build_vehicle()
    build_square()
    build_newsroom()
    build_lab()
    build_sitroom()
    build_facility()
    build_booth()

# ============================================================================
# CAST. The main character is the same build_human() figure as in Part 1 (same spec: face, hair, T-shirt, sweatpants;
# only trainers added so he can go outside). The scientists, the facility director, the news presenter, officials and
# crowds are women built with the same builder; crowds are baked and instanced.
# ============================================================================
YOU = 'you'
YOU_SPEC = dict(sex='m', skin='skinH', hair='hair_dark', hstyle='crew', top='tee', topmat='tee_grey', bottom='trousers',
                bottommat='sweats_dark', shoes='shoe_white', iris='brown', stubble=True, height=1.03, subdiv=2)
HEROES = {   # name: (collection, spec)
    'sci1': ('Faci', dict(sex='f', skin='skinA', hair='hair_auburn', hstyle='bob', top='labcoat', topmat='labcoat_white', bottom='trousers',
                          bottommat='trousers_black', shoes='shoe_white', iris='green', height=0.96)),
    'dir': ('Faci', dict(sex='f', skin='skinD', hair='hair_black', hstyle='bun', top='blazer', topmat='blazer_navy', bottom='skirt',
                         bottommat='skirt_black', shoes='shoe_black', iris='dark', height=0.97, subdiv=1)),
    'sci2': ('Lab', dict(sex='f', skin='skinC', hair='hair_black', hstyle='long', top='labcoat', topmat='labcoat_white', bottom='trousers',
                         bottommat='trousers_navy', shoes='shoe_black', iris='dark', height=0.95)),
    'anchor': ('News', dict(sex='f', skin='skinB', hair='hair_brown', hstyle='long', top='blazer', topmat='blazer_red', bottom='skirt',
                            bottommat='skirt_black', shoes='shoe_black', iris='brown', height=0.96)),
}
NEUTRAL_F = dict(brow=0.1, lid=0.35, open=0.0, smile=0.0, frown=0.0, btilt=0.0)
SLEEPY = dict(lid=0.62, brow=0.0, open=0.0, smile=0.0)
PUZZLED = dict(brow=0.55, btilt=0.35, lid=0.3, open=0.05, frown=0.12)
SHOCK_F = dict(brow=0.95, btilt=0.2, lid=0.12, open=0.35, frown=0.0)
STUNNED = dict(brow=0.7, btilt=0.5, lid=0.22, open=0.18, frown=0.1)
UNEASY = dict(brow=0.45, btilt=0.75, lid=0.3, open=0.06, frown=0.3)
HALF_SMILE = dict(brow=0.35, btilt=0.25, lid=0.35, open=0.0, smile=0.4, frown=0.0)
BUSY = dict(brow=0.15, lid=0.38, open=0.0, smile=0.1)
TALK = lambda t, k=17.0: dict(open=0.06 + 0.14 * max(0.0, math.sin(t * k) * math.sin(t * 5.3 + 1.0)))
FX = {}


def build_cast():
    build_human(YOU, YOU_SPEC, 'Chars')
    for nm, (C, sp) in HEROES.items():
        build_human(nm, sp, C, hair_particles_on=nm in ('sci1', 'sci2', 'anchor'))
    for nm in [YOU] + list(HEROES):
        park(nm)
    build_crowd_variants()


STAND_VARS, SIT_VARS, REPORTER_VARS, COAT_VARS = [], [], [], []


def build_crowd_variants():
    template_collection('PeopleT')
    rng = np.random.default_rng(17)
    skins = list(SKINS)
    hairs = ['hair_black', 'hair_brown', 'hair_dark', 'hair_blonde', 'hair_auburn', 'hair_grey']
    styles = ['long', 'bob', 'ponytail', 'bun', 'long']
    outfits = [('blazer', 'blazer_navy', 'trousers', 'trousers_black'), ('jacket', 'jacket_tan', 'trousers', 'jeans_blue'),
               ('sweater', 'sweater_rust', 'skirt', 'skirt_grey'), ('blouse', 'blouse_blue', 'trousers', 'trousers_beige'),
               ('blazer', 'blazer_black', 'skirt', 'skirt_black'), ('jacket', 'jacket_olive', 'trousers', 'trousers_navy'),
               ('sweater', 'sweater_green', 'trousers', 'jeans_blue'), ('blouse', 'blouse_pink', 'skirt', 'skirt_black'),
               ('blazer', 'blazer_grey', 'trousers', 'trousers_black'), ('blazer', 'blazer_red', 'trousers', 'trousers_black')]
    k = 0
    for kind, n in (('stand', 12), ('sit', 6), ('coat', 6)):
        for i in range(n):
            o = outfits[(i * 3 + len(kind)) % len(outfits)]
            if kind == 'coat':
                o = ('labcoat', 'labcoat_white', 'trousers', ('trousers_black', 'trousers_navy', 'jeans_blue')[i % 3])
            spec = dict(sex='f', skin=skins[int(rng.integers(len(skins)))], hair=hairs[int(rng.integers(len(hairs)))],
                        hstyle=styles[int(rng.integers(len(styles)))], top=o[0], topmat=o[1], bottom=o[2], bottommat=o[3],
                        shoes=('shoe_black', 'shoe_brown')[i % 2], iris='brown', height=rng.uniform(0.92, 1.0), subdiv=0,
                        girth=rng.uniform(0.95, 1.1))
            nm = f'pv{k:02d}'
            build_human(nm, spec, 'Booth', hair_particles_on=False)
            bpy.context.view_layer.update()
            if kind in ('stand', 'coat'):
                P = dict(look=(0, 0), lid=0.35, smile=rng.uniform(0, 0.15), shR=(0, 6, 0), shL=(0, 6, 0), elR=12, elL=12,
                         nod=rng.normal(-8, 4) if kind == 'stand' else rng.normal(4, 4))
                (STAND_VARS if kind == 'stand' else COAT_VARS).append(bake_human(nm, 'PeopleT', P))
            else:
                P = dict(dz=-0.47, hipR=(86, 6), hipL=(86, 6), knR=88, knL=88, lid=0.38, shR=(40, 12, 0), shL=(40, 12, 0), elR=60, elL=60)
                SIT_VARS.append(bake_human(nm, 'PeopleT', P))
            k += 1
    for i, ob in enumerate(STAND_VARS + SIT_VARS + REPORTER_VARS + COAT_VARS):
        ob.name = f'PV_{i:02d}'


def people(name, pts, yaws, kinds, collection, seed=0):
    """Instance baked people: kinds 'stand' / 'sit' / 'rep' per point (an index into the template collection)."""
    rng = np.random.default_rng(seed)
    allv = STAND_VARS + SIT_VARS + REPORTER_VARS + COAT_VARS
    base = {'stand': 0, 'sit': len(STAND_VARS), 'rep': len(STAND_VARS) + len(SIT_VARS), 'coat': len(STAND_VARS) + len(SIT_VARS) + len(REPORTER_VARS)}
    cnt = {'stand': len(STAND_VARS), 'sit': len(SIT_VARS), 'rep': max(1, len(REPORTER_VARS)), 'coat': len(COAT_VARS)}
    var = [base[k] + int(rng.integers(cnt[k])) for k in kinds]
    # the instancer picks templates in the template collection's order, which is name order
    order = sorted(range(len(allv)), key=lambda i: allv[i].name)
    remap = {old: new for new, old in enumerate(order)}
    var = [remap[v] for v in var]
    return instancer(name, pts, var, yaws, rng.uniform(0.97, 1.03, len(pts)), 'PeopleT', collection)


def build_crowds():
    rng = np.random.default_rng(23)
    P, Y = [], []
    for y in np.arange(-40, 42, 0.95):
        for x in np.arange(-48, 48, 0.9):
            if rng.random() < 0.18:
                continue
            p = (SQ.x + x + rng.uniform(-0.3, 0.3), SQ.y + y + rng.uniform(-0.3, 0.3), 0.06)
            P.append(p)
            Y.append(math.atan2(-(SQ.x + 5 - p[0]), (SQ.y + 59.8 - p[1])) + rng.normal(0, 0.25))
    SETS['sq_crowd'] = people('SqCrowd', P, Y, ['stand'] * len(P), 'Square', 1)
    SETS['sq_crowd_yaw'] = np.array(Y)
    P = [(NEWSR.x + x + dx, NEWSR.y - 1.75, 0.0) for x in (-6, -2, 2, 6) for dx in (-0.8, 0.8)]
    people('NewsStaff', P, [0.0] * len(P), ['sit'] * len(P), 'News', 3)
    P = [(x, y, 0.0) for (x, y, _) in SETS['sit_seats']]
    people('Officials', P, [R(-a) for (_, _, a) in SETS['sit_seats']], ['sit'] * len(P), 'Sit', 4)
    P, Y = [], []
    for (x, y) in SETS['faci_consoles']:
        for dx in (-1.0, 1.0):
            P.append((FACI.x + x + dx, FACI.y + y - 0.75, 0.0))
            Y.append(rng.normal(0, 0.2))
    cols = [(x, y) for x in np.arange(-24, 25, 8.0) for y in (-8, 10, 28, 46)]
    k = 0
    while k < 30:
        x, y = rng.uniform(-25, 10), rng.uniform(-4, 31)
        if min((x - cx) ** 2 + (y - cy) ** 2 for cx, cy in cols) < 1.4 or x * x + (y - 22) ** 2 < 30 or (1.5 < x < 7.5 and y < 12):
            continue
        P.append((FACI.x + x, FACI.y + y, 0.0))
        Y.append(rng.uniform(-3.1, 3.1))
        k += 1
    people('FaciStaff', P, Y, ['coat'] * len(P), 'Faci', 5)
    P = [(LAB.x + x, LAB.y + y, 0.0) for (x, y) in ((-4.0, 2.6), (3.6, 2.4), (-2.6, -2.2), (2.4, -2.0))]
    people('LabStaff', P, [0.1, -0.2, 3.0, 3.1], ['coat'] * 4, 'Lab', 6)


def root_matrix(xl, yl, zl):
    return Matrix((xl, yl, zl)).transposed()


def face_pt(name):
    return jmat(CH[name]['J']['neck']) @ (HC2 + Vector((0, 0.09, EYE_Z)))


def eyes_pt(name):
    return jmat(CH[name]['J']['neck']) @ (HC2 + Vector((0, 0.085, EYE_Z)))


def place_phone(p, n, up):
    ph = SETS['phone']
    ph.location = p
    n = n.normalized()
    x = up.cross(n)
    if x.length < 1e-5:
        x = Vector((1, 0, 0))
    x.normalize()
    y = n.cross(x).normalized()
    ph.rotation_euler = root_matrix(x, y, n).to_euler()


def hide_phone():
    SETS['phone'].location = (0, 0, -500)




# --- the main character ----------------------------------------------------------------------------------------------
WALK_Y = -2.0
LOOKUP_X = -15.0 + 1.15 * 3.0


def chor_street(t, shot):
    hide_phone()
    if shot in ('walk', 'billboard'):
        P, mv = walk_along([(-15.0, WALK_Y), (-6.0, WALK_Y)], t, -0.4, 1.15, amp=0.85)
        P['loc'] = (P['loc'][0], P['loc'][1], 0.15)
        P = merge(P, blend_face(PUZZLED, UNEASY, ramp(t, 0.6, 1.4)))
        pose(YOU, P)
        P.update(look_at(YOU, Vector((P['loc'][0] + 6, WALK_Y - 6, 1.6)), head=0.4))
        pose(YOU, P)
    elif shot == 'lookup':
        x = LOOKUP_X
        u = smooth(ramp(t, 2.6, 3.3))
        P = merge(dict(loc=(x, WALK_Y, 0.15), yaw=-90 - 75 * u), idle(t), blend_face(UNEASY, STUNNED, ramp(t, 2.9, 3.6)))
        pose(YOU, P)
        P.update(look_at(YOU, Vector((8.0, GIANT['y'], 13.0)), head=0.8))
        pose(YOU, P)
    elif shot == 'car':
        p = Vector((1.8, -3.5, 0.15))
        P = merge(dict(loc=tuple(p), yaw=140), idle(t), UNEASY)
        pose(YOU, P)
        P.update(look_at(YOU, Vector((car_x(t), -6.6, 1.2)), head=0.6))
        pose(YOU, P)


def chor_enter(t, shot):
    hide_phone()
    O = FACI
    P, mv = walk_along([(O.x + 4.0, O.y - 5.0), (O.x + 4.2, O.y + 8.0)], t, 12.2, 0.95, amp=0.7)
    P = merge(P, blend_face(UNEASY, AWE_F, ramp(t, 13.0, 14.0)))
    pose(YOU, P)
    P.update(look_at(YOU, O + Vector((-6.0 + 8.0 * ramp(t, 12.8, 15.0), 22.0, 7.0)), head=0.7))
    pose(YOU, P)
    P = merge(dict(loc=tuple(O + Vector((4.9, 1.6, 0))), yaw=172), idle(t, 1.0), dict(smile=0.25, brow=0.2, lid=0.35))
    pose('dir', P)
    P.update(look_at('dir', Vector(CH[YOU]['J']['root'].location) + Vector((0, 0, 1.6)), head=0.6))
    pose('dir', P)


def chor_room(t, shot):
    """The research room: the welcome, the timeline, the turn."""
    hide_phone()
    R_ = RROOM
    you_p = R_ + Vector((-2.08, -2.62, 0))
    sci_p = R_ + Vector((-1.52, -1.98, 0))
    if shot == 'welcome':
        u = smooth(ramp(t, 15.6, 16.6))
        P = merge(dict(loc=tuple(you_p), yaw=-55), idle(t), blend_face(UNEASY, PUZZLED, ramp(t, 16.5, 17.5)))
        pose(YOU, P)
        hand = (Vector(you_p) + sci_p) / 2 + Vector((0, 0, 1.05))
        if u > 0.2:
            P['shR'], P['elR'] = reach(YOU, 'R', hand + Vector((-0.02, -0.02, 0)))
        P.update(look_at(YOU, face_pt('sci1'), head=0.6))
        pose(YOU, P)
        S = merge(dict(loc=tuple(sci_p), yaw=125), idle(t, 2.0), dict(smile=0.35, brow=0.25, lid=0.35), TALK(t, 9.0))
        pose('sci1', S)
        S['shR'], S['elR'] = reach('sci1', 'R', hand + Vector((0.02, 0.02, 0))) if u > 0.1 else ((0, 8, 0), 12)
        S.update(look_at('sci1', face_pt(YOU), head=0.6))
        pose('sci1', S)
        D = merge(dict(loc=tuple(R_ + Vector((0.8, 1.2, 0))), yaw=160), idle(t, 3.0), BUSY)
        pose('dir', D)
        D.update(look_at('dir', face_pt(YOU), head=0.6))
        pose('dir', D)
    else:
        scr = R_ + Vector((5.95, 0.0, 2.6))
        if shot in ('timeline', 'notice'):
            sp = R_ + Vector((4.0, 0.6 - 1.2 * smooth(ramp(t, 19.4, 20.6)), 0))
            S = merge(dict(loc=tuple(sp), yaw=-90), idle(t, 2.0), blend_face(BUSY, PUZZLED, ramp(t, 21.4, 22.2)))
            pose('sci1', S)
            sw = math.sin((t - 19.2) * 2.2) * (1 - ramp(t, 20.8, 21.2))
            S['shR'], S['elR'] = reach('sci1', 'R', Vector((scr.x - 0.35, sp.y - 0.4 + 0.5 * sw, 2.0 + 0.2 * sw)))
            S.update(look_at('sci1', Vector((scr.x, sp.y - 1.0, 2.4)), head=0.7))
            pose('sci1', S)
            yp = R_ + Vector((1.6, -2.4, 0))
            P = merge(dict(loc=tuple(yp), yaw=-70), idle(t), PUZZLED)
            pose(YOU, P)
            P.update(look_at(YOU, scr, head=0.6))
            pose(YOU, P)
        else:   # turn, symbol, stare
            sp = R_ + Vector((4.0, -0.6, 0))
            yp = R_ + Vector((1.6, -2.4, 0))
            u = smooth(ramp(t, 23.6, 24.6)) if shot == 'turn' else 1.0
            S = merge(dict(loc=tuple(sp), yaw=-90 - 143 * u), idle(t, 2.0), blend_face(PUZZLED, dict(brow=0.4, btilt=0.3, lid=0.3, open=0.05), u))
            pose('sci1', S)
            S.update(look_at('sci1', face_pt(YOU) if u > 0.5 else scr, head=0.7))
            pose('sci1', S)
            yaw_you = -70 if shot != 'stare' else -70 + 0.0
            f = blend_face(PUZZLED, STUNNED, ramp(t, 25.2, 26.4))
            P = merge(dict(loc=tuple(yp), yaw=yaw_you), idle(t), f, dict(btilt=0.6))
            pose(YOU, P)
            P.update(look_at(YOU, face_pt('sci1') if shot == 'turn' else scr + Vector((0, 0, 0.3)), head=0.6))
            pose(YOU, P)


def chor_anchor(t, shot):
    O = NEWSR
    P = merge(dict(loc=tuple(O + Vector((0, 5.8, 0))), yaw=180, dz=-0.47, hipR=(86, 6), hipL=(86, 6), knR=88, knL=88),
              idle(t, 3.0), NEUTRAL_F, TALK(t), dict(brow=0.3 + 0.15 * math.sin(t * 2.0)))
    pose('anchor', P)
    P['shR'], P['elR'] = reach('anchor', 'R', O + Vector((-0.28, 5.3, 1.08)))
    P['shL'], P['elL'] = reach('anchor', 'L', O + Vector((0.28 + 0.04 * math.sin(t * 3.0), 5.3, 1.08)))
    P.update(look_at('anchor', O + Vector((0.0, -4.0, 1.4)), head=0.6))
    pose('anchor', P)


def chor_lab2(t, shot):
    O = LAB
    P = merge(dict(loc=tuple(O + Vector((-0.6, 2.25, 0))), yaw=-35), idle(t, 2.0), BUSY, TALK(t, 13.0))
    pose('sci2', P)
    P['shR'], P['elR'] = reach('sci2', 'R', O + Vector((-0.25 + 0.06 * math.sin(t * 2.3), 2.55, 1.15)))
    P.update(look_at('sci2', O + Vector((1.0, 1.0, 1.6)), head=0.5))
    pose('sci2', P)


AWE_F = dict(brow=0.6, btilt=0.1, lid=0.25, open=0.15, smile=0.0)
CHOR = {'walk': chor_street, 'billboard': chor_street, 'lookup': chor_street, 'car': chor_street,
        'enter': chor_enter, 'welcome': chor_room, 'timeline': chor_room, 'notice': chor_room,
        'turn': chor_room, 'symbol': chor_room, 'stare': chor_room}
CHOR_PEOPLE = {'anchor': chor_anchor, 'scidata': chor_lab2}

# ============================================================================
# Cameras (one rig per shot; every shot moves) and everything that moves on its own each frame
# ============================================================================
def V3(*a):
    return Vector(a)


def landmark(name, P, fn=None):
    """Pose a character once (before the cameras are built) and read off where its eyes end up."""
    pose(name, P)
    CH[name]['J']['root'].rotation_euler = (0, 0, R(P.get('yaw', 0.0)))
    bpy.context.view_layer.update()
    e = eyes_pt(name)
    park(name)
    return e


CAR_STOP = -1.0


def fwd(yaw):
    """The horizontal direction a character with this yaw (degrees) faces."""
    return V3(-math.sin(R(yaw)), math.cos(R(yaw)), 0)


def car_x(t):
    """The government car brakes in from the left and stops beside him."""
    u = ramp(t, 10.45, 11.8)
    return CAR_STOP - 18.0 * (1.0 - u) ** 2


def build_cameras():
    # where the main character's eyes are in each set-up
    look_e = landmark(YOU, dict(loc=(LOOKUP_X, WALK_Y, 0.15), yaw=-165))
    stare_e = landmark(YOU, dict(loc=tuple(RROOM + V3(1.6, -2.4, 0)), yaw=-70))
    sci_e = landmark('sci1', dict(loc=tuple(RROOM + V3(4.0, -0.6, 0)), yaw=-233))
    # SCENE 1 - the street, the giant screen switches on
    x0 = -15.0 + 1.15 * 0.4
    camera_shot('walk', 35, [(0, V3(x0 + 4.2, -2.9, 1.25)), (1, V3(x0 + 4.9, -2.85, 1.3))],
                [(0, V3(x0, WALK_Y, 1.45)), (1, V3(x0 + 1.7, WALK_Y, 1.5))], fstop=2.8, ease=False)
    G = GIANT
    gc = V3(0.0, G['y'], (G['z0'] + G['z1']) / 2)
    pc = V3(G['x1'] - (G['x1'] - G['x0']) * 440 / 2048, G['y'], G['z1'] - (G['z1'] - G['z0']) * 630 / 1152)   # his face on it
    camera_shot('billboard', 24, [(0, V3(-8.0, -2.6, 1.7)), (1, V3(5.0, -7.0, 10.8))],
                [(0, gc + V3(-1, 0, -1)), (1, pc + V3(0, 0, 0.4))], fstop=60, lenses=[(0, 20), (1, 26)], ease='EASE_IN')
    d = fwd(-165)                                             # his facing direction once he has turned
    camera_shot('lookup', 40, [(0, look_e + d * 1.6 + V3(0.35, 0, -0.75)), (1, look_e + d * 1.05 + V3(0.25, 0, -0.55))],
                [(0, look_e + V3(0, 0, -0.08)), (1, look_e + V3(0, 0, -0.03))], fstop=2.4)
    # SCENE 2 - the world finds out
    N = NEWSR
    camera_shot('anchor', 40, [(0, N + V3(1.6, 1.4, 1.3)), (1, N + V3(0.8, 2.5, 1.25))],
                [(0, N + V3(0.0, 5.8, 1.15)), (1, N + V3(0.0, 5.8, 1.2))], fstop=3.2)
    O = SQ
    camera_shot('screens', 24, [(0, O + V3(-4.0, -4.0, 1.7)), (1, O + V3(0.0, 4.0, 4.0))],
                [(0, O + V3(5.0, 59.8, 24.0)), (1, O + V3(5.0, 59.8, 30.0))], fstop=60, ease=False)
    camera_shot('crowd', 24, [(0, O + V3(-30.0, -32.0, 26.0)), (1, O + V3(-24.0, -27.0, 23.0))],
                [(0, O + V3(0.0, 15.0, 2.0)), (1, O + V3(2.0, 15.0, 4.0))], fstop=60, ease=False)
    S_ = SIT
    camera_shot('gov', 22, [(0, S_ + V3(0.3, -5.6, 2.3)), (1, S_ + V3(0.1, -3.9, 1.75))],
                [(0, S_ + V3(0.0, 5.88, 1.7)), (1, S_ + V3(0.0, 5.88, 1.9))], fstop=5.6)
    L_ = LAB
    camera_shot('scidata', 26, [(0, L_ + V3(2.4, 1.6, 1.7)), (1, L_ + V3(1.7, 1.9, 1.65))],
                [(0, L_ + V3(-0.6, 1.95, 1.5)), (1, L_ + V3(-0.65, 2.05, 1.55))], fstop=3.5)
    # SCENE 3 - the car, the facility, the welcome
    camera_shot('car', 30, [(0, V3(10.0, -8.6, 0.55)), (1, V3(8.6, -8.0, 0.75))],
                [(0, V3(-8.0, -6.0, 0.9)), (1, V3(1.0, -4.6, 1.1))], fstop=5.6)
    F = FACI
    camera_shot('enter', 20, [(0, F + V3(8.5, -11.0, 13.0)), (1, F + V3(6.6, -9.0, 3.4))],
                [(0, F + V3(2.0, 20.0, 4.0)), (1, F + V3(3.0, 14.0, 4.5))], fstop=60, ease='EASE_IN_OUT')
    Rr = RROOM
    mid = Rr + V3(-1.8, -2.3, 1.55)
    arc = []
    for k in range(5):
        u = k / 4
        a = R(-54 + 24 * u)
        arc.append((u, mid + V3(4.6 * math.cos(a), 4.6 * math.sin(a), 0.1 - 0.05 * u) * (1.0 - 0.12 * u)))
    camera_shot('welcome', 22, arc, [(0, mid + V3(-0.1, 0.1, 0.05)), (1, mid + V3(0.0, 0.0, 0.08))], fstop=2.8, ease=False)
    # SCENE 4 - the timeline
    camera_shot('timeline', 18, [(0, Rr + V3(-4.2, -2.8, 2.2)), (1, Rr + V3(-2.6, -0.2, 2.35))],
                [(0, Rr + V3(5.98, -3.0, 2.5)), (1, Rr + V3(5.98, 2.6, 2.5))], fstop=8.0, ease=False)
    ph = Rr + V3(5.96, 7.2 - 14.4 * 485 / 3200, 2.5 + 4.05 * (0.5 - 510 / 900))
    camera_shot('notice', 30, [(0, Rr + V3(0.8, 0.8, 2.1)), (0.6, Rr + V3(2.6, 3.0, 2.25)), (1, Rr + V3(3.3, 3.8, 2.3))],
                [(0, ph + V3(0, -3.4, 0)), (0.6, ph + V3(0, -0.4, 0)), (1, ph)], fstop=5.6, ease='EASE_IN_OUT')
    # SCENE 5 - the turn, the symbol, the stare
    dsc = fwd(-233)                                           # her facing once she has turned
    camera_shot('turn', 50, [(0, sci_e + dsc * 1.5 + V3(0.15, 0.0, -0.08)), (1, sci_e + dsc * 1.15 + V3(0.1, 0.0, -0.05))],
                [(0, sci_e + V3(0, 0, -0.06)), (1, sci_e + V3(0, 0, -0.04))], fstop=2.4)
    camera_shot('symbol', 24, [(0, Rr + V3(-1.6, -1.0, 1.75)), (1, Rr + V3(0.6, -0.4, 2.0))],
                [(0, Rr + V3(5.98, -0.2, 2.45)), (1, Rr + V3(5.98, 0.0, 2.5))], fstop=8.0, ease=False)
    dy = fwd(-70)
    camera_shot('stare', 50, [(0, stare_e + dy * 1.05 + V3(0, 0, -0.06)), (1, stare_e + dy * 0.55 + V3(0, 0, -0.01))],
                [(0, stare_e + V3(0, 0, -0.07)), (1, stare_e + V3(0, 0, 0.0))], fstop=2.2, lenses=[(0, 45), (1, 55)])


def SV(key, v):
    for s in SHOTVAL.get(key, []):
        s.default_value = v


def flicker_on(t, a, b):
    """A big LED screen powering up: dark, a few stuttering flashes, then on."""
    if t < a:
        return 0.0
    if t >= b:
        return 1.0
    u = (t - a) / (b - a)
    k = int(u * 9)
    return (0.0, 0.7, 0.05, 0.0, 0.9, 0.2, 1.0, 0.6, 1.0)[k] * (0.4 + 0.6 * u)


def rr_image(t):
    return 'timeline' if t < 21.6 else ('anomaly' if t < 25.3 else 'symbol')


def update_world(t, shot):
    S = SETS
    SV('gtime', t)
    # the giant screen across the street powers on with his face
    on = flicker_on(t, 1.62, 1.98)
    SV('giant_on', on)
    SV('g_giant', 0.6 if 0.0 < on < 1.0 else (0.25 if 1.98 <= t < 2.2 else 0.0))
    S['giant_light'].data.energy = (6e3 if shot == 'lookup' else 1.4e4) * on if shot in ('billboard', 'lookup', 'car') else 0.0
    S['giant_light'].data.color = (0.75, 0.85, 1.0)
    for h in S['helis']:
        h['root'].location = (0, 0, -100)
    # the government car
    car = S['govcar']
    if shot == 'car':
        x = car_x(t)
        car['root'].location = (x, -6.6, 0.0)
        car['root'].rotation_euler = (R(-1.2 * (1.0 - ramp(t, 11.6, 12.0)) * (t > 11.0)), 0, R(-90))
        for w in car['wheels']:
            w.rotation_euler = (-(x - CAR_STOP + 18.0) / 0.42, 0, 0)
        u = smooth(ramp(t, 12.0, 12.5))
        car['door'].location = (-1.03 - 0.08 * min(1.0, u * 4), -0.3 - 1.1 * u, 0)
    else:
        car['root'].location = (-300, -6.6, 0)
    # the hologram turns
    S['holo'].rotation_euler = (R(8), 0, t * 0.35)
    # the research room screen: timeline -> the anomaly (his photo) -> the symbol
    img = teximg(rr_image(t))
    nt = MAT['scr_rr'].node_tree
    for nn in ('Img', 'Img2'):
        if nt.nodes[nn].image != img:
            nt.nodes[nn].image = img
    S['rr_portrait'].hide_render = not (21.6 <= t < 25.3 and shot in ('notice', 'turn'))
    g = 0.0
    for tc in (21.6, 25.3):
        if tc - 0.12 <= t < tc + 0.2:
            g = 0.8
    if t >= 27.85:
        g = 1.0
    SV('g_rr', g)
    pulse = 0.85 + 0.15 * math.sin(t * 2.4)
    SV('rr_e', (2.2 if t < 25.3 else 3.2 * pulse) * (0.15 if t >= 28.25 else 1.0))
    # the lights dim as she turns
    dim = smooth(ramp(t, 24.0, 24.8))
    for lt in S['rr_lights']:
        lt.data.energy = 380.0 * (1.0 - 0.9 * dim)
    if 'faci_tops' not in S:
        S['faci_tops'] = [o for o in bpy.data.objects if o.name.startswith('FaciTop')]
    for lt in S['faci_tops']:
        lt.data.energy = 1800.0 * (1.0 - 0.75 * dim)
    sl = S['rr_scr_light']
    if t < 25.3:
        sl.data.energy, sl.data.color = 300.0 * (1.15 if 21.6 <= t else 1.0), (0.5, 0.78, 1.0) if t < 21.6 else (0.9, 0.55, 0.55)
    else:
        sl.data.energy, sl.data.color = 420.0 * pulse * (0.15 if t >= 28.25 else 1.0), (0.62, 0.35, 1.0)
    SV('holo_e', 5.0 * (1.0 - 0.6 * dim))
    # the situation room's red alert light
    S['sit_light'].data.energy = 160.0 * (0.25 + 0.75 * max(0.0, math.sin(t * 5.0)) ** 2)
    # every screen in the newsroom shows his face
    for (ob, tex), pp in zip(S['nwall'], S['nwallp']):
        ob.data.materials[0] = MAT['scr_only']
        pp.hide_render = shot != 'anchor'
    if shot in ('screens', 'crowd'):
        y0 = S['sq_crowd_yaw']
        set_attr(S['sq_crowd'], 'yaw', y0 + 0.05 * np.sin(t * 0.8 + np.arange(len(y0)) * 0.37))


def animate(t, shot):
    for nm in [YOU] + list(HEROES):
        park(nm)
    fn = CHOR.get(shot)
    if fn is not None:
        fn(t, shot)
    else:
        hide_phone()
    fp = CHOR_PEOPLE.get(shot)
    if fp is not None:
        fp(t, shot)
    update_world(t, shot)

# ============================================================================
# Materials
# ============================================================================
def V_(nt, m, key, v):
    """A Value node registered under `key` (animated per shot / per frame through SHOTVAL)."""
    s = value(nt, key, v)
    register_value(m, key, key)
    return s


def screen_mat(name, tex, gkey, strength, skey=None, overlay=None, live=False, ekey=None):
    """An LED / LCD screen: emissive image, faint scanlines, horizontal-band glitch (gkey), TV static (skey), an
    optional RGBA overlay (HUD) and an optional red "LIVE" wash (live)."""
    m, nt, out = new_mat(name)
    uv = nd(nt, 'ShaderNodeTexCoord').outputs['UV']
    s = sep(nt, uv)
    g = V_(nt, m, gkey, 0.0)
    tt = V_(nt, m, 'gtime', 0.0)
    band = mth(nt, 'FLOOR', mth(nt, 'MULTIPLY', s.outputs['Y'], 26.0))
    bt = mth(nt, 'FLOOR', mth(nt, 'MULTIPLY', tt, 12.0))
    wn = nd(nt, 'ShaderNodeTexWhiteNoise', p_noise_dimensions='3D', Vector=comb(nt, band, bt, 0.0))
    sel = mth(nt, 'GREATER_THAN', sep(nt, wn.outputs['Color']).outputs['X'], 0.55)
    off = mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', mth(nt, 'SUBTRACT', wn.outputs['Value'], 0.5), g), mth(nt, 'MULTIPLY', sel, 0.5))
    u2 = mth(nt, 'ADD', s.outputs['X'], off)
    img = nd(nt, 'ShaderNodeTexImage', p_image=teximg(tex), p_interpolation='Linear', p_extension='EXTEND', Vector=comb(nt, u2, s.outputs['Y'], 0.0))
    img.name = 'Img'
    col = img.outputs['Color']
    # chromatic split while glitching: shift red one way
    img2 = nd(nt, 'ShaderNodeTexImage', p_image=teximg(tex), p_interpolation='Linear', p_extension='EXTEND',
              Vector=comb(nt, mth(nt, 'ADD', u2, mth(nt, 'MULTIPLY', g, 0.012)), s.outputs['Y'], 0.0))
    img2.name = 'Img2'
    sp = nd(nt, 'ShaderNodeSeparateColor', Color=col)
    sp2 = nd(nt, 'ShaderNodeSeparateColor', Color=img2.outputs['Color'])
    col = nd(nt, 'ShaderNodeCombineColor', Red=sp2.outputs['Red'], Green=sp.outputs['Green'], Blue=sp.outputs['Blue']).outputs[0]
    if overlay:
        ov = nd(nt, 'ShaderNodeTexImage', p_image=teximg(overlay), p_interpolation='Linear', p_extension='EXTEND', Vector=uv)
        col = mixc(nt, ov.outputs['Alpha'], col, ov.outputs['Color'])
    if skey:
        st = V_(nt, m, skey, 0.0)
        wn2 = nd(nt, 'ShaderNodeTexWhiteNoise', p_noise_dimensions='3D',
                 Vector=comb(nt, mth(nt, 'FLOOR', mth(nt, 'MULTIPLY', s.outputs['X'], 320.0)),
                             mth(nt, 'FLOOR', mth(nt, 'MULTIPLY', s.outputs['Y'], 180.0)), mth(nt, 'MULTIPLY', tt, 30.0)))
        col = mixc(nt, st, col, wn2.outputs['Color'])
    if live:
        lv = V_(nt, m, 'live', 0.0)
        red = mixc(nt, 0.5, col, (1.0, 0.1, 0.08, 1))
        col = mixc(nt, mth(nt, 'MULTIPLY', lv, 0.35), col, red)
    lines = mth(nt, 'MULTIPLY_ADD', mth(nt, 'SINE', mth(nt, 'MULTIPLY', s.outputs['Y'], 1400.0)), 0.07, 0.93)
    strength = V_(nt, m, ekey, strength) if ekey else strength
    e = nd(nt, 'ShaderNodeEmission', Color=col, Strength=mth(nt, 'MULTIPLY', lines, strength))
    gl_ = nd(nt, 'ShaderNodeBsdfGlossy', Roughness=0.08, Color=(0.04, 0.04, 0.045, 1))
    ad = nd(nt, 'ShaderNodeAddShader')
    nt.links.new(e.outputs[0], ad.inputs[0])
    nt.links.new(gl_.outputs[0], ad.inputs[1])
    nt.links.new(ad.outputs[0], out.inputs['Surface'])
    MAT[name] = m
    return m


def glow_img(name, tex, strength, alpha=False, key=None):
    m, nt, out = new_mat(name)
    t = nd(nt, 'ShaderNodeTexImage', p_image=teximg(tex), p_interpolation='Linear', p_extension='EXTEND')
    if key:
        strength = mth(nt, 'MULTIPLY', V_(nt, m, key, 1.0), strength)
    e = nd(nt, 'ShaderNodeEmission', Color=t.outputs['Color'], Strength=strength)
    if alpha:
        tr = nd(nt, 'ShaderNodeBsdfTransparent')
        mx = nd(nt, 'ShaderNodeMixShader', Fac=t.outputs['Alpha'])
        nt.links.new(tr.outputs[0], mx.inputs[1])
        nt.links.new(e.outputs[0], mx.inputs[2])
        nt.links.new(mx.outputs[0], out.inputs['Surface'])
    else:
        nt.links.new(e.outputs[0], out.inputs['Surface'])
    MAT[name] = m
    return m


def future_facade(name, glass, frame, mull=1.6, floor=4.2, band=(0.55, 0.8, 1.0), lit=0.22, stone=False):
    """Curtain-wall towers: glass between mullions and floor slabs, a glowing band every few floors, some lit windows."""
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    s_ = sep(nt, oc)
    h = mth(nt, 'ADD', s_.outputs['X'], s_.outputs['Y'])
    z = s_.outputs['Z']
    u = mth(nt, 'FRACT', mth(nt, 'DIVIDE', h, mull))
    v = mth(nt, 'FRACT', mth(nt, 'DIVIDE', z, floor))
    fw = 0.22 if stone else 0.06
    pane = mth(nt, 'MULTIPLY', mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', u, fw), mth(nt, 'LESS_THAN', u, 1 - fw)),
               mth(nt, 'MULTIPLY', mth(nt, 'GREATER_THAN', v, 0.16 if stone else 0.1), mth(nt, 'LESS_THAN', v, 0.92)))
    cell = comb(nt, mth(nt, 'FLOOR', mth(nt, 'DIVIDE', h, mull)), mth(nt, 'FLOOR', mth(nt, 'DIVIDE', z, floor)), 0.0)
    wn = nd(nt, 'ShaderNodeTexWhiteNoise', p_noise_dimensions='3D', Vector=cell)
    gcol = mixc(nt, mth(nt, 'MULTIPLY', wn.outputs['Value'], 0.6), rgba(glass), rgba([min(1, c * 1.6) for c in glass]))
    col = mixc(nt, pane, rgba(frame), gcol)
    roof = mth(nt, 'GREATER_THAN', mth(nt, 'ABSOLUTE', sep(nt, nd(nt, 'ShaderNodeNewGeometry').outputs['Normal']).outputs['Z']), 0.5)
    col = mixc(nt, roof, col, (0.28, 0.28, 0.3, 1))
    pane = mth(nt, 'MULTIPLY', pane, mth(nt, 'SUBTRACT', 1.0, roof))
    rough = mth(nt, 'ADD', mth(nt, 'MULTIPLY', pane, -0.6), 0.7)
    p = principled(nt, out, **{'Base Color': col, 'Roughness': rough, 'Metallic': mth(nt, 'MULTIPLY', pane, 0.0 if stone else 0.6),
                               'Specular IOR Level': 0.6})
    fl = mth(nt, 'FLOOR', mth(nt, 'DIVIDE', z, floor))
    bandm = mth(nt, 'MULTIPLY', mth(nt, 'LESS_THAN', mth(nt, 'MODULO', fl, 6.0), 0.5), mth(nt, 'LESS_THAN', v, 0.08))
    on = mth(nt, 'MULTIPLY', pane, mth(nt, 'GREATER_THAN', sep(nt, wn.outputs['Color']).outputs['Y'], 1 - lit))
    em = mixc(nt, bandm, (1.0, 0.85, 0.65, 1), rgba(band))
    nt.links.new(em, p.inputs['Emission Color'])
    lv = V_(nt, m, 'citylit', 1.0)
    nt.links.new(mth(nt, 'MULTIPLY', mth(nt, 'ADD', mth(nt, 'MULTIPLY', bandm, 6.0), mth(nt, 'MULTIPLY', on, 1.4)), lv), p.inputs['Emission Strength'])
    MAT[name] = m



def panel_metal(name, base, size=(1.2, 1.2), rough=0.35):
    m, nt, out = new_mat(name)
    oc = obj_coord(nt)
    s_ = sep(nt, oc)
    hx = mth(nt, 'ADD', s_.outputs['X'], s_.outputs['Y'])
    a = mth(nt, 'FRACT', mth(nt, 'DIVIDE', hx, size[0]))
    b = mth(nt, 'FRACT', mth(nt, 'DIVIDE', s_.outputs['Z'], size[1]))
    seam = mth(nt, 'MAXIMUM', mth(nt, 'LESS_THAN', a, 0.012), mth(nt, 'LESS_THAN', b, 0.012))
    cell = comb(nt, mth(nt, 'FLOOR', mth(nt, 'DIVIDE', hx, size[0])), mth(nt, 'FLOOR', mth(nt, 'DIVIDE', s_.outputs['Z'], size[1])), 0.0)
    wn = nd(nt, 'ShaderNodeTexWhiteNoise', p_noise_dimensions='3D', Vector=cell).outputs['Value']
    col = mixc(nt, mth(nt, 'MULTIPLY', wn, 0.35), rgba(base), rgba([c * 1.4 for c in base]))
    col = mixc(nt, seam, col, (0.005, 0.005, 0.006, 1))
    principled(nt, out, **{'Base Color': col, 'Metallic': 0.75, 'Roughness': mth(nt, 'ADD', rough, mth(nt, 'MULTIPLY', wn, 0.15))})
    MAT[name] = m


def glass_window_material():
    m, nt, out = new_mat('window_glass')
    lw = nd(nt, 'ShaderNodeLayerWeight', Blend=0.25)
    tp = nd(nt, 'ShaderNodeBsdfTransparent', Color=(0.96, 0.98, 0.98, 1))
    gl = nd(nt, 'ShaderNodeBsdfGlossy', Roughness=0.02)
    mx = nd(nt, 'ShaderNodeMixShader', Fac=mth(nt, 'MULTIPLY_ADD', lw.outputs['Fresnel'], 0.6, 0.04))
    nt.links.new(tp.outputs[0], mx.inputs[1])
    nt.links.new(gl.outputs[0], mx.inputs[2])
    nt.links.new(mx.outputs[0], out.inputs['Surface'])
    MAT['window_glass'] = m




