def set_light(L, cfg_):
    sc = bpy.context.scene
    hc, zc, st = L['sky']
    SKY['hor'].outputs[0].default_value = rgba(hc)
    SKY['zen'].outputs[0].default_value = rgba(zc)
    SKY['bg'].inputs['Strength'].default_value = st
    el, az, en, col = cfg_.get('sun', L['sun'])
    d = sun_dir(el, az)
    for i, c in enumerate('XYZ'):
        SKY['sunvec'].inputs[c].default_value = d[i]
    SKY['glow'].outputs[0].default_value = L['glow'][0]
    SKY['glowcol'].outputs[0].default_value = rgba(L['glow'][1])
    SKY['clouds'].outputs[0].default_value = L['clouds']
    SKY['cloudcol'].outputs[0].default_value = rgba([min(1.0, c * 1.15) for c in hc])
    sun = SKY['sun']
    sun.rotation_euler = d.to_track_quat('Z', 'Y').to_euler()
    sun.data.energy = en
    sun.data.color = col
    sun.hide_render = en <= 0
    w = sc.world
    w.mist_settings.start, w.mist_settings.depth = L['mist']
    nt = sc.node_tree
    nt.nodes['FogAmt'].inputs[0].default_value = L['fog'][0]
    nt.nodes['FogColor'].inputs[2].default_value = rgba(L['fog'][1])


def apply_shot(name):
    cfg_ = SHOTCFG[name]
    sc = bpy.context.scene
    groups = set(cfg_['groups'])
    hide = set(cfg_.get('hide', [])) | (set(os.environ.get('MT_HIDE', '').split(',')) - {''})
    for g in ALL_GROUPS:
        if g not in COLL:
            continue
        vis = g in groups
        for ob in COLL[g].all_objects:
            if ob.type != 'EMPTY':
                ob.hide_render = (not vis) or any(ob.name.startswith(h) for h in hide)
    sc.cycles.samples = max(2, int(round(SPP[0] * cfg_.get('spp', 1.0))))
    for key, socks in SHOTVAL.items():
        if key in DEFAULTS or key in cfg_:
            v = cfg_.get(key, DEFAULTS.get(key, 0.0))
            for s in socks:
                s.default_value = v
    set_light(cfg_['light'], cfg_)
    nt = sc.node_tree
    nt.nodes['BeamAmt'].inputs[0].default_value = cfg_.get('beams', 0.0)
    lift, gamma, gain, sat = GRADE[cfg_['grade']]
    nt.nodes['Grade'].lift, nt.nodes['Grade'].gamma, nt.nodes['Grade'].gain = lift, gamma, gain
    nt.nodes['Sat'].inputs['Saturation'].default_value = sat
    sc.view_settings.exposure = cfg_['exposure'] + float(os.environ.get('MT_EXP', '0'))
    CUR['shot'] = name


def sun_beam_centre(cs, name):
    L = SHOTCFG[name]['light']
    el, az, en, col = SHOTCFG[name].get('sun', L['sun'])
    d = sun_dir(el, az)
    from bpy_extras.object_utils import world_to_camera_view
    sc = bpy.context.scene
    co = world_to_camera_view(sc, sc.camera, Vector(cs['loc']) + d * 1000.0)
    return (co.x, co.y)



def build_emitters():
    def motes(name, centre, area=3.0, rate=40.0, kind='dot', op=0.4, size=(0.004, 0.008)):
        EMIT.setdefault(name, []).append(emitter(kind, [tuple(centre)], rate, 6.0, (0.0, 0.0, 0.01), 0.02, size, opacity=op,
                                                 area=area, t0=SHOT[name]['t0'] - 6.0, rise=0.0, turb=0.15, salt=len(EMIT.get(name, []))))
    motes('enter', FACI + Vector((2.0, 4.0, 3.0)), 8.0, 60, op=0.25, size=(0.01, 0.02))
    motes('welcome', RROOM + Vector((-1.8, -2.3, 1.7)), 2.0, 40, op=0.3)
    motes('stare', RROOM + Vector((1.6, -2.4, 1.7)), 1.5, 30, op=0.3)


def on_frame(scene, depsgraph=None):
    f = scene.frame_current
    t = tsec(f)
    s = shot_at(f)
    name = s['name']
    if CUR.get('shot') != name:
        apply_shot(name)
    cs = cam_state(name, f)
    CUR['camloc'] = cs['loc']
    animate(t, name)
    update_particles(t, name, cs)
    CAMS[name].location = shake_offset(t, name)
    if SHOTCFG[name].get('beams'):
        try:
            bx, by = sun_beam_centre(cs, name)
            scene.node_tree.nodes['Beams'].source = (bx, by)
        except Exception:
            pass



# ============================================================================
# The ID portrait and the presenter feed: rendered once from the 3D characters, then shown on the screens
# ============================================================================
def render_still_from(sc, cam_loc, target, lens, path, size, groups=None):
    cd = bpy.data.cameras.new('FeedCam')
    cd.lens = lens
    cd.sensor_width = 36
    cd.clip_end = 5000
    ob = bpy.data.objects.new('FeedCam', cd)
    coll('Rig').objects.link(ob)
    ob.location = cam_loc
    ob.rotation_euler = (Vector(target) - Vector(cam_loc)).to_track_quat('-Z', 'Y').to_euler()
    old = (sc.camera, sc.render.resolution_x, sc.render.resolution_y, sc.render.resolution_percentage, sc.render.filepath)
    sc.camera = ob
    sc.render.resolution_x, sc.render.resolution_y = size
    sc.render.resolution_percentage = 100
    sc.render.filepath = path
    if groups is not None:
        for g in ALL_GROUPS:
            if g in COLL:
                for o in COLL[g].all_objects:
                    if o.type != 'EMPTY':
                        o.hide_render = g not in groups
    mk = sc.timeline_markers.new('FEED', frame=sc.frame_current)      # a marker binds this camera for this frame
    mk.camera = ob
    bpy.ops.render.render(write_still=True)
    sc.timeline_markers.remove(mk)
    sc.camera, sc.render.resolution_x, sc.render.resolution_y, sc.render.resolution_percentage, sc.render.filepath = old
    bpy.data.objects.remove(ob)


def render_feeds(sc):
    flag = os.path.join(TEX, 'feeds_ok')
    if os.path.exists(flag):
        return
    print('rendering the ID portrait and the presenter feed (once) ...', flush=True)
    h = list(bpy.app.handlers.frame_change_pre)
    CUR.clear()
    sc.frame_set(3)
    bpy.app.handlers.frame_change_pre.clear()
    for nm in [YOU] + list(HEROES):
        park(nm)
    set_light(L_INT, {})
    sc.view_settings.exposure = 0.0
    O = BOOTH
    pose(YOU, merge(dict(loc=tuple(O + Vector((0, 0.2, 0))), yaw=180), NEUTRAL_F, dict(lid=0.36)))
    bpy.context.view_layer.update()
    fc = face_pt(YOU)
    render_still_from(sc, fc + Vector((0.0, -1.7, 0.02)), fc + Vector((0, 0, -0.06)), 85, os.path.join(TEX, 'portrait.png'), (480, 600),
                      groups=['Booth', 'Chars'])
    park(YOU)
    for fn in h:
        bpy.app.handlers.frame_change_pre.append(fn)
    for im in bpy.data.images:
        if im.filepath and os.path.basename(im.filepath).split('.')[0] in ('portrait',):
            im.reload()
    open(flag, 'w').write('ok\n')
    CUR.clear()


# ============================================================================
# Stage: render
# ============================================================================
def build_scene():
    ensure_textures()
    sc = reset_scene()
    setup_render(sc)
    build_materials()
    build_world(sc)
    build_compositor(sc)
    for name in ALL_GROUPS:
        coll(name)
    build_sets()
    build_fx()
    build_cast()
    build_crowds()
    for m in bpy.data.materials:
        m.cycles.emission_sampling = 'NONE'
    for nm in ('scr_giant', 'scr_rr', 'scr_urgent', 'scr_search', 'scr_bc', 'holo'):
        MAT[nm].cycles.emission_sampling = 'AUTO'
    bpy.context.view_layer.update()
    build_cameras()
    build_emitters()
    bpy.app.handlers.frame_change_pre.clear()
    bpy.app.handlers.frame_change_pre.append(on_frame)
    print('SHOTS:')
    for s in SHOTS:
        print(f"  {s['name']:14s} frames {s['f0']:4d}-{s['f1']:4d}  ({s['t0']:5.2f}-{s['t1']:5.2f} s)")
    print('objects:', len(bpy.data.objects), ' render frames 1 -', RENDER_END)
    return sc


def stage_render():
    sc = build_scene()
    render_feeds(sc)
    if ARGS.save_blend:
        bpy.ops.wm.save_as_mainfile(filepath=os.path.abspath(ARGS.save_blend))
    os.makedirs(ARGS.out, exist_ok=True)
    if ARGS.stills:
        for tok in ARGS.stills.split(','):
            f = int(tok)
            CUR.clear()
            sc.frame_set(f)
            sc.render.filepath = os.path.join(ARGS.out, f'still_{f:04d}.png')
            bpy.ops.render.render(write_still=True)
        return
    a, b = 1, RENDER_END
    if ARGS.frames:
        a, b = (int(x) for x in ARGS.frames.split('-'))
    b = min(b, RENDER_END)
    sc.render.filepath = os.path.join(ARGS.out, 'f_')
    for s in SHOTS:
        lo, hi = max(a, s['f0']), min(b, s['f1'])
        if lo > hi:
            continue
        if all(os.path.exists(os.path.join(ARGS.out, f'f_{f:04d}.png')) for f in range(lo, hi + 1)):
            continue
        CUR.clear()
        sc.frame_set(lo)
        sc.frame_start, sc.frame_end = lo, hi
        print(f'--- rendering shot {s["name"]} frames {lo}-{hi}', flush=True)
        bpy.ops.render.render(animation=True)

# ============================================================================
# Stage: audio - synthesised score and sound design (numpy only), ducked under the narration
# ============================================================================
SR = 48000


def _bandpass(x, lo, hi, order=2):
    X = np.fft.rfft(x)
    f = np.fft.rfftfreq(len(x), 1 / SR) + 1e-3
    H = np.ones_like(f)
    if lo:
        H /= np.sqrt(1 + (lo / f) ** (2 * order))
    if hi:
        H /= np.sqrt(1 + (f / hi) ** (2 * order))
    return np.fft.irfft(X * H, len(x))


def _sweep_bp(x, centre_fn, q=6.0, block=4096):
    """Time-varying band-pass (overlap-add of FFT-filtered Hann blocks)."""
    out = np.zeros(len(x) + block)
    win = np.hanning(block)
    hop = block // 2
    f = np.fft.rfftfreq(block, 1 / SR) + 1e-3
    for i in range(0, len(x), hop):
        seg = x[i:i + block]
        if len(seg) < block:
            seg = np.pad(seg, (0, block - len(seg)))
        fc = centre_fn((i + block / 2) / SR)
        bw = fc / q
        H = 1.0 / np.sqrt(1 + ((f - fc) / bw) ** 2)
        out[i:i + block] += np.fft.irfft(np.fft.rfft(seg * win) * H, block)
    return out[:len(x)]


def _noise(n, seed, colour='white'):
    r = np.random.default_rng(seed).standard_normal(n)
    if colour == 'white':
        return r
    X = np.fft.rfft(r)
    f = np.fft.rfftfreq(n, 1 / SR) + 1.0
    X /= np.sqrt(f) if colour == 'pink' else f
    y = np.fft.irfft(X, n)
    return y / (np.abs(y).max() + 1e-9)


def _env(t, pts):
    """Piecewise-linear envelope from [(time, value), ...]."""
    ts, vs = zip(*pts)
    return np.interp(t, ts, vs)


def _reverb(x, seconds=2.6, seed=0, damp=3.0):
    n = int(seconds * SR)
    tt = np.arange(n) / SR
    ir = np.random.default_rng(seed).standard_normal(n) * np.exp(-damp * tt / seconds * 2.3)
    ir = _bandpass(ir, 120, 6000)
    ir /= np.sqrt((ir ** 2).sum())
    L = len(x) + n
    y = np.fft.irfft(np.fft.rfft(x, L) * np.fft.rfft(ir, L), L)[:len(x)]
    return y


def _place(buf, sig, t0, gain=1.0, pan=0.0):
    i = int(t0 * SR)
    if i >= buf.shape[1] or i + len(sig) <= 0:
        return
    j0 = max(0, -i)
    sig = sig[j0:]
    i = max(i, 0)
    n = min(len(sig), buf.shape[1] - i)
    gl = math.cos((pan + 1) * math.pi / 4) * gain
    gr = math.sin((pan + 1) * math.pi / 4) * gain
    buf[0, i:i + n] += sig[:n] * gl
    buf[1, i:i + n] += sig[:n] * gr


def _boom(dur=2.5, f0=62, f1=32, seed=0):
    t = np.arange(int(dur * SR)) / SR
    ph = 2 * np.pi * np.cumsum(f1 + (f0 - f1) * np.exp(-t * 3.0)) / SR
    body = np.sin(ph) * np.exp(-t * 1.6)
    n = _bandpass(_noise(len(t), seed), None, 260) * np.exp(-t * 5.0) * 0.6
    return np.tanh(1.6 * (body + n))


def _pluck(freq, dur=3.0, bright=1.0):
    t = np.arange(int(dur * SR)) / SR
    y = np.zeros_like(t)
    for k, a in ((1, 1.0), (2, 0.45 * bright), (3, 0.18 * bright), (4, 0.09 * bright), (5.02, 0.05)):
        y += a * np.sin(2 * np.pi * freq * k * t) * np.exp(-t * (1.4 + 0.9 * k))
    return y * np.minimum(t / 0.004, 1)


def _crunch(seed, dur=0.16):
    t = np.arange(int(dur * SR)) / SR
    r = np.random.default_rng(seed)
    grains = (r.random(len(t)) < 0.02) * r.standard_normal(len(t))
    y = _bandpass(grains + 0.2 * r.standard_normal(len(t)), 700, 5500) * np.exp(-t * 22)
    return y / (np.abs(y).max() + 1e-9)


def _pad(notes, dur, seed=0, cutoff=900):
    t = np.arange(int(dur * SR)) / SR
    y = np.zeros_like(t)
    r = np.random.default_rng(seed)
    for f in notes:
        for det in (-0.12, 0.0, 0.13):
            ph = r.uniform(0, 1)
            saw = 2 * ((t * f * (1 + det / 100) + ph) % 1.0) - 1
            y += saw
    y = _bandpass(y, 40, cutoff, order=2)
    return y / (np.abs(y).max() + 1e-9)





def _roar(n, seed):
    y = _bandpass(_noise(n, seed, 'brown'), 30, 700)
    return y / (np.abs(y).max() + 1e-9)


def _bell(freq, dur=6.0):
    t = np.arange(int(dur * SR)) / SR
    y = np.zeros_like(t)
    for k, a, d in ((0.5, 0.5, 0.6), (1.0, 1.0, 0.9), (1.19, 0.5, 1.4), (1.5, 0.35, 1.6), (2.0, 0.3, 2.0), (2.74, 0.2, 2.6)):
        y += a * np.sin(2 * np.pi * freq * k * t) * np.exp(-t * d)
    return y * np.minimum(t / 0.003, 1)





def _norm(y):
    return y / (np.abs(y).max() + 1e-9)


def _foghorn(dur=3.2, f=110.0):
    """Two-tone diaphone-like horn (the sound of San Francisco Bay at night)."""
    t = np.arange(int(dur * SR)) / SR
    env = np.minimum(t / 0.25, 1) * np.minimum((dur - t) / 0.6, 1)
    split = dur * 0.62
    ff = np.where(t < split, f, f * 0.84)
    ph = 2 * np.pi * np.cumsum(ff) / SR
    y = np.sign(np.sin(ph)) * 0.5 + np.sin(ph) + 0.4 * np.sin(2 * ph)
    return _norm(_bandpass(y, 60, 900)) * env


def _siren(dur, f0=640.0, f1=1150.0, period=3.4):
    """A wailing mechanical siren (rising and falling)."""
    t = np.arange(int(dur * SR)) / SR
    k = 0.5 - 0.5 * np.cos(2 * np.pi * t / period)
    f = f0 + (f1 - f0) * k
    ph = 2 * np.pi * np.cumsum(f) / SR
    y = np.sin(ph) + 0.35 * np.sin(2 * ph) + 0.15 * np.sin(3 * ph)
    return _norm(y)


def _tick(seed, bright=1.0):
    t = np.arange(int(0.05 * SR)) / SR
    r = np.random.default_rng(seed)
    y = r.standard_normal(len(t)) * np.exp(-t * 400) + 0.6 * np.sin(2 * np.pi * 3100 * t) * np.exp(-t * 260)
    return _norm(_bandpass(y, 900 * bright, 9000)) * 0.8


def _key(seed):
    """A typewriter key strike: thump + bright clack + carriage rattle."""
    r = np.random.default_rng(seed)
    t = np.arange(int(0.12 * SR)) / SR
    clack = _bandpass(r.standard_normal(len(t)), 1500, 7000) * np.exp(-t * 90)
    thump = np.sin(2 * np.pi * 160 * t) * np.exp(-t * 60) * 0.7
    ring = np.sin(2 * np.pi * r.uniform(2400, 3200) * t) * np.exp(-t * 120) * 0.25
    return _norm(clack + thump + ring)


def _paper(dur, seed):
    """Paper sliding on a desk."""
    t = np.arange(int(dur * SR)) / SR
    y = _sweep_bp(_noise(len(t), seed), lambda x: 1800 + 2400 * math.sin(math.pi * x / dur), q=2.0)
    return _norm(y) * np.sin(np.pi * t / dur) ** 0.8


def _step(seed):
    t = np.arange(int(0.25 * SR)) / SR
    r = np.random.default_rng(seed)
    y = _bandpass(r.standard_normal(len(t)), 80, 1800) * np.exp(-t * 30) + np.sin(2 * np.pi * 70 * t) * np.exp(-t * 40)
    return _norm(y)


def _stamp():
    t = np.arange(int(0.4 * SR)) / SR
    y = np.sin(2 * np.pi * 85 * t) * np.exp(-t * 18) + _bandpass(_noise(len(t), 77), 200, 3000) * np.exp(-t * 40) * 0.6
    return _norm(y)


def _click():
    t = np.arange(int(0.08 * SR)) / SR
    y = _bandpass(_noise(len(t), 88), 1200, 8000) * np.exp(-t * 160) + 0.3 * np.sin(2 * np.pi * 900 * t) * np.exp(-t * 90)
    return _norm(y)



def _crowd(n, seed, density=1.0):
    """A cheering street crowd: a band-limited roar with swells, plus scattered claps and whistles."""
    t = np.arange(n) / SR
    r = np.random.default_rng(seed)
    roar = _norm(_bandpass(_noise(n, seed, 'pink'), 250, 3200))
    swell = 0.65 + 0.35 * np.sin(2 * np.pi * t / 2.7 + r.uniform(0, 6)) * np.sin(2 * np.pi * t / 1.3)
    y = roar * swell * 0.6
    claps = np.zeros(n)
    for _ in range(int(n / SR * 140 * density)):
        i = r.integers(0, n - 2000)
        k = np.arange(900)
        claps[i:i + 900] += r.standard_normal(900) * np.exp(-k / 90.0) * r.uniform(0.3, 1.0)
    y += _norm(_bandpass(claps, 700, 6000)) * 0.45
    for _ in range(int(n / SR * 0.8 * density)):
        i = r.integers(0, max(1, n - SR))
        d = int(r.uniform(0.25, 0.6) * SR)
        tt = np.arange(d) / SR
        f = r.uniform(1600, 2600) * (1 + 0.15 * np.sin(2 * np.pi * tt / (d / SR) * 0.5))
        y[i:i + d] += np.sin(2 * np.pi * np.cumsum(f) / SR) * np.sin(np.pi * tt / tt[-1]) * 0.12
    return _norm(y)


def _engine(n, seed, base=42.0):
    """Idling / cruising motorcycle engines: a rough low harmonic series with jitter."""
    t = np.arange(n) / SR
    r = np.random.default_rng(seed)
    f = base * (1 + 0.04 * np.sin(2 * np.pi * t * 0.7) + 0.02 * r.standard_normal(n).cumsum() / np.sqrt(np.arange(1, n + 1)))
    ph = 2 * np.pi * np.cumsum(f) / SR
    y = sum(np.sin(k * ph + r.uniform(0, 6)) / k ** 0.8 for k in range(1, 9))
    y = y * (1 + 0.5 * np.sign(np.sin(ph * 0.5)))
    return _norm(_bandpass(y, 30, 900))


def _wings(n, seed):
    """A flock taking off: many fast, soft flaps."""
    r = np.random.default_rng(seed)
    y = np.zeros(n)
    for _ in range(140):
        i = int(r.uniform(0, 0.75) * n)
        rate = r.uniform(8, 13)
        for k in range(int(r.uniform(4, 12))):
            j = i + int(k * SR / rate)
            if j + 1500 >= n:
                break
            m = np.arange(1500)
            y[j:j + 1500] += r.standard_normal(1500) * np.exp(-m / 260.0) * (1 - k / 14)
    return _norm(_bandpass(y, 400, 5000))


def _snare(seed, muffle=1.0):
    t = np.arange(int(0.16 * SR)) / SR
    r = np.random.default_rng(seed)
    y = _bandpass(r.standard_normal(len(t)), 180, 4200 / muffle) * np.exp(-t * 26) + 0.6 * np.sin(2 * np.pi * 185 * t) * np.exp(-t * 38)
    return _norm(y)


def _phone(dur=1.6):
    """A 1960s desk telephone bell: a struck bell modulated by the 20 Hz ringer."""
    t = np.arange(int(dur * SR)) / SR
    bell = np.sin(2 * np.pi * 1180 * t) + 0.5 * np.sin(2 * np.pi * 2360 * t + 1) + 0.3 * np.sin(2 * np.pi * 1750 * t)
    gate = (np.sin(2 * np.pi * 20 * t) > 0) * 1.0
    return _norm(bell * (0.4 + 0.6 * gate) * np.minimum(t / 0.01, 1) * np.minimum((dur - t) / 0.08, 1))


def _static(dur, seed, crackle=1.0):
    t = np.arange(int(dur * SR)) / SR
    r = np.random.default_rng(seed)
    y = _bandpass(r.standard_normal(len(t)), 300, 3400) * (0.5 + 0.5 * np.abs(np.sin(2 * np.pi * t * 3.1)))
    pops = (r.random(len(t)) < 0.002 * crackle) * r.standard_normal(len(t)) * 6
    return _norm(y + _bandpass(pops, 500, 7000)) * np.minimum(t / 0.02, 1) * np.minimum((dur - t) / 0.08, 1)


def _horn(dur=3.4, freqs=(311.1, 370.0, 415.3)):
    """A distant locomotive chord horn."""
    t = np.arange(int(dur * SR)) / SR
    y = sum(np.sign(np.sin(2 * np.pi * f * t)) * 0.4 + np.sin(2 * np.pi * f * t) for f in freqs)
    env = np.minimum(t / 0.3, 1) * np.minimum((dur - t) / 0.8, 1)
    return _norm(_bandpass(y, 150, 1400)) * env


def _whoosh(dur, seed):
    t = np.arange(int(dur * SR)) / SR
    y = _sweep_bp(_noise(len(t), seed), lambda x: 300 + 3500 * (x / dur) ** 1.5, q=3.0)
    return _norm(y) * np.sin(np.pi * t / dur) ** 1.5




def _jet(dur, seed, f0=2600.0, f1=1700.0):
    """A distant jet passing: broadband roar plus a faint falling turbine whine (Doppler)."""
    n = int(dur * SR)
    tt = np.arange(n) / SR
    roar = _norm(_bandpass(_noise(n, seed, 'pink'), 120, 2200))
    f = f0 + (f1 - f0) * (tt / dur)
    whine = np.sin(2 * np.pi * np.cumsum(f) / SR) * 0.05
    env = np.sin(np.pi * np.clip(tt / dur, 0, 1)) ** 1.5
    return (roar + whine) * env


def _chatter(dur, seed):
    """Radio voices too far away to understand: band-limited noise shaped like syllables, with squelch."""
    n = int(dur * SR)
    tt = np.arange(n) / SR
    rng = np.random.default_rng(seed)
    sy = np.zeros(n)
    t = 0.05
    while t < dur - 0.2:
        a = int(t * SR)
        L = int(rng.uniform(0.08, 0.2) * SR)
        sy[a:a + L] += np.hanning(L)
        t += rng.uniform(0.1, 0.25) + (0.4 if rng.random() < 0.15 else 0.0)
    v = _norm(_bandpass(_noise(n, seed + 1), 500, 2600)) * sy
    v += 0.25 * np.sin(2 * np.pi * rng.uniform(180, 240) * tt) * sy
    return _norm(v) * 0.6 + _static(dur, seed + 2, 0.6)[:n] * 0.4


def _crickets(n, seed):
    tt = np.arange(n) / SR
    rng = np.random.default_rng(seed)
    out = np.zeros(n)
    for k in range(5):
        f = rng.uniform(4200, 5200)
        rate = rng.uniform(2.0, 3.4)
        ph = rng.uniform(0, 1)
        gate = (np.sin(2 * np.pi * (tt * rate + ph)) > 0.6).astype(float)
        trill = (np.sin(2 * np.pi * 38 * tt) > 0).astype(float)
        out += np.sin(2 * np.pi * f * tt) * gate * trill * rng.uniform(0.3, 1.0)
    return _norm(_bandpass(out, 3500, 6500))


def _clunk(seed):
    """A heavy breaker / contactor closing in a big metal building."""
    n = int(0.5 * SR)
    tt = np.arange(n) / SR
    body = np.sin(2 * np.pi * 70 * tt) * np.exp(-tt * 18) + 0.6 * np.sin(2 * np.pi * 140 * tt) * np.exp(-tt * 30)
    click = _bandpass(_noise(n, seed), 800, 5000) * np.exp(-tt * 90)
    return _norm(body + click * 0.8)


def _rumble_doors(dur, seed):
    n = int(dur * SR)
    tt = np.arange(n) / SR
    r = _norm(_bandpass(_noise(n, seed, 'pink'), 40, 400))
    roll = 0.7 + 0.3 * np.sin(2 * np.pi * 7.0 * tt) * np.sin(2 * np.pi * 2.3 * tt)
    squeal = 0.04 * np.sin(2 * np.pi * (900 + 60 * np.sin(2 * np.pi * 0.7 * tt)) * tt)
    return (r * roll + squeal) * np.minimum(tt / 0.3, 1)




# --- instruments and effects for this film -----------------------------------------------------
def _tt(dur):
    return np.arange(int(dur * SR)) / SR


def _mtof(m):
    return 440.0 * 2 ** ((m - 69) / 12.0)


def _adsr(t, a, d, s_, r, dur):
    env = np.where(t < a, t / max(a, 1e-4), np.where(t < a + d, 1 - (1 - s_) * (t - a) / max(d, 1e-4), s_))
    return env * np.clip((dur - t) / max(r, 1e-4), 0, 1)


def _saw(f, t, ph=0.0):
    return 2 * ((np.cumsum(np.broadcast_to(f, t.shape)) / SR + ph) % 1.0) - 1


def _marimba(freq, dur=0.6):
    t = _tt(dur)
    y = np.sin(2 * np.pi * freq * t) * np.exp(-t * 7) + 0.35 * np.sin(2 * np.pi * freq * 3.9 * t) * np.exp(-t * 26) \
        + 0.12 * np.sin(2 * np.pi * freq * 9.2 * t) * np.exp(-t * 60)
    return y * np.minimum(t / 0.002, 1)


def _pizz(freq, dur=0.35):
    t = _tt(dur)
    y = sum(a * np.sin(2 * np.pi * freq * k * t) * np.exp(-t * (9 + 5 * k)) for k, a in ((1, 1.0), (2, 0.5), (3, 0.28), (4, 0.12)))
    return y * np.minimum(t / 0.003, 1)


def _tuba(freq, dur=0.4):
    t = _tt(dur)
    y = _bandpass(_saw(freq * (1 + 0.004 * np.sin(2 * np.pi * 5 * t)), t), None, 520)
    return y * _adsr(t, 0.025, 0.08, 0.7, 0.08, dur)


def _brass(freqs, dur=0.5, bright=1600.0):
    t = _tt(dur)
    y = sum(_saw(f * (1 + 0.003 * np.sin(2 * np.pi * 5.5 * t + i)), t, i * 0.3) for i, f in enumerate(freqs))
    y = _sweep_bp(y, lambda tc: 300 + bright * min(tc / 0.06, 1.0), q=0.8, block=2048)
    return y * _adsr(t, 0.03, 0.1, 0.75, 0.12, dur)


def _whistle_note(freq, dur):
    t = _tt(dur)
    f = freq * (1 + 0.012 * np.sin(2 * np.pi * 5.8 * t) * np.clip(t / 0.15, 0, 1))
    y = np.sin(2 * np.pi * np.cumsum(f) / SR) + 0.05 * _bandpass(np.random.default_rng(int(freq)).standard_normal(len(t)), 1500, 6000)
    return y * _adsr(t, 0.03, 0.05, 0.8, 0.06, dur)


def _kick(dur=0.35):
    t = _tt(dur)
    f = 45 + 110 * np.exp(-t * 28)
    return np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-t * 9)


def _clap(seed):
    t = _tt(0.25)
    n = np.random.default_rng(seed).standard_normal(len(t))
    e = np.exp(-t * 30) + 0.6 * np.exp(-((t - 0.012) % 0.012) * 300) * (t < 0.036)
    return _bandpass(n, 900, 5000) * e


def _shaker(seed):
    t = _tt(0.09)
    return _bandpass(np.random.default_rng(seed).standard_normal(len(t)), 5000, 12000) * np.sin(np.pi * t / t[-1]) ** 2


def _taiko(dur=1.2):
    t = _tt(dur)
    f = 55 + 40 * np.exp(-t * 12)
    body = np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-t * 4)
    return np.tanh(1.5 * (body + 0.3 * _bandpass(np.random.default_rng(1).standard_normal(len(t)), None, 400) * np.exp(-t * 18)))


def _kaching(pitch=1.0, seed=0):
    """Cash register: a drawer clunk and a bright bell."""
    t = _tt(1.6)
    r = np.random.default_rng(seed)
    clunk = _bandpass(r.standard_normal(len(t)), 80, 900) * np.exp(-t * 35)
    clunk += np.sin(2 * np.pi * 95 * t) * np.exp(-t * 25) * 0.8
    bell = np.zeros_like(t)
    b0 = 0.09
    tb = np.clip(t - b0, 0, None)
    for k, a, d in ((1.0, 1.0, 3.0), (2.76, 0.5, 5.0), (5.4, 0.25, 8.0), (1.5, 0.3, 4.0)):
        bell += a * np.sin(2 * np.pi * 1900 * pitch * k * tb) * np.exp(-tb * d) * (t >= b0)
    return _norm(0.8 * clunk + 0.55 * bell)


def _scratch():
    """Record scratch: a short back-and-forth scrub."""
    t = _tt(0.55)
    pos = 0.06 * np.sin(2 * np.pi * 3.2 * t) * np.exp(-t * 1.5)
    rate = np.gradient(pos) * SR
    src = _noise(len(t) + 2000, 3, 'pink')
    idx = np.clip((np.cumsum(np.abs(rate)) * 2.0).astype(int), 0, len(src) - 1)
    y = src[idx] * np.abs(rate) / (np.abs(rate).max() + 1e-9)
    y = _bandpass(y, 300, 5000) + 0.3 * np.sin(2 * np.pi * np.cumsum(200 + 900 * np.abs(rate) / (np.abs(rate).max() + 1e-9)) / SR) * np.exp(-t * 6)
    return _norm(y) * np.minimum(t / 0.005, 1)


def _slide_whistle(f0, f1, dur):
    t = _tt(dur)
    f = f0 * (f1 / f0) ** (t / dur)
    f = f * (1 + 0.02 * np.sin(2 * np.pi * 7 * t))
    return np.sin(2 * np.pi * np.cumsum(f) / SR) * _adsr(t, 0.02, 0.05, 0.9, 0.08, dur)


def _boing(dur=0.6):
    t = _tt(dur)
    f = 180 + 260 * (1 - np.exp(-t * 18)) + 60 * np.sin(2 * np.pi * 14 * t) * np.exp(-t * 4)
    return np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-t * 5)


def _flutter(dur, seed, density=1.0):
    """Banknotes fluttering: band-passed noise chopped at paper-flap rates."""
    t = _tt(dur)
    r = np.random.default_rng(seed)
    n = _bandpass(r.standard_normal(len(t)), 1500, 7000)
    am = np.abs(np.sin(2 * np.pi * (18 + 10 * np.sin(2 * np.pi * 0.7 * t)) * t)) ** 3
    gate = np.clip(_bandpass(r.standard_normal(len(t)), None, 6) * 6 * density + 0.3, 0, 1)
    return _norm(n * am * gate)


def _birds(n, seed, density=1.0):
    y = np.zeros(n)
    r = np.random.default_rng(seed)
    for _ in range(int(n / SR * 2.2 * density)):
        i = r.integers(0, max(1, n - SR))
        f0 = r.uniform(2600, 4200)
        for k in range(r.integers(2, 6)):
            d = int(r.uniform(0.04, 0.09) * SR)
            tt = np.arange(d) / SR
            f = f0 * (1 + r.uniform(-0.25, 0.3) * tt / tt[-1])
            j = i + k * int(0.11 * SR)
            if j + d < n:
                y[j:j + d] += np.sin(2 * np.pi * np.cumsum(f) / SR) * np.sin(np.pi * tt / tt[-1]) * r.uniform(0.3, 1.0)
    return y


def _motor(dur, seed, f=110.0, roar=1.0):
    t = _tt(dur)
    y = _bandpass(_saw(f * (1 + 0.01 * np.sin(2 * np.pi * 3 * t)), t), None, 1800) * 0.5
    y += roar * _bandpass(np.random.default_rng(seed).standard_normal(len(t)), 300, 4000) * 0.7
    return _norm(y)


def _counter_machine(dur):
    t = _tt(dur)
    clicks = np.zeros_like(t)
    rate = 32.0
    for k in range(int(dur * rate)):
        i = int(k / rate * SR)
        m = min(300, len(t) - i)
        clicks[i:i + m] += np.random.default_rng(k).standard_normal(m) * np.exp(-np.arange(m) / 40.0)
    hum = np.sin(2 * np.pi * 120 * t) * 0.3 + _bandpass(np.random.default_rng(9).standard_normal(len(t)), 200, 1200) * 0.2
    return _norm(_bandpass(clicks, 1200, 8000) + hum) * np.minimum(t / 0.05, 1) * np.clip((dur - t) / 0.08, 0, 1)


def _beep(f=1800.0, dur=0.12):
    t = _tt(dur)
    return np.sin(2 * np.pi * f * t) * _adsr(t, 0.004, 0.01, 0.9, 0.02, dur)


def _sad_trombone():
    """The descending 'wah wah wah waaah'."""
    notes = [(58, 0.32), (57, 0.32), (56, 0.32), (55, 1.1)]
    out = []
    for k, (m, d) in enumerate(notes):
        t = _tt(d)
        vib = 1 + (0.025 * np.sin(2 * np.pi * 6 * t) * np.clip((t - 0.25) / 0.2, 0, 1) if k == 3 else 0)
        y = _saw(_mtof(m) * vib, t, k * 0.1)
        y = _sweep_bp(y, lambda tc: 350 + 700 * abs(math.sin(math.pi * tc / 0.32)) if k < 3 else 350 + 600 * abs(math.sin(tc * 9)), q=1.2, block=1024)
        out.append(y * _adsr(t, 0.03, 0.05, 0.85, 0.06, d))
    return _norm(np.concatenate(out))


def _choir(chord, dur, seed=0):
    t = _tt(dur)
    y = np.zeros_like(t)
    for i, m in enumerate(chord):
        for det in (-0.2, 0.0, 0.2):
            y += _saw(_mtof(m) * (1 + det / 100) * (1 + 0.004 * np.sin(2 * np.pi * 5 * t + i + det)), t, i * 0.17 + det)
    y = _bandpass(y, 500, 900) * 0.8 + _bandpass(y, 1000, 1300) * 0.5
    return _norm(y) * _adsr(t, dur * 0.4, 0.2, 0.9, dur * 0.3, dur)


def _shutter(seed):
    t = _tt(0.12)
    r = np.random.default_rng(seed)
    y = np.zeros_like(t)
    for d in (0.0, 0.055):
        i = int(d * SR)
        m = 600
        y[i:i + m] += r.standard_normal(m) * np.exp(-np.arange(m) / 60.0)
    return _bandpass(y, 1500, 9000)


def _squeak(seed):
    t = _tt(0.14)
    f = 2400 + 900 * np.sin(np.pi * t / 0.14) + np.random.default_rng(seed).uniform(-200, 200)
    return np.sin(2 * np.pi * np.cumsum(f) / SR) * np.sin(np.pi * t / 0.14) ** 2


def _scrape(seed, dur=0.5):
    t = _tt(dur)
    n = np.random.default_rng(seed).standard_normal(len(t))
    return _norm(_sweep_bp(n, lambda tc: 900 + 1600 * tc / dur, q=3.0, block=1024)) * np.sin(np.pi * t / dur)


# --- instruments and effects for this film ------------------------------------------------------------------------
def _tt2(d):
    return np.arange(int(d * SR)) / SR


def _bass_note(freq, dur, bright=900.0):
    """A dark analogue-style bass pluck (detuned saws through a falling low-pass)."""
    t = _tt2(dur)
    y = _saw(freq, t) + 0.7 * _saw(freq * 1.006, t, 0.3) + 0.5 * np.sin(2 * np.pi * freq * 0.5 * t)
    y = _bandpass(y, 30, bright)
    return _norm(y) * np.exp(-t * 5.0) * np.minimum(t / 0.004, 1) * np.minimum((dur - t) / 0.02, 1)


def _ostinato(dur, root, bpm=120.0, pattern=(0, 0, 12, 0, 7, 0, 10, 0), bright=900.0, gain_curve=None):
    """Sixteenth-note bass ostinato (the trailer pulse)."""
    out = np.zeros(int(dur * SR))
    step = 60.0 / bpm / 4
    k = 0
    tm = 0.0
    while tm < dur - 0.05:
        n = _bass_note(_mtof(root + pattern[k % len(pattern)]), step * 1.6, bright)
        g = 1.0 if gain_curve is None else gain_curve(tm / dur)
        i = int(tm * SR)
        m = min(len(n), len(out) - i)
        out[i:i + m] += n[:m] * g * (1.0 if k % 4 == 0 else 0.7)
        tm += step
        k += 1
    return _norm(out)


def _riser(dur, seed=0, f0=200.0, f1=3000.0):
    """A tension riser: noise swept upward plus a rising tone, ending abruptly."""
    t = _tt2(dur)
    n = _sweep_bp(_noise(len(t), seed, 'pink'), lambda tc: f0 + (f1 - f0) * (tc / dur) ** 2, q=3.0)
    tone = np.sin(2 * np.pi * np.cumsum(80 * 2 ** (3 * t / dur)) / SR)
    return _norm(_norm(n) * 0.7 + tone * 0.35) * (t / dur) ** 2


def _hit(seed=0, size=1.0):
    """A trailer impact: sub boom, a low brass stab, a noise crack and a long tail."""
    b = _boom(3.5 * size, 70, 28, seed)
    br = _brass([_mtof(m) for m in (38, 45, 50)], 1.2, 900)
    crack = _bandpass(_noise(int(0.4 * SR), seed + 1), 200, 6000) * np.exp(-_tt2(0.4) * 18)
    y = np.zeros(len(b))
    y += b
    y[:len(br)] += br * 0.6
    y[:len(crack)] += crack * 0.5
    return _norm(_reverb(_norm(y), 3.0, seed) * 0.6 + _norm(y) * 0.7)


def _countbeep(f=1500.0, dur=0.09):
    t = _tt2(dur)
    return np.sin(2 * np.pi * f * t) * np.minimum(t / 0.003, 1) * np.minimum((dur - t) / 0.01, 1)


def _pa(dur, seed):
    """The presenter heard through the square's PA: a reverberant, band-limited vowel murmur - no words."""
    t = _tt2(dur)
    f0 = 118 * (1 + 0.08 * np.sin(2 * np.pi * 2.3 * t + seed) + 0.05 * np.sin(2 * np.pi * 5.1 * t))
    buzz = (np.cumsum(f0) / SR) % 1.0 - 0.5
    syl = (0.5 + 0.5 * np.sin(2 * np.pi * 3.4 * t + seed)) ** 2
    y = _bandpass(buzz, 400, 2600) * syl
    return _norm(_reverb(_norm(y), 3.5, seed) * 0.8 + y * 0.3)


def _servo(dur, seed, f=900.0):
    """A camera motor turning: a whine that rises and settles."""
    t = _tt2(dur)
    ff = f * (1 + 0.3 * np.sin(np.pi * t / dur))
    y = np.sin(2 * np.pi * np.cumsum(ff) / SR) * 0.6 + _bandpass(_noise(len(t), seed), 1500, 5000) * 0.25
    return _norm(y) * np.sin(np.pi * t / dur) ** 0.7


def _hiss(dur, seed):
    t = _tt2(dur)
    return _norm(_bandpass(_noise(len(t), seed), 1200, 9000)) * np.exp(-t * 3.0) * np.minimum(t / 0.01, 1)


def _ping(f=1250.0):
    t = _tt2(1.4)
    return _norm(np.sin(2 * np.pi * f * t) * np.exp(-t * 4) + 0.3 * np.sin(2 * np.pi * 2 * f * t) * np.exp(-t * 7))


def _glitch(dur, seed):
    """Digital break-up: stuttering square-wave bursts and noise, gated."""
    rng = np.random.default_rng(seed)
    t = _tt2(dur)
    f = rng.choice([220, 440, 660, 1320, 2200], size=int(dur * 40) + 1)
    fi = f[(t * 40).astype(int)]
    sq = np.sign(np.sin(2 * np.pi * np.cumsum(fi) / SR))
    gate = (rng.random(int(dur * 40) + 1) > 0.35)[(t * 40).astype(int)]
    return _norm((sq * 0.5 + _noise(len(t), seed) * 0.5) * gate)


def _servers(n, seed):
    """Control-room bed: mains hum, fans, random data chirps."""
    t = np.arange(n) / SR
    hum = np.sin(2 * np.pi * 50 * t) + 0.4 * np.sin(2 * np.pi * 150 * t)
    fans = _norm(_bandpass(_noise(n, seed, 'pink'), 300, 3000)) * 0.5
    rng = np.random.default_rng(seed)
    chirps = np.zeros(n)
    for k in range(int(n / SR * 5)):
        i = int(rng.uniform(0, n - 0.1 * SR))
        b = _countbeep(rng.choice([1800, 2400, 3100]), 0.04)
        chirps[i:i + len(b)] += b * 0.3
    return _norm(hum * 0.3 + fans + chirps)


def _river(n, seed):
    return _norm(_sweep_bp(_noise(n, seed, 'pink'), lambda tc: 900 + 300 * math.sin(0.7 * tc), q=0.8))


def _tremolo_strings(notes, dur, seed=0):
    t = _tt2(dur)
    y = _pad([_mtof(m) for m in notes], dur, seed=seed, cutoff=2200)
    return y * (0.65 + 0.35 * np.sin(2 * np.pi * 11.0 * t))


def _heartbeat(dur, bpm=72.0):
    out = np.zeros(int(dur * SR))
    period = 60 / bpm
    tm = 0.0
    while tm < dur - 0.4:
        for dt, g in ((0.0, 1.0), (0.22, 0.6)):
            b = _boom(0.35, 60, 40, int(tm * 10))
            i = int((tm + dt) * SR)
            m = min(len(b), len(out) - i)
            out[i:i + m] += b[:m] * g
        tm += period
    return _norm(out)


def _test_tone(dur):
    t = _tt2(dur)
    return np.sin(2 * np.pi * 1000 * t) * np.minimum(t / 0.01, 1) * np.minimum((dur - t) / 0.05, 1)


def _sting(seed=0, up=True):
    """A breaking-news sting: a bright brass chord with a timpani-like hit and a short riser."""
    br = _brass([_mtof(m) for m in ((62, 69, 74, 78) if up else (57, 64, 69, 72))], 0.55, 3000)
    y = np.zeros(int(1.6 * SR))
    y[:len(br)] += br
    b = _boom(1.2, 90, 45, seed)
    y[:len(b)] += b * 0.6
    return _norm(_reverb(_norm(y), 1.8, seed) * 0.5 + _norm(y) * 0.8)


def _water(dur, seed):
    t = _tt2(dur)
    n = _bandpass(_noise(len(t), seed, 'pink'), 400, 7000)
    return _norm(n * (0.6 + 0.4 * np.abs(np.sin(2 * np.pi * 3.0 * t + seed))))


def _rotor(n, seed, rate=5.5):
    t = np.arange(n) / SR
    chop = 0.55 + 0.45 * np.sin(2 * np.pi * rate * t) ** 8
    body = _bandpass(_noise(n, seed, 'pink'), 60, 900)
    return _norm(_norm(body) * chop + 0.3 * np.sin(2 * np.pi * 38 * t))


def _notify(seed):
    """A phone notification: two quick bright tones."""
    f = (1568, 1975, 2349, 1760)[seed % 4]
    y = np.zeros(int(0.32 * SR))
    for k, (ff, dt) in enumerate(((f, 0.0), (f * 1.335, 0.09))):
        b = _countbeep(ff, 0.11) * np.exp(-_tt2(0.11) * 18)
        i = int(dt * SR)
        y[i:i + len(b)] += b
    return y


def _power_on(seed):
    """A giant screen switching on: a relay clunk, a rising electrical hum and a crackle."""
    t = _tt2(1.4)
    hum = (np.sin(2 * np.pi * 50 * t) + 0.5 * np.sin(2 * np.pi * 100 * t) + 0.25 * np.sin(2 * np.pi * 150 * t))
    hum = hum * np.minimum(t / 0.35, 1) * np.exp(-np.maximum(t - 0.6, 0) * 2.0)
    cr = _static(1.4, seed, 1.6)[:len(t)] * np.exp(-t * 3.0) * 0.5
    y = _norm(hum) * 0.7 + cr
    c = _clunk(seed)
    y[:len(c)] += c * 0.8
    return _norm(y)


def _power_down(seed):
    """The room lights going down: a falling whine and a heavy relay."""
    t = _tt2(1.2)
    f = 900 * np.exp(-t * 2.2) + 60
    wh = np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-t * 1.6)
    y = _norm(wh) * 0.6
    c = _clunk(seed + 3)
    y[:len(c)] += c
    return _norm(_reverb(_norm(y), 2.0, seed) * 0.5 + _norm(y))


def _door_slide(seed):
    """An electronic door: a pneumatic hiss, a motor and a soft chime."""
    t = _tt2(1.0)
    hiss = _bandpass(_noise(len(t), seed), 1500, 8000) * np.exp(-t * 3.5) * np.minimum(t / 0.02, 1)
    mot = np.sin(2 * np.pi * np.cumsum(220 + 160 * t) / SR) * np.sin(np.pi * np.clip(t / 0.7, 0, 1)) * 0.4
    y = _norm(hiss) * 0.7 + mot
    ch = _countbeep(1320, 0.3) * np.exp(-_tt2(0.3) * 9)
    i = int(0.55 * SR)
    y[i:i + len(ch)] += ch * 0.4
    return _norm(y)


def _swipe(seed):
    """A holographic interface swipe: a short filtered noise sweep with a sparkle."""
    t = _tt2(0.4)
    y = _sweep_bp(_noise(len(t), seed), lambda tc: 600 + 7000 * tc / 0.4, q=4.0) * np.sin(np.pi * t / 0.4)
    return _norm(y)


def _brakes(seed):
    """Tyres braking hard on asphalt."""
    t = _tt2(1.1)
    sq = _sweep_bp(_noise(len(t), seed), lambda tc: 2400 - 900 * tc, q=8.0) * np.exp(-t * 1.5) * np.minimum(t / 0.05, 1)
    rumble = _bandpass(_noise(len(t), seed + 1, 'pink'), 40, 400) * np.exp(-t * 2.5)
    return _norm(_norm(sq) * 0.35 + _norm(rumble) * 0.8)


def _music(N, cues):
    mus = np.zeros((2, N))
    S_ = {s['name']: (s['t0'], s['t1']) for s in SHOTS}
    # 0-4 s: a cold, low drone; the screen powers on; an impact as his face appears
    y = _pad([_mtof(m) for m in (37, 44, 49, 52)], 4.2, seed=1, cutoff=700)
    _place(mus, y * _env(_tt2(4.2), [(0, 0), (0.3, 0.8), (1.6, 0.8), (2.0, 1.0), (4.2, 0.3)]), 0.0, 0.3)
    _place(mus, _heartbeat(1.6, 70), 0.05, 0.25)
    cues.append((0.0, 'MUSIC: a cold low drone (C sharp minor) with a slow heartbeat bass', 'music'))
    _place(mus, _riser(0.9, 2, 150, 3500), 1.08, 0.3)
    _place(mus, _hit(2, 1.1), 1.98, 0.75)
    cues.append((1.98, 'IMPACT as the giant screen comes fully on with his face', 'music'))
    st = _tremolo_strings((49, 52, 56, 61), 2.3, 3)
    _place(mus, st * _env(_tt2(2.3), [(0, 0), (0.3, 0.7), (2.0, 0.9), (2.3, 0)]), 2.1, 0.2)
    # 4-10.45 s: the world finds out - a driving news pulse that grows with every cut
    a, b = S_['anchor'][0], S_['car'][0]
    _place(mus, _ostinato(b - a, 37, 128, pattern=(0, 0, 12, 0, 7, 0, 10, 12), bright=1300, gain_curve=lambda u: 0.5 + 0.5 * u), a, 0.34)
    for k in range(int((b - a) / 0.469)):
        _place(mus, _kick(0.3), a + k * 0.469, 0.24 + 0.1 * k / 13)
        _place(mus, _shaker(400 + k), a + k * 0.469 + 0.234, 0.06)
        if k % 2:
            _place(mus, _snare(500 + k, 0.8), a + k * 0.469, 0.08 + 0.06 * k / 13)
    for k, ch in enumerate(((49, 56, 61, 64), (45, 52, 57, 61), (47, 54, 59, 63), (44, 51, 56, 60))):
        seg = (b - a) / 4
        yy = _pad([_mtof(m) for m in ch], seg + 0.3, seed=10 + k, cutoff=1500)
        _place(mus, yy * _env(_tt2(seg + 0.3), [(0, 0), (0.15, 1), (seg, 1), (seg + 0.3, 0)]), a + k * seg, 0.26 + 0.04 * k)
    _place(mus, _sting(5, True), a + 0.02, 0.5)
    _place(mus, _sting(7, False), S_['gov'][0] + 0.02, 0.45)
    _place(mus, _riser(1.6, 6, 200, 4500), b - 1.6, 0.32)
    cues.append((a, 'MUSIC: a driving news pulse (C sharp minor, 128 bpm), kick, snare and shaker, building cut by cut', 'music'))
    cues.append((a, 'Breaking-news stings on the presenter and on the government urgent report', 'music'))
    # 10.45 s: the pulse stops dead; low bass under the car's arrival
    _place(mus, _boom(2.5, 50, 28, 9), b, 0.45)
    y = _pad([_mtof(m) for m in (25, 32, 37)], 2.3, seed=12, cutoff=300)
    _place(mus, y * _env(_tt2(2.3), [(0, 0), (0.1, 1), (2.0, 1), (2.3, 0)]), b, 0.4)
    cues.append((b, 'MUSIC: the pulse stops dead; a sub-bass boom and a low drone as the government car arrives', 'music'))
    # 12.6-19.15 s: the facility - vast, cold, reverberant; a choir swell when the hall opens up
    a, b = S_['enter'][0], S_['timeline'][0]
    for k, ch in enumerate(((37, 44, 49, 56, 61), (35, 42, 47, 54, 59), (33, 40, 45, 52, 57))):
        seg = (b - a) / 3
        yy = _choir(ch, seg + 0.8, seed=30 + k) * 0.55 + _pad([_mtof(m) for m in ch], seg + 0.8, seed=34 + k, cutoff=1400) * 0.7
        _place(mus, _reverb(yy * _env(_tt2(seg + 0.8), [(0, 0), (0.6, 1), (seg, 1), (seg + 0.8, 0)]), 3.5, 30 + k) * 0.8, a + k * seg, 0.3)
    j, tm = 0, a + 0.2
    while tm < b - 0.3:
        _place(mus, _pluck(_mtof((73, 76, 80, 85, 80, 76)[j % 6]), 1.2, 0.6), tm, 0.06, pan=0.4 * math.sin(j))
        tm += 0.469
        j += 1
    cues.append((a, 'MUSIC: vast and cold - choir and pads in a long reverb, a slow glassy arpeggio', 'music'))
    # 19.15-23.5 s: the timeline - a ticking pulse and rising strings; a stab when his photo is found
    a, b = S_['timeline'][0], S_['turn'][0]
    for k in range(int((b - a) / 0.234)):
        _place(mus, _tick(k, 1.0), a + k * 0.234, 0.07)
    st = _tremolo_strings((49, 52, 56, 61, 64), b - a + 0.5, 40)
    _place(mus, st * _env(_tt2(b - a + 0.5), [(0, 0), (0.6, 0.5), (b - a, 1.0), (b - a + 0.5, 0.6)]), a, 0.26)
    _place(mus, _hit(41, 0.7), 21.6, 0.5)
    cues.append((a, 'MUSIC: a clock-like ticking pulse and rising tremolo strings over the timeline', 'music'))
    cues.append((21.6, 'A stab as the timeline finds the one man it missed - his photo', 'music'))
    # 23.5-27.9 s: rising suspense into the symbol
    a, b = S_['turn'][0], 27.88
    _place(mus, _heartbeat(b - a, 84), a, 0.35)
    _place(mus, _riser(b - 25.3, 50, 120, 6000), 25.3, 0.38)
    y = _choir((37, 38, 44), b - 25.3 + 0.2, seed=51) * 0.7 + _pad([_mtof(m) for m in (25, 37, 38)], b - 25.3 + 0.2, seed=52, cutoff=500)
    _place(mus, y * _env(_tt2(b - 25.3 + 0.2), [(0, 0), (0.4, 1), (b - 25.3, 1), (b - 25.3 + 0.2, 0)]), 25.3, 0.36)
    _place(mus, _boom(3.0, 45, 24, 53), 25.3, 0.55)
    cues.append((a, 'MUSIC: rising suspense - a faster heartbeat bass, then an eerie dissonant choir and a long riser under the symbol', 'music'))
    cues.append((25.3, 'A deep sub boom as the symbol appears', 'music'))
    # 27.9 s: everything cuts on the glitch; one last low hit under PART 3?
    i = int(27.9 * SR)
    mus[:, i:] *= 0.0
    _place(mus, _hit(60, 0.9), 28.22, 0.6)
    cues.append((27.9, 'MUSIC CUTS on the digital glitch; one last low hit under "PART 3?" (28.2 s), then its tail', 'music'))
    return mus


def stage_audio():
    N = int(DURATION * SR)
    t = np.arange(N) / SR
    amb = np.zeros((2, N))
    sfx = np.zeros((2, N))
    cues = []

    def cue(time, what, layer='sfx'):
        cues.append((time, what, layer))
    S_ = {s['name']: (s['t0'], s['t1']) for s in SHOTS}
    music = _music(N, cues)

    def bed(names, fn, gain, what, pan=0.0):
        for nm in names:
            a, b = S_[nm]
            n = int((b - a) * SR) + 1
            y = fn(n, abs(hash(nm)) % 1000) * _env(np.arange(n) / SR, [(0, 0), (0.03, 1), ((b - a) - 0.03, 1), (b - a, 0)])
            _place(amb, y, a, gain, pan=pan)
        cue(S_[names[0]][0], what, 'ambience')
    bed(['walk', 'billboard', 'lookup', 'car'], lambda n, s: _wind(n, s, 150, 900, 0.2) * 0.5 + _engine(n, s, 40.0) * 0.3 + _crowd(n, s, 0.3) * 0.2,
        0.16, 'Street: wind, distant traffic, a few far-off voices - eerily quiet')
    bed(['anchor'], lambda n, s: _crowd(n, s, 0.8) * 0.5 + _servers(n, s) * 0.5, 0.16, 'Newsroom: busy murmur, keyboards, phones')
    bed(['screens', 'crowd'], lambda n, s: _crowd(n, s, 1.8), 0.32, 'The square: a huge crowd murmuring at the giant screens')
    bed(['gov'], lambda n, s: _servers(n, s) * 0.6 + _hum_bed(n, s, 50.0, 0.2) * 0.4, 0.14, 'Situation room: hum, data chirps')
    bed(['scidata'], lambda n, s: _servers(n, s), 0.16, 'Lab: equipment hum and bleeps')
    bed(['enter', 'welcome'], lambda n, s: _hum_bed(n, s, 55.0, 0.15) * 0.5 + _servers(n, s) * 0.5, 0.15,
        'Facility: a deep air-handling hum, servers, distant interface bleeps')
    bed(['timeline', 'notice', 'turn', 'symbol', 'stare'], lambda n, s: _hum_bed(n, s, 55.0, 0.1), 0.1, 'Research room: a low hum')
    # effects
    for k in range(4):
        _place(sfx, _step(10 + k), 0.12 + k * 0.48, 0.2, pan=0.1)
    cue(0.12, 'His footsteps on the pavement')
    _place(sfx, _power_on(3), 1.62, 0.4)
    cue(1.62, 'The giant screen switches on: a relay clunk, a rising electrical hum and crackle')
    _place(sfx, _static(0.35, 4, 1.4), 1.62, 0.18)
    for nm in ('billboard', 'lookup', 'anchor', 'screens', 'crowd', 'gov', 'scidata', 'car', 'enter', 'welcome', 'timeline', 'notice', 'turn', 'symbol', 'stare'):
        _place(sfx, _whoosh(0.35, len(nm)), S_[nm][0] - 0.15, 0.14 if nm not in ('billboard',) else 0.3)
    cue(1.35, 'A whoosh on every cut (a big one on the push to the giant screen)')
    rng = np.random.default_rng(5)
    tm = 4.3
    while tm < 10.2:
        _place(sfx, _notify(int(rng.integers(4))), tm, 0.08 + 0.06 * rng.random(), pan=rng.uniform(-0.6, 0.6))
        tm += rng.uniform(0.18, 0.55)
    cue(4.3, 'Phone notifications everywhere, faster and faster')
    _place(sfx, _static(0.25, 9, 1.0), S_['anchor'][0], 0.18)
    _place(sfx, _static(0.25, 10, 1.0), S_['screens'][0], 0.16)
    for k in range(3):
        _place(sfx, _countbeep(880, 0.25), S_['gov'][0] + 0.15 + k * 0.5, 0.12)
    cue(S_['gov'][0] + 0.15, 'An urgent alert tone in the situation room')
    for k in range(5):
        _place(sfx, _countbeep(2000 + 300 * k, 0.06), S_['scidata'][0] + 0.3 + k * 0.45, 0.08)
    # the car
    a = S_['car'][0]
    n = int(1.9 * SR)
    eng = _engine(n, 21, 44.0) * _env(np.arange(n) / SR, [(0, 0.3), (0.6, 1.0), (1.35, 0.7), (1.9, 0.15)])
    _place(sfx, eng, a, 0.45, pan=-0.3)
    _place(sfx, _whoosh(0.6, 22), a + 0.35, 0.3, pan=-0.2)
    _place(sfx, _brakes(23), a + 0.55, 0.3)
    _place(sfx, _door_slide(24), 12.0, 0.35, pan=-0.1)
    cue(a, 'The government car: engine, a pass-by whoosh, hard braking; its door slides open (12.0 s)')
    # the facility
    _place(sfx, _door_slide(25), S_['enter'][0] + 0.05, 0.35)
    cue(S_['enter'][0] + 0.05, 'Electronic doors open into the facility')
    for k in range(5):
        st_ = np.concatenate([_step(30 + k), np.zeros(int(1.2 * SR))])
        y = _reverb(st_, 2.5, k) * 0.6
        y[:len(st_)] += st_
        _place(sfx, _norm(y), S_['enter'][0] + 0.3 + k * 0.52, 0.25)
    cue(S_['enter'][0] + 0.3, 'Footsteps echoing across the hall')
    for k in range(4):
        _place(sfx, _countbeep(2600 - 200 * k, 0.05), S_['enter'][0] + 0.8 + k * 0.6, 0.07, pan=0.5 * math.sin(k))
    _place(sfx, _door_slide(26), S_['welcome'][0] + 0.05, 0.25)
    cue(S_['welcome'][0] + 0.05, 'The glass research room door; interface bleeps')
    for k, tm in enumerate((19.4, 19.95, 20.5)):
        _place(sfx, _swipe(40 + k), tm, 0.2, pan=0.3)
    cue(19.4, 'Interface swipes as the scientist scrolls the timeline')
    _place(sfx, _glitch(0.25, 44), 21.58, 0.12)
    for k in range(3):
        _place(sfx, _countbeep(1175, 0.12), 21.7 + k * 0.3, 0.16)
    cue(21.6, 'A data glitch and a triple alert beep: ANOMALY - SUBJECT 001')
    _place(sfx, _power_down(50), 24.0, 0.4)
    cue(24.0, 'The lights go down: a falling whine and a heavy relay')
    _place(sfx, _glitch(0.2, 51), 25.25, 0.16)
    _place(sfx, _glitch(0.4, 60), 27.86, 0.45)
    _place(sfx, _static(0.4, 61, 2.0), 27.86, 0.35)
    cue(27.86, 'DIGITAL GLITCH: stuttering square-wave bursts and static as the picture breaks up')
    _place(sfx, _glitch(0.12, 62), 29.7, 0.2)

    vo = np.zeros(N)
    vpath = os.path.join(ROOT, 'audio', 'narration.wav')
    if os.path.exists(vpath):
        with wave.open(vpath) as w:
            a_ = np.frombuffer(w.readframes(w.getnframes()), np.int16).astype(np.float64) / 32768
        vo[:min(N, len(a_))] = a_[:N]
    env = np.abs(vo)
    k = int(0.03 * SR)
    env = np.convolve(env, np.ones(k) / k, mode='same')
    env = np.clip(env / (env.max() + 1e-9) * 4, 0, 1)
    rel_k = int(0.3 * SR)
    env = np.maximum.reduce([np.roll(env, j) for j in range(0, rel_k, rel_k // 12)])
    duck_m = 1 - 0.55 * env
    duck_a = 1 - 0.45 * env
    music_n, amb_n, sfx_n = (x / (np.abs(x).max() + 1e-9) for x in (music, amb, sfx))
    bedm = 0.6 * music_n + 0.35 * amb_n + 0.6 * sfx_n
    with_voice = 0.6 * music_n * duck_m + 0.35 * amb_n * duck_a + 0.6 * sfx_n * duck_a + np.stack([vo, vo]) * (1.6 / (np.abs(vo).max() + 1e-9))
    end_fade = np.clip((DURATION - t) / 0.15, 0, 1)
    os.makedirs(os.path.join(ROOT, 'audio'), exist_ok=True)
    outs = {}
    for name, mix in (('mix_with_voice', with_voice), ('mix_no_voice', bedm), ('music_sfx_stem', bedm)):
        mix = mix * end_fade
        mix = np.tanh(mix / (np.abs(mix).max() + 1e-9) * 1.2) * 0.89
        p = os.path.join(ROOT, 'audio', name + '.wav')
        with wave.open(p, 'wb') as w:
            w.setnchannels(2)
            w.setsampwidth(2)
            w.setframerate(SR)
            w.writeframes((np.clip(mix.T, -1, 1) * 32767).astype(np.int16).tobytes())
        outs[name] = p
    for name in ('mix_with_voice', 'mix_no_voice'):
        p = outs[name]
        tmp = p.replace('.wav', '_ln.wav')
        try:
            r = subprocess.run(['ffmpeg', '-hide_banner', '-i', p, '-af', 'loudnorm=I=-14:TP=-1.5:LRA=20:print_format=json', '-f', 'null', '-'],
                               check=True, capture_output=True, text=True).stderr
            js = json.loads(r[r.rindex('{'):r.rindex('}') + 1])
            af = (f"loudnorm=I=-14:TP=-1.5:LRA=20:linear=true:measured_I={js['input_i']}:measured_TP={js['input_tp']}:"
                  f"measured_LRA={js['input_lra']}:measured_thresh={js['input_thresh']}:offset={js['target_offset']}")
            subprocess.run(['ffmpeg', '-y', '-loglevel', 'error', '-i', p, '-af', af, '-ar', str(SR), tmp], check=True)
            os.replace(tmp, p)
        except (OSError, subprocess.CalledProcessError) as e:
            print('loudnorm skipped:', e)
    write_sound_design(cues)
    print('audio written:', ', '.join(outs))


def write_sound_design(cues):
    L = ['WHAT IF YOU WERE THE ONLY MAN ALIVE? PART 2 - SOUND DESIGN, MUSIC AND TIMING',
         '=' * 60, '',
         'Everything below is synthesised by code in animation.py --stage audio (numpy only: oscillators, filtered noise,',
         'envelopes, convolution reverb). No samples, recordings, stock sound or copyrighted music. The narration is a',
         'synthetic voice (Kokoro-82M, voice bm_george) made by tools/voiceover.py. Music, ambience and effects duck under',
         'the voice so the narration always stays on top.',
         '',
         'THE IDEA: bigger than Part 1. A cold drone on an eerily quiet street; the giant screen powers on with a relay clunk',
         'and an electrical hum, and an impact lands as his face appears. The world finds out over a driving news pulse with',
         'stings, static and a storm of phone notifications. The pulse stops dead for the black car (engine, braking, a',
         'sliding door). The facility is vast and cold: electronic doors, echoing footsteps, interface bleeps, a choir in a',
         'long reverb. The timeline ticks; a stab and alert beeps find his photo. Then rising suspense: a faster heartbeat,',
         'the lights powering down, a sub boom and a dissonant choir under the symbol - and a digital glitch cuts everything',
         'to one last low hit under PART 3?',
         '',
         'Files: audio/mix_with_voice.wav (final mix, -14 LUFS), audio/mix_no_voice.wav (music + sound only, -14 LUFS),',
         'audio/narration.wav (voice only).',
         '', 'CUE SHEET (generated)', '-' * 60]
    vt = os.path.join(BUILD, 'vo_timing.json')
    if os.path.exists(vt):
        with open(vt) as fh:
            for ln in json.load(fh)['lines']:
                cues.append((ln['start'], f'NARRATION: "{ln["text"]}" (to {ln["end"]:.2f} s)', 'voice'))
    for tm, what, layer in sorted(cues):
        L.append(f'{tm:6.2f} s  [{layer:9s}] {what}')
    L += ['', 'MUSIC GUIDE (if you re-score it in CapCut or another editor)', '-' * 60,
          '- 0-2 s: a cold, low drone; a big hit when the giant screen comes on (2.0 s).',
          '- 4-10.5 s: news-channel energy - a driving minor-key pulse (120-130 bpm) that builds with every cut.',
          '- 10.5 s: stop the pulse dead for the car; low bass only.',
          '- 12.6-19 s: something vast and cold (pads, choir, long reverb) for the facility.',
          '- 19-23.5 s: a ticking pulse and rising strings; a stab at 21.6 s when his photo is highlighted.',
          '- 23.5-27.9 s: rising suspense; cut everything on the glitch at 27.9 s, one low hit under PART 3?.',
          '- Keep the narration 10-15 dB above the music; YouTube Shorts plays back at about -14 LUFS.',
          '- Use only music you have the rights to (your own, a licensed library, or YouTube Audio Library tracks).']
    with open(os.path.join(ROOT, 'sound_design.txt'), 'w') as fh:
        fh.write('\n'.join(L) + '\n')


# the generic helpers this file uses that came with the last film's sound set
def _hum(dur, f=55.0):
    t = np.arange(int(dur * SR)) / SR
    y = np.sin(2 * np.pi * f * t) + 0.5 * np.sin(2 * np.pi * 1.5 * f * t + 0.3) + 0.25 * np.sin(2 * np.pi * 2.01 * f * t)
    return y * (0.7 + 0.3 * np.sin(2 * np.pi * 0.5 * t))


def _hum_bed(n, seed, f=50.0, hiss=0.3):
    t = np.arange(n) / SR
    y = np.sin(2 * np.pi * f * t) + 0.5 * np.sin(2 * np.pi * 2 * f * t) + 0.25 * np.sin(2 * np.pi * 3 * f * t)
    y = y * (0.85 + 0.15 * np.sin(2 * np.pi * 0.3 * t))
    return _norm(y + hiss * _norm(_bandpass(_noise(n, seed, 'pink'), 2000, 9000)))


def _wind(n, seed, lo=150, hi=1400, gust=0.35):
    t = np.arange(n) / SR
    g = 0.65 + gust * np.sin(2 * np.pi * 0.11 * t + seed) + 0.2 * np.sin(2 * np.pi * 0.37 * t + 2 * seed)
    y = _sweep_bp(_noise(n, seed, 'pink'), lambda tc: lo + (hi - lo) * (0.5 + 0.5 * math.sin(0.4 * tc + seed)), q=1.4)
    return _norm(y) * np.clip(g, 0.15, 1.3)

# ============================================================================
# Stage: edit - Video Sequence Editor: upscale, glitches, vignette, grain, titles, LIVE bug, key captions, captions, audio, encode
# ============================================================================
TITLE_STYLE = {
    #          font         size  colour                         y (from bottom)  outline  plate
    'hero':   (FONT_TITLE, 112, (1.0, 1.0, 1.0, 1.0), 0.815, 0.06, True),
    'big':    (FONT_TITLE, 150, (1.0, 0.74, 0.16, 1.0), 0.775, 0.05, False),
    'label':  (FONT_TITLE, 78, (1.0, 1.0, 1.0, 1.0), 0.815, 0.07, True),
    'item':   (FONT_TITLE, 60, (1.0, 1.0, 1.0, 1.0), 0.855, 0.07, True),
    'tag':    (FONT_TITLE, 34, (0.95, 0.92, 0.85, 1.0), 0.905, 0.0, True),
    'count':  (FONT_TITLE, 330, (1.0, 0.74, 0.16, 1.0), 0.775, 0.035, False),
}
_FONTS = {}


def font(path):
    if path not in _FONTS:
        _FONTS[path] = bpy.data.fonts.load(path, check_existing=True)
    return _FONTS[path]


def save_png(path, arr):
    h, w = arr.shape[:2]
    im = bpy.data.images.new(os.path.basename(path), w, h, alpha=True)
    im.pixels.foreach_set(np.ascontiguousarray(arr[::-1]).astype(np.float32).ravel())
    im.filepath_raw = path
    im.file_format = 'PNG'
    im.save()
    bpy.data.images.remove(im)


def make_overlays():
    d = os.path.join(BUILD, 'overlays')
    os.makedirs(d, exist_ok=True)
    vpath = os.path.join(d, 'vignette.png')
    if not os.path.exists(vpath):
        h, w = 960, 540
        y, x = np.mgrid[0:h, 0:w]
        r = np.sqrt(((x - w / 2) / (w / 2)) ** 2 * 0.9 + ((y - h / 2) / (h / 2)) ** 2)
        a = np.clip((r - 0.6) / 0.75, 0, 1) ** 1.7 * 0.6
        arr = np.zeros((h, w, 4))
        arr[..., 3] = a
        save_png(vpath, arr)
    grains = []
    rng = np.random.default_rng(5)
    for k in range(24):
        gp = os.path.join(d, f'grain_{k:02d}.png')
        if not os.path.exists(gp):
            g = rng.normal(0.5, 0.1, (960, 540))
            save_png(gp, np.stack([g, g, g, np.ones_like(g)], -1).clip(0, 1))
        grains.append(os.path.basename(gp))
    return vpath, d, grains


def key_alpha(strip, pts):
    for f, a in pts:
        strip.blend_alpha = a
        strip.keyframe_insert('blend_alpha', frame=f)


def add_text(se, name, text, t0, t1, style, channel, fade=4, rise=0.01, y=None):
    fnt, size, col, y0, outline, plate = TITLE_STYLE[style]
    y = y0 if y is None else y
    f0, f1 = frame(t0), frame(t1)
    st = se.sequences.new_effect(name=name, type='TEXT', channel=channel, frame_start=f0, frame_end=f1)
    st.text = text
    st.font = font(fnt)
    st.font_size = size
    st.color = col
    st.align_x = 'CENTER'
    st.align_y = 'CENTER'
    st.wrap_width = 0.95
    st.use_shadow = True
    st.shadow_color = (0, 0, 0, 0.8)
    st.shadow_blur = 0.35
    st.shadow_offset = 0.035
    if outline > 0:
        st.use_outline = True
        st.outline_color = (0, 0, 0, 1)
        st.outline_width = outline
    if plate:
        # a dark plate keeps light text readable over busy, bright backgrounds
        st.use_box = True
        st.box_color = (0.02, 0.02, 0.02, 0.62 if style != 'tag' else 0.7)
        st.box_margin = 0.014
    st.blend_type = 'ALPHA_OVER'
    fade = min(fade, max(1, (f1 - f0) // 3))
    key_alpha(st, [(f0, 0.0), (f0 + fade, 1.0), (f1 - fade, 1.0), (f1, 0.0)])
    st.location = (0.5, y - rise)
    if rise > 0:
        st.keyframe_insert('location', frame=f0)
        st.location = (0.5, y)
        st.keyframe_insert('location', frame=f0 + fade * 2)
    return st


def ensure_captions():
    if not os.path.exists(os.path.join(BUILD, 'captions', 'index.json')):
        py = os.environ.get('SHORTS_PY', '/opt/shorts/venv/bin/python')
        subprocess.run([py, os.path.join(ROOT, 'tools', 'captions.py')], check=True)
    with open(os.path.join(BUILD, 'captions', 'index.json')) as fh:
        return json.load(fh)


def stage_edit():
    frames_dir = ARGS.out
    files = sorted(f for f in os.listdir(frames_dir) if f.startswith('f_') and f.endswith('.png')) if os.path.isdir(frames_dir) else []
    if not files:
        raise SystemExit('no rendered frames in ' + frames_dir)
    fset = set(files)
    missing = [f for f in range(1, RENDER_END + 1) if f'f_{f:04d}.png' not in fset]
    if missing:
        print(f'WARNING: {len(missing)} frames missing (first {missing[:5]}); they will show as black')
    caps = None if ARGS.no_voice else ensure_captions()
    bpy.ops.wm.read_factory_settings(use_empty=True)
    sc = bpy.context.scene
    sc.name = 'Edit'
    sc.render.resolution_x, sc.render.resolution_y = RES
    sc.render.resolution_percentage = 100
    sc.render.fps = FPS
    sc.frame_start, sc.frame_end = 1, LAST_FRAME
    sc.view_settings.view_transform = 'Standard'     # frames are already tone-mapped (AgX) in the render
    sc.view_settings.look = 'None'
    se = sc.sequence_editor_create()
    first = 1
    while f'f_{first:04d}.png' not in fset:
        first += 1
    img = se.sequences.new_image('Frames', os.path.join(frames_dir, f'f_{first:04d}.png'), channel=1, frame_start=first, fit_method='FIT')
    for f in range(first + 1, RENDER_END + 1):
        img.elements.append(f'f_{f:04d}.png')
    img.transform.filter = 'CUBIC_MITCHELL'
    vpath, gdir, grains = make_overlays()
    vg = se.sequences.new_image('Vignette', vpath, channel=2, frame_start=1, fit_method='STRETCH')
    vg.frame_final_end = LAST_FRAME + 1
    vg.blend_type = 'ALPHA_OVER'
    gr = se.sequences.new_image('Grain', os.path.join(gdir, grains[0]), channel=3, frame_start=1, fit_method='STRETCH')
    for f in range(2, LAST_FRAME + 1):
        gr.elements.append(grains[(f - 1) % len(grains)])
    gr.blend_type = 'OVERLAY'
    gr.blend_alpha = 0.16
    # broadcast-style glitches on some cuts and moments: a displaced ghost copy of the picture plus a flash
    def glitch(name, t0, t1, dx=0.03, flash=0.35):
        f0, f1 = frame(t0), max(frame(t1), frame(t0) + 1)
        for j, (sx, ch_) in enumerate(((1, 4), (-1, 5))):
            if f'f_{f0:04d}.png' not in fset:
                continue
            g = se.sequences.new_image(f'{name}_g{j}', os.path.join(frames_dir, f'f_{f0:04d}.png'), channel=ch_, frame_start=f0, fit_method='FIT')
            for f in range(f0 + 1, f1):
                g.elements.append(f'f_{f:04d}.png')
            g.transform.offset_x = sx * dx * RES[0] * (1 if j == 0 else 0.6)
            g.transform.offset_y = (-1) ** j * 6
            g.blend_type = 'SCREEN' if j == 0 else 'DIFFERENCE'
            g.blend_alpha = 0.45 if j == 0 else 0.25
            g.color_saturation = 1.8
        if flash > 0:
            fl = se.sequences.new_effect(f'{name}_fl', type='COLOR', channel=6, frame_start=f0, frame_end=f0 + 2)
            fl.color = (0.85, 0.95, 1.0)
            fl.blend_type = 'ADD'
            fl.blend_alpha = flash
    G = [('g_board', 1.62, 1.75, 0.02, 0.25), ('g_anchor', SHOT['anchor']['t0'], SHOT['anchor']['t0'] + 0.1, 0.03, 0.35),
         ('g_screens', SHOT['screens']['t0'], SHOT['screens']['t0'] + 0.08, 0.025, 0.25),
         ('g_gov', SHOT['gov']['t0'], SHOT['gov']['t0'] + 0.1, 0.03, 0.3), ('g_sci', SHOT['scidata']['t0'], SHOT['scidata']['t0'] + 0.07, 0.02, 0.2),
         ('g_anom', 21.6, 21.7, 0.02, 0.2), ('g_sym', 25.3, 25.4, 0.03, 0.25),
         ('g_end1', 27.86, 28.0, 0.05, 0.45), ('g_end2', 28.0, 28.12, -0.08, 0.3), ('g_end3', 28.12, 28.22, 0.11, 0.6),
         ('g_tail', 29.7, 29.76, 0.03, 0.15)]
    for name_, a_, b_, dx_, fl_ in G:
        glitch(name_, a_, b_, dx_, fl_)
    # after the final glitch the picture drops almost to black under PART 3?
    dk = se.sequences.new_effect('Dark', type='COLOR', channel=7, frame_start=frame(28.22), frame_end=LAST_FRAME + 1)
    dk.color = (0.0, 0.0, 0.0)
    dk.blend_type = 'ALPHA_OVER'
    key_alpha(dk, [(frame(28.22), 0.55), (frame(28.6), 0.7), (LAST_FRAME, 0.75)])
    # a broadcast "LIVE" bug while the world watches (scene 2)
    for k, (a_, b_) in enumerate(((SHOT['anchor']['t0'], SHOT['crowd']['t1']),)):
        st = se.sequences.new_effect(f'Live{k}', type='TEXT', channel=8, frame_start=frame(a_), frame_end=frame(b_))
        st.text = '  LIVE   GLOBAL 24  '
        st.font = font(FONT_TITLE)
        st.font_size = 40
        st.color = (1, 1, 1, 1)
        st.align_x = 'LEFT'
        st.align_y = 'CENTER'
        st.location = (0.06, 0.945)
        st.use_box = True
        st.box_color = (0.85, 0.08, 0.06, 0.92)
        st.box_margin = 0.01
        st.blend_type = 'ALPHA_OVER'
    ch = 9
    for k, tl in enumerate(TIMING['titles']):
        for j, line in enumerate(tl['text'].split('|')):
            st = add_text(se, f'Title{k}_{j}', line, tl['start'], tl['end'], tl['style'], ch + (k % 4) * 2 + j,
                          rise=0.0 if tl['style'] == 'tag' else 0.01, y=tl.get('y'))
            if j:
                dy = j * TITLE_STYLE[tl['style']][1] * 1.25 / RES[1]
                fc = sc.animation_data.action.fcurves if sc.animation_data and sc.animation_data.action else []
                for fcu in fc:
                    if fcu.data_path == f'sequence_editor.sequences_all["{st.name}"].location' and fcu.array_index == 1:
                        for kp in fcu.keyframe_points:
                            kp.co[1] -= dy
                            kp.handle_left[1] -= dy
                            kp.handle_right[1] -= dy
                st.location = (0.5, st.location[1] - dy)
    if caps:
        cdir = os.path.join(BUILD, 'captions')
        words = sorted(c['start'] for c in caps if not c.get('key'))
        for k, c in enumerate(caps):
            end = c['end']
            if c.get('key'):    # a key caption gives way to the next spoken caption
                nxt = [w for w in words if c['start'] + 0.3 < w < end]
                end = min([end] + nxt)
            f0, f1 = frame(c['start']), max(frame(end), frame(c['start']) + 1)
            st = se.sequences.new_image(f'Cap{k}', os.path.join(cdir, c['file']), channel=(22 if c.get('key') else 20 + k % 2),
                                        frame_start=f0, fit_method='ORIGINAL')
            st.frame_final_end = f1
            st.blend_type = 'ALPHA_OVER'
            if c.get('key'):
                # key moments pop in: a quick scale-down from 115 % with a fade, and fade out
                key_alpha(st, [(f0, 0.0), (f0 + 3, 1.0), (f1 - 4, 1.0), (f1, 0.0)])
                st.transform.origin = (0.5, 0.36)          # scale about the caption itself
                for fr, sc_ in ((f0, 1.15), (f0 + 5, 1.0)):
                    st.transform.scale_x = st.transform.scale_y = sc_
                    st.transform.keyframe_insert('scale_x', frame=fr)
                    st.transform.keyframe_insert('scale_y', frame=fr)
    apath = os.path.join(ROOT, 'audio', 'mix_no_voice.wav' if ARGS.no_voice else 'mix_with_voice.wav')
    se.sequences.new_sound('Audio', apath, channel=24, frame_start=1)
    r = sc.render
    r.use_sequencer = True
    r.use_compositing = False
    r.image_settings.file_format = 'FFMPEG'
    ff = r.ffmpeg
    ff.format = 'MPEG4'
    ff.codec = 'H264'
    ff.constant_rate_factor = 'NONE'
    ff.video_bitrate = ARGS.bitrate
    ff.maxrate = int(ARGS.bitrate * 1.125)
    ff.minrate = 0
    ff.buffersize = 18000
    ff.gopsize = 30
    ff.ffmpeg_preset = 'GOOD'
    ff.audio_codec = 'AAC'
    ff.audio_bitrate = 192
    ff.audio_mixrate = 48000
    ff.audio_channels = 'STEREO'
    name = ARGS.output or ('final_video_no_voice.mp4' if ARGS.no_voice else 'final_video.mp4')
    out = os.path.join(ROOT, name) if name == 'final_video.mp4' else os.path.join(ROOT, 'renders', name)
    tmp = os.path.join(BUILD, 'edit_' + name)
    if ARGS.frames:
        a, b = (int(x) for x in ARGS.frames.split('-'))
        sc.frame_start, sc.frame_end = a, b
    r.filepath = tmp
    r.use_file_extension = False
    bpy.ops.render.render(animation=True)
    try:
        subprocess.run(['ffmpeg', '-y', '-loglevel', 'error', '-i', tmp, '-c', 'copy', '-movflags', '+faststart', out], check=True)
        os.remove(tmp)
    except (OSError, subprocess.CalledProcessError):
        os.replace(tmp, out)
    print('wrote', out)

def main():
    os.makedirs(BUILD, exist_ok=True)
    if ARGS.stage in ('render', 'all'):
        stage_render()
    if ARGS.stage in ('audio', 'all'):
        stage_audio()
    if ARGS.stage in ('edit', 'all'):
        stage_edit()


if __name__ == '__main__':
    main()
